/* ÇEVİRİ bg · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("bg","olay",{
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Договорът от Серав — подновяване на мира с Иран", "e778aca8"], "d": ["Договорът от Серав, сключен с Иран след разгрома при Пюл-и Шикесте, до голяма степен потвърди условията на договора на Насух паша от 1612; годишното количество коприна, което сефевидите щяха да изпращат, бе намалено от двеста на сто товара. Така приключи втората фаза на източните войни, започнали през 1603 Мирът нямаше да бъде дълготраен и със загубата на Багдад през 1623 войната щеше да пламне отново.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Походът срещу Хотин и Хотинският договор", "bc4c823c"], "d": ["Срещу голямата армия, командвана лично от Осман II, укрепеният лагер, създаден от Ходкевич пред Хотин, не можа да бъде преодолян и след месеци атаки не се получи резултат. С договора, подписан на 9 октомври, река Днестър бе приета за граница, а поляците се задължиха да възпрат казашките набези. Макар да бе представен като победа, походът, който не даде резултат, затвърди недоверието на младия падишах към еничарите и намерението му да прочисти оджака.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["Отнемането на Ормуз от португалците", "93e5f6cf"], "d": ["Сефевидските сили обсадиха и си върнаха Ормуз, държан от португалците от 1515; Кешм и крайбрежният Gamrûn (Bender Abbas) също преминаха под сефевидско управление и търговията на Залива се премести към новото пристанище.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Второто сваляне на Мустафа I и възцаряването на Мурад IV", "1b3a9e74"], "d": ["Мустафа I, качен за втори път на трона след убийството на Осман II, бе свален отново след една година и три месеца и единайсетгодишният Мурад IV бе провъзгласен за падишах. През първите девет години държавата бе управлявана фактически от майка му Кьосем султан и дворцовите сановници. От 1632 Мурад IV лично пое управлението и започна период на строга централизация.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Загубата на Багдад в полза на сефевидите", "db81be0c"], "d": ["След пазарлъците на въстаналия в Багдад Бекир субашъ със сефевидите синът му Дервиш Мехмед, който защитаваше вътрешната крепост, предаде града на силите на шаха Абас. Загубата на един от символните градове на халифското наследство и на по-голямата част от Ирак предизвика голямо възмущение в Истанбул. Възвръщането на Багдад щеше да бъде единствената цел на османската политика на изток в продължение на петнайсет години.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Потушаването на бунта на Абаза Мехмед паша с център Ерзурум", "e6da2729"], "d": ["Ерзурумският бейлербей Абаза Мехмед паша, въстанал срещу еничарите под предлог за отмъщение за убийството на Осман II, години наред държеше Източна Анатолия под контрола си и се съпротивляваше на центъра. Той бе принуден да се предаде при обсадата на Ерзурум от великия везир Хюсрев паша, бе помилван и назначен в Босна. Краят на бунта бе предпоставка за това Мурад IV да може да потегли в поход срещу Иран.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Първата екзекуция на шейхюлислям: Ахизаде Хюсеин ефенди", "a60a58c5"], "d": ["Шейхюлисляма Ахизаде Хюсеин ефенди бе екзекутиран близо до Бююкчекмедже под предлог, че е посредничил във военната смута и е изпратил на падишаха писмено предупреждение за съдебната процедура. Като първи екзекутиран османски шейхюлислям, той наруши вкоренената традиция, според която най-тежкото наказание за улемите е заточение. Събитието се смята за символ на втвърдяващата се власт на Мурад IV и на нарушаването на баланса между държавата и улемите.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Превземането на Ереван от Мурад IV", "b65a9b73"], "d": ["Тръгнал от Истанбул на 28 март 1635, Мурад IV обсади Ереван на 28–29 юли и на 8 август прие предаването на крепостта; след това влезе в изпразнения Табриз и нареди да бъде разрушен. Падишахът построи в двореца Топкапъ Ереванския павилион в памет на победата. Този поход бе първата голяма източна кампания след трийсетгодишно прекъсване, при която падишахът лично командваше армията.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Загубата на Ереван в полза на сефевидите", "fbb8dd25"], "d": ["След оттеглянето на османската армия силите на шаха Сафи обсадиха Ереван и го върнаха за осем месеца. Толкова бързата загуба на крепостта показа колко трудно е в логистично отношение трайното господство в Кавказ. Ереван щеше да бъде оставен на Иран и с договора от Касър-и Ширин от 1639 и османците щяха да се откажат от претенциите си към Азербайджан.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Повторното завоевание на Багдад", "4d2f27f3"], "d": ["Мурад IV, излязъл от Истанбул на 8 май 1638, след четирийсетдневна яростна обсада си върна Багдад, който от петнайсет години бе в сефевидски ръце; при обсадата загина като шехид везирът Таяр Мехмед паша. С превземането на града османското управление в Ирак бе възстановено и падишахът получи титлата «Завоевател на Багдад». Завоеванието, затвърдено с договора от Касър-и Ширин през следващата година, положи основите на днешната турско-иранска граница.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Смъртта на Мурад IV и възцаряването на султан Ибрахим", "e2ca1ca0"], "d": ["След смъртта на Мурад IV, починал на двайсет и седем години (двайсет и осем по хиджра), на трона се възкачи брат му Ибрахим, единственият оцелял мъжки член на династията. По време на управлението на новия падишах, живял години наред в кафеса, дворцовите разходи и борбите за влияние в двореца разтърсиха държавния ред. С детронирането и убийството му осем години по-късно в османската история щеше да се случи второто убийство на падишах.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Възвръщането на крепостта Азак от казаците", "e5fcf160"], "d": ["Крепостта Азак, завладяна през 1637 от донските казаци, бе опразнена пред съвместната кампания на Султанзаде Мехмед паша и кримския хан Мехмед IV Гирай; казаците подпалиха крепостта и се оттеглиха. Възвръщането на северната порта на Черно море затвори опасния период, в който казашките набези стигаха до Истанбулския проток. Крепостта щеше да бъде загубена през 1696, този път в полза на руския цар Петър I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Началото на критския поход и превземането на Hanya", "a1b0c77f"], "d": ["Под претекст, че малтийски корсари са ударили османски поклонически кораб и са се скрили в Крит, бе обявена война на Венеция и флотът под командването на Юсуф паша стовари войска на острова. След петдесет и четиридневна обсада бе превзета крепостта Hanya и в Крит бе създадена първата трайна османска база. Така започна най-дългата война в османската история; островът щеше да бъде напълно завладян едва двайсет и четири години по-късно, през 1669", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Превземането на Ретимно — разделянето на Крит на две", "8f2c4353"], "d": ["Година след превземането на Хания паднала и крепостта Ретимно в средата на острова и западната половина на Крит премина изцяло под османска власт. В ръцете на Венеция останаха само столицата Кандия и източният край; островът живя двадесет и три години разделен на две. Превземането на Ретимно бе стъпката, започнала обсадата на Кандия — най-дългата обсада в историята започна тук.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Загубата на Клис в полза на Венеция", "5473c22c"], "d": ["На далматинския фронт на Критската (Кандийската) война контраатаката на венецианския командир Леонардо Фосколо обхвана и Клис, център на санджака от 1537; крепостта премина към Венеция. Съсредоточаването на цялата османска мощ в Крит направи невъзможно възвръщането на тази загуба на далматинската граница — Клис нямаше вече да се върне под османско управление; центърът на санджака бе преместен в Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Началото на обсадата на Кандия", "13016b10"], "d": ["След превземането на Hanya и Resmo османската армия обсади Кандия, последната голяма опора на Венеция на острова. Тази блокада, която щеше да продължи двайсет и една години, остана в историята като една от най-дългите обсади във военната история на света. По време на обсадата опитите на венецианския флот да затвори проток Чанаккале щяха да пренесат войната в сърцето на Егейско море.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Убийството на Великата валиде Кьосем султан", "9d763f79"], "d": ["Около шейсет и двегодишната Кьосем султан бе открита в една стая на харема и убита от Başlala Uzun Süleyman ага и хората му, действащи по заповед на Турхан султан, майката на Мехмед IV. Смъртта на тази силна жена от династията, която през управлението на трима падишахи насочваше политиката на държавата, се смята за фактически край на епохата, наричана «Женски султанат». Освободената власт отвори пътя към това Кьопрюлю Мехмед паша да стане след пет години велик везир с извънредни пълномощия.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Разгромът при Чанаккале и загубата на Bozcaada и Limni", "e01a1f7e"], "d": ["Голямата морска победа, спечелена от венецианския адмирал Mocenigo през юни 1656 пред проток Чанаккале, почти напълно унищожи османския флот; след това бяха окупирани Bozcaada, Limni и Semadirek. Със затварянето на пролива от венецианската блокада цените на храните в Истанбул скочиха и в столицата се разнесе страх от нападение. Това бедствие стана пряката причина през септември 1656 Кьопрюлю Мехмед паша да бъде назначен за велик везир при условия и с извънредни пълномощия.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Победата при Чанаккале и възвръщането на Bozcaada", "603da863"], "d": ["Флотът, мобилизиран от Кьопрюлю Мехмед паша, разби на 19 юли 1657 пред пролива венецианския флот; след това силите под командването на Курд паша си върнаха на 25 август Bozcaada и на 30 август венецианците напълно напуснаха острова. През ноември бе освободен и Limni, блокадата на Чанаккале бе пречупена и пътят за снабдяването на Истанбул бе отворен отново. Кьопрюлю лично отиде на острова и нареди да бъдат поправени укрепленията; този успех е първото голямо военно придобивка на епохата на Кьопрюлюовци.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Превземането на Yanova (Ineu) и походът срещу Трансилвания", "d1089616"], "d": ["Кьопрюлю Мехмед паша, потеглил в поход, за да накаже трансилванския княз Дьорд II Ракоци, който без разрешение бе тръгнал на поход срещу Полша и така бе нарушил османското покровителство, мина през Белград и превзе стратегическата крепост Yanova. В Трансилвания бе назначен нов княз и васалната връзка бе грубо припомнена. Този поход бе първото звено от опита на османците да възстановят авторитета си в Средна Европа. Трансилвания вече била васално на османците княжество; превземането на Yanova не бе завоевание от чужда държава, а изваждане на тази крепост на васалната Трансилвания от управлението на княжеството и свързването му директно с османски санджак; останалата част от княжеството остана във васален статут.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Потушаването на бунта на Абаза Хасан паша", "4ba74321"], "d": ["Абаза Хасан паша, който срещу строгите чистки на Кьопрюлю Мехмед паша застана начело на анатолийските бейлербеи и секбанските аги, поиска смяната на великия везир и започна голямо въстание. Бунтът бе потушен в Алепо и водачите му бяха премахнати; това бе последната обща съпротива на провинциалните паши срещу центъра. Така авторитетът на Кьопрюлю стана безспорен, а везирският пост отново се издигна до положението на истински изпълнителен център на държавата.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Превземането на Varad (Орадя)", "0e6ad300"], "d": ["В рамките на похода срещу трансилванския княз Дьорд II Ракоци, който обяви война на османците, бяха превзети крепостта и градът Varad. С падането на една от ключовите крепости на Трансилвания в региона бе създаден нов османски еялет (еялет Varad). Завоеванието разтревожи Хабсбургите и стана една от преките причини за османско-австрийската война, която щеше да започне три години по-късно. Други места, присъединени на същата дата: Varat. И тук земята не бе отнета от чужда държава: Трансилвания вече била васално османско княжество; превръщането на Varad в еялет само отне управлението на този град от васалното княжество и го свърза директно с падишаха, точно както преди две години при Yanova.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Битката при Свети Готард (St. Gotthard)", "61ebc1f2"], "d": ["Османските сили, преминали река Раб, бяха спрени от съюзническата европейска армия под командването на Монтекукули и понесоха тежки загуби. Битката се смята за повратна точка във военната история, тъй като за пръв път ясно показа превъзходството на огъня на дисциплинираната пехота с пушки над османската конна атака. Въпреки поражението османците успяха да извоюват изгодни условия в Васварския договор, подписан девет дни по-късно.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Васварски договор", "089c978c"], "d": ["Договорът, подписан въпреки разгрома при Свети Готард, определи, че Уйвар и Varad остават на османците, че Трансилвания остава неутрална под османско покровителство и че Австрия плаща «подарък» от 200 000 гроша. Този двайсетгодишен мир е един от редките примери за страна, загубила войната, която печели на масата. Недоволството, което договорът предизвика в хабсбургското общество, щеше да подхрани движението в Средна Унгария и косвено похода към Виена през 1683", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Започването на управлението на деите в Алжир", "e99faa51"], "d": ["Алжирският оджак и таифе-и реис (корсарските капитани) свалиха последния ага и избраха Хаджи Мехмед за дей с доживотен мандат. Оттогава Алжир се управляваше не от бейлербей, назначаван от Истанбул, а от дей, избиран от местния оджак измежду своите; османската връзка се ограничи с четенето на името на султана в хутбето, санджака и задължението за поход. Така Алжир се превърна от провинция в оджаклък — същата промяна преживяха Тунис с хюсейнидите през 1705 и Триполитания с Караманлиите през 1711", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Започна походът срещу Полша — Мехмед IV и Фазъл Ахмед паша начело на армията", "75e15a39"], "d": ["Когато нападенията на Полша срещу украинския хетман Петро Дорошенко, преминал под османско покровителство, продължиха, Истанбул поиска от полския крал да се откаже от нападенията; тъй като не последва положителен отговор, бе взето решение за поход срещу Полша. Великият везир Фазъл Ахмед паша потегли на 4 юни 1672 срещу Полша с армия, при която беше и падишахът. Походът щеше да завърши с превземането на Каменец и Бучачкия договор.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Превземането на Каменец и създаването на еялета Подолия", "c3f4f6d0"], "d": ["След деветдневна обсада бе приета предаването на Каменец, смятан за най-силната крепост на Полша на изток; Мехмед IV на 2 септември извърши първата петъчна молитва в джамията, превърната от катедралата. Като на крепостта бе даден статут на център, бе създаден еялетът Подолия и османското знаме достигна най-северната си точка в земите на днешна Украйна. Каменец щеше да остане северозападният край на империята до договора от Карловци през 1699", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Кара Мустафа паша прие предаването на Умань от Полша", "0d3543a0"], "d": ["Изпратеният срещу Полша Кара Мустафа паша прие предаването на Умань, една от крепостите, държани от Полша; градът остана под османско управление до Карловци.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Превземането на крепостта Чигирин", "a17cedd0"], "d": ["След кампанията през предходната година, при която Мелек Ибрахим паша не постигна резултат, великият везир Мерзифонлу Кара Мустафа паша лично командваше, обсади (19/21 юли) укрепената крепост Чигирин и я завзе на 21 август. Падането на крепостта, символ на османско-руското съперничество за казашкия хетманат в Украйна, принуди Русия към мир. Този успех бе един от източниците на самоувереността на Мерзифонлу, насочена към Виена.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Бахчесарайски договор — първият официален мир с Русия", "df82bc0b"], "d": ["След преговорите, водени след походите при Чигирин с посредничеството на кримския хан, бе подписан двайсетгодишен мир между Османската държава и Русия, при който река Özü (Днепър) бе приета за граница. Като първи всеобхватен договор между двете държави, той се смята за изходен документ на османско-руските отношения. Благодарение на мира източният фронт бе осигурен и армията можа да бъде насочена към Средна Европа.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Предоставянето на берат за кралство Средна Унгария на Имре Тьокьоли", "3cd8d51d"], "d": ["Протестантският унгарски благородник Имре Тьокьоли, въстанал срещу хабсбургския натиск, от април 1682 започна да бъде смятан за «избран крал на Средна Унгария», а на 16 септември будинският бейлербей Ибрахим паша му поднесе знаците на княжеското достойнство. Така под османско покровителство бе създадена нова васална унгарска държава. Тази намеса направи войната с Австрия неизбежна и започна веригата, водеща към Втората обсада на Виена през следващата година.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Загубата на Ayamavra (Лефкада) в полза на Венеция", "e6905fee"], "d": ["Флотът на Венеция, присъединила се към Свещената лига, след като обстреля града, окупира остров Ayamavra в Йонийско море. Със загубата на Превеза през същата година османският контрол над входа на Адриатическо море бе пречупен. Тези загуби бяха начални стъпки на кампанията, с която Моросини щеше да завладее цяла Морея в рамките на три години.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Загубата на Корон в полза на Венеция", "2ed762bc"], "d": ["Венецианските сили под командването на Моросини завзеха крепостта Корон в югозападния край на Мореанския полуостров; градът щеше да остане след това тридесет години под венецианско управление. Падането на Корон бе първото голямо придобивка на венецианската кампания за завладяване на Морея. Крепостта можа да бъде възвърната едва през 1715 от османската армия под командването на Силяхдар Али паша.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Връщането на Атина — оттеглянето на Венеция", "03393b46"], "d": ["Morosini, който през септември 1687 бомбардира Акропола и взриви Партенона, след като прекара зимата в Атина, разбра, че не може да се задържи в града. Поради чумна епидемия, трудности със снабдяването и прегрупирането на османските сили венецианският гарнизон напусна града и се оттегли в Морея. Така Атина се върна под османска власт без бой, но разрушението, понесено от Партенона, не можа да бъде възстановено.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Липова (Lippa) се предаде на Караффа — премина в австрийски ръце", "7f0a8d38"], "d": ["След тридневната обсада на Антонио Караффа Липова се предаде между 12 и 22 юни 1688 и премина в ръцете на Австрия. Османците по-късно си върнаха града, Австрия отново го превзе през 1691; при похода от 1695 Османската империя отново установи контрол. Другите селища, преминали от Османската империя към Хабсбургите в същия ден в атласа: Арад и Вилагош (Şiria). За Арад източникът дава само годината (MKL, Arad: между 1551-1688 в османски ръце); денят е взет от Липова, Вилагош следва веригата на Арад (beyanlı yaklaşıklık). Крепостите Лугож (Lugoj) и Карансебеш (Caransebeş) също преминаха към Австрия в края на юни (Bánlaky 0016/1302 „Jenővel elveszett Lugos és Karánsebes“; 0017/1443 „június végén“).", "2c8131d4"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Отблъскването на венецианската обсада на Eğriboz", "aae7e6a0"], "d": ["Моросини, насочил се към Егейско море след завладяването на Морея, се опита да вземе Eğriboz с обсада, продължила над три месеца; но пред укрепленията, засилени през зимата на 1687–1688, и съпротивата на гарнизона той бе принуден да се оттегли с тежки загуби. Този провал спря напредването на Венеция в Егейско море и разклати военния престиж на Моросини. Eğriboz щеше да остане в османски ръце и в Карловци.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Загубата на крепостта Kanije в полза на Австрия", "553b45f3"], "d": ["Kanije, взета от януари 1690 в плътна блокада от 60-хилядна хабсбургска армия, след като месеци наред се съпротивлява без помощ, бе загубена със споразумение за предаване, подписано от последния защитник Мустафа паша. Така приключи деветдесетгодишното османско господство в крепостта, известна с епичната защита на Тирьяки Хасан паша. Загубата на Kanije бе срутването на последната голяма опора на османците в западна Унгария.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Смъртта на Сюлейман II", "d2478080"], "d": ["Сюлейман II, който след около четиридесет години в кафеса бе възкачен на трона през 1687, умря в петък, 22 юни 1691, към обяд в Одрин, болен, докато следеше приготовленията на армията; царуването му продължи три години, осем месеца и два дни. Великият везир предварително бе дал необходимата инструкция брат му Ахмед да бъде възкачен на трона в случай на смърт на падишаха. Погребалната молитва бе извършена същия ден в Alay Köşkü; тялото му бе донесено в Истанбул и погребано в тюрбето на султан Сюлейман Законодателя, от дясната му страна.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Възкачването на трона на Ахмед II", "52947b14"], "d": ["След смъртта на Сюлейман II брат му Ахмед II, на четирийсет и девет години, се възкачи на трона в Одрин. Управлението му съвпадна с най-тежките години на войните на Свещената лига; два месеца след възцаряването му при Салан Кемен загина като шехид великият везир Фазъл Мустафа паша. В замяна на това системата на малекането, въведена по негово време, стана една от най-важните наредби, променили дългосрочната структура на османските финанси.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Смъртта на Мехмед IV в Одрин", "17388b7e"], "d": ["Свален от трона през 1687, Avcı Mehmed бе доведен в Одрин по време на унгарския поход на Сюлейман II през 1689 и стана свидетел и на царуването на другия си брат Ахмед II. Умря в този толкова обичан от него град. Тялото му бе донесено в Истанбул и погребано в тюрбето на майка му Turhan Sultan до Yenicami.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Смъртта на Ахмед II в Одрин", "c6306c08"], "d": ["Ахмед II, чието четиригодишно царуване мина във война, умря в Одрин на петдесет и две години от istiskā (воднянка). Тялото му бе донесено в Истанбул и погребано в тюрбето на Сюлейман Законодателя. На негово място се възкачи племенникът му Мустафа II.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Превземането на Басра от иранците", "a9cdf3a3"], "d": ["Докато Османската държава бе заета на запад с войните на Свещената лига, Басра, след епидемията от чума през 1690, бе пострадала първо от грабежите на мунтефикския шейх Мани, а след това на хана на Хувейзе Ферецуллах. Възползвайки се от това смущение, иранците превзеха града през 1696 и оставиха в Басра гарнизон.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Истанбулски договор — отстъпването на Азак на Русия", "79db4724"], "d": ["В Карловци с Русия бе постигнато само двегодишно примирие; трайният мир бе подписан в Истанбул след тежки преговори, продължили година и половина. Османската държава официално отстъпи на Русия крепостта Азак, загубена през 1696, и околните земи и се отказа от годишния данък, който кримският хан получаваше от Москва. В замяна Русия получи правото да държи постоянен посланик в Истанбул; така руското присъствие на северния бряг на Черно море бе юридически узаконено.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Възвръщането на Kürne и Басра от Далтабан Мустафа паша", "7adb777d"], "d": ["Далтабан Мустафа паша, назначен след договора от Карловци за багдадски управител и басренски сераскер, тръгна на юг със силите на Алепо, Ракка, Сивас и Караман и с речен флот, слязъл от Birecik. Околните племенни шейхове му се покоряваха един по един, иранският охранител на Басра Давуд хан напусна града и Kürne и Басра отново влязоха под османско управление.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Смъртта на Мустафа II", "626c394d"], "d": ["Мустафа II, който с Одринските събития (Edirne Vak'ası) отстъпи трона на брат си Ахмед III, умря в обичания от него Одрин около пет месеца след свалянето си от трона. Към болестта му се бяха прибавили и скърбите от последните събития. Някои западни източници пишат, че сред народа бе широко разпространено убеждението, че е бил отровен.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Началото на управлението на Кьолемен (мамелюците) в Багдад", "abe52618"], "d": ["С назначаването на грузинския по произход Хасан паша за управител на Багдад в Ирак започна период, в който вместо назначаваните от центъра управители преобладаваше управленски слой, израсъл от собствените им роби. С управлението на Сюлейман паша през 1749 системата се затвърди окончателно и Високата порта вече не можеше да назначава когото пожелае, а бе принудена да назначава един от завзелите влиянието кьолемени. Макар тази полуавтономна структура да е била полезна за защитата на иранската граница, тя отслаби контрола на централната власт над Ирак за един и половина века.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Основаването на династията на Хюсейнидите в Тунис", "cb1a98f9"], "d": ["В образувалия се вакуум на властта след нашествието на алжирските сили в Тунис сипахийският ага от турски произход Хюсеин бин Али завзе бейството и придоби легитимност, като заяви покорността си на османския падишах. Създадената от него династия управлява Тунис през 1705–1735 и 1756–1957; на оджашкото управление бе поставено бейство, преминаващо от баща на син. Така се роди първият пример на зависими от центъра, но фактически автономни династични структури в западните оджаци.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Превземането на Вахран (Оран) и Мерсалкебир от испанците", "b67ce06a"], "d": ["Силите на бейлербея на Алжирския оджак, след дълга обсада, завзеха Вахран и пристанището Мерсалкебир, които от два века бяха в ръцете на испански гарнизон. Това бе най-голямата победа, спечелена срещу Испания от намиращите се под османско покровителство западни оджаци в Западното Средиземноморие, и осигури западното крило на Алжир. Градът щеше да бъде през 1732 отново окупиран от Испания, но през 1792 окончателно възвърнат.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Прутски договор — възвръщането на Азак и Таганрог", "bac5d2a1"], "d": ["Седемчленният договор, подписан с предаването на обсадената при Прут руска армия, определи Азак да бъде върнат на османците заедно със земите и боеприпасите му. Укрепленията Таганрог, Каменка и Yenikale щяха да бъдат разрушени и страните нямаше да строят нови крепости в тези райони. Флотът и базовият ред, които Петър I създаваше шестнайсет години във Воронеж и Азак, се срутиха; излизането на Русия към Черно море се забави с около петдесет години.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Основаването на династията на Караманлиите в Триполитания", "e1105d4a"], "d": ["В Триполитания, изтощена от разприте на оджашките аги, кавалерийският офицер Ахмед Караманлъ взе властта и узакони положението си с бейлербейски берат от Истанбул. С Ахмед паша, сина му Мехмед паша и внука му Юсуф паша възникна династия, просъществувала през 1711–1835; появи се полунезависима структура, която създаде собствен флот и подписваше договори директно с европейски държави. Този период щеше да приключи едва през 1835 с директното подчиняване на еялета на центъра.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Одринският договор с Русия", "14901a70"], "d": ["След като поради неизпълнението на обещанията, дадени при Прут, война бе обявявана още два пъти, най-сетне, когато руснаците приеха поетите ангажименти, в Одрин бе подписан траен мир. Договорът потвърди условията от Прут; Русия нямаше да се меси в полските работи, щеше да се изтегли от казашките земи и нямаше да пречи на връщането в страната му на шведския крал Карл Железноглавия. Затварянето на северния фронт даде възможност на Османската държава да насочи погледа си към Морея и Венеция. Други места, присъединени на същата дата: Хотин.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Обявяване на война на Венеция — подготовка на похода към Морея", "d970b122"], "d": ["На Дивана бе взето решение за война с мотива, че Венеция подкрепяла черногорските бунтовници, конфискувала османски търговски кораби и смазвала с тежки данъци Морея, взета в Карловци. Походът, подготвен от великия везир Силяхдар Дамад Али паша, щеше да завърши през следващата година с възвръщането на целия Мореански полуостров за по-малко от сто дни. Но този успех щеше да раздвижи Австрия и да отвори през 1716 вратата на много по-тежка война.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Istendil (Тинос): предаването на последния остров на Венеция в Егейско море", "4abec891"], "d": ["Флотът, тръгнал на поход към Морея, хвърли котва по пътя пред Istendil, единствения остров, останал на Венеция в Егейско море. Островът, който, макар херцогството Наксос да падна през 1566, благодарение на латинското си население бе носил още сто и петдесет години венецианско знаме, се предаде след кратка обсада, без да бъде пролята кръв. Така последната венецианска следа в Егейско море бе заличена и морето стана изцяло вътрешно османско море.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Превземането на Нафплио — ключовата крепост на Морея", "62a5808a"], "d": ["Нафплио, венецианската столица и най-силно укрепеният пункт в Морея, падна, след като табията Паламиди бе овладяна след деветдневна бомбардировка. Толкова бързото превземане на крепостта пречупи съпротивата в останалата част на полуострова. Връщането на Морея, загубена при Карловци, на практика бе завършено тук. Другото селище, преминало същия ден в атласа от Венеция към Османската империя: Аргос — следва abi-merkez веригата на Нафплио (TDV anabolu; beyanlı yaklaşıklık).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Предаването на Модон", "43faa909"], "d": ["След падането на Нафплио крепостта Модон в югозападния край на Морея, обсадена от суша от армията и от море от флотата, скоро се предаде. Това пристанище, използвано от Венеция в продължение на двеста години при походите ѝ в Източното Средиземноморие, бе задължителна спирка, където корабите вземаха вода и провизии. Загубата му сложи край на способността за маневриране на венецианския флот в Егея.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Предаването на Корон — завършването на похода в Морея", "e4b9c8a4"], "d": ["С предаването на крепостта Корон, която държи входа на Месенския залив, венецианското управление в полуостров Морея напълно приключи. Полуостровът, загубен при Карловци, бе върнат изцяло едва три месеца след началото на похода. В продължение на същия поход през септември 1715 от Венеция бе отнет и островът Айя Мавра (Лефкада) в Йонийско море. Тази бързина принуди Венеция да въвлече Австрия във войната и три години по-късно отвори пътя към Пожаревац.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Превземането на Китира (Çuha Adası)", "494de6c6"], "d": ["След завършването на полуострова Çuha Adası в южния край на Морея бе взет от флотата. Островът, който наблюдава прохода между Йонийско море и Егея, бе напреднал пост, използван от Венеция за контрол над тези води. Но не остана единственият османски остров, който се задържа: три години по-късно бе върнат на Венеция при Пожаревац.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Австрия и Венеция сключиха съюз — вратата на османско-австрийската война от 1716–1718", "99511ca2"], "d": ["След като османците си върнаха Морея от Венеция, Австрия, твърдейки, че договорът от Карловци е нарушен, подписа съюзен договор с Венеция; принц Евгений в писмото си до великия везир поиска връщането на отнетите от Венеция места. При съвещанието в лагера Давутпаша с натиска на великия везир Али паша бе обявена война на Австрия и за това бе получена фетва от шейхюлисляма.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Великият везир Али паша потегли в поход срещу Австрия", "2fbdce42"], "d": ["След обявяването на война на Австрия сердар-екремът Али паша потегли в поход срещу Австрия с армия от над 100 000 души; флотът пък се насочи през същото лято към Корфу. Армията щеше да тръгне от Белград към Varadin и при разгрома в началото на август великият везир щеше да загине като шехид.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Разгромът при Varadin (Петроварадин) — шехидството на Дамад Али паша", "265c1d81"], "d": ["Османската армия, преминала Дунав през Белград, се срещна пред Varadin с австрийските сили под командването на принц Евгений; макар при първия удар еничарската атака да принуди вражеските окопи, редиците се разпръснаха с рухването на конното крило. Великият везир Силяхдар Дамад Али паша бе прострелян в челото и загина като шехид, лагерът и артилерията попаднаха изцяло в ръцете на врага. Този разгром, който османските вакаинамета наричат «годината на Varadin», бе първото звено от веригата към загубата на Темешвар и на Белград през следващата година.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Провалът на обсадата на Корфу", "b2aa7011"], "d": ["Мореанският сераскер Кара Мустафа паша по суша и капудан паша Джанъм Ходжа Мехмед паша с флота по море нападнаха Корфу; островът бе ключовата база на Венеция в Адриатика. Но изключително силните укрепления на крепостта, подкрепленията, донесени от венецианския флот, и вестите за разгрома на дунавския фронт доведоха до вдигането на обсадата. Невземането на Корфу угаси приповдигнатото настроение от повторното завладяване на Морея и измести центъра на тежестта на войната към Унгария.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Загубата на Темешвар (Timişvar) в полза на Австрия", "27fe1365"], "d": ["След разгрома при Varadin принц Евгений тръгна директно срещу Темешвар и крепостта бе предадена със споразумение в края на обсада, продължила над четирийсет дни. Градът, завладян през 1552 при Сюлейман Законодателя и смятан в продължение на 164 години за източен стълб на защитата на Унгария като център на бейлербейство, така бе загубен. С падането на Темешвар цялата област Банат премина към Австрия и османската граница бе изтласкана на юг от Дунав. Други места, преминали на същата дата в атласа от османците към Хабсбургите: Csákóvár, Facset и Karánşebeş (Caransebeş) — заедно със смяната на еялета Темешвар (TDV timisvar; денят на ниво място липсва в източника, верига на абиевия център, обявено приблизително).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Предаването на крепостта Haram (Yeni Palanka) на Австрия — дунавският бряг на Банат бе загубен", "38ee4c6d"], "d": ["След падането на Темешвар австрийският кавалерийски генерал Мерси, натоварен да вземе останалата част от Банат, на 14 ноември тръгна срещу Haram (Yeni Palanka) на дунавския бряг; когато на 16 ноември стигна до крепостта, 200-души османски гарнизон вдигна бял флаг и се предаде срещу условие за свободно оттегляне. Така и дунавската линия на Южен Банат, от 1552 в османски ръце, премина към Австрия. Друго място, преминало на същата дата в атласа от османците към Хабсбургите: Versec — следва верига на абиевия център на Haram (Bánlaky 0019/1703; обявено приблизително).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Пожаревацкият мир — Морея бе придобита, Белград и Банат бяха загубени", "d46aa216"], "d": ["Морея бе върната от Венеция, но Австрия, влязла във войната, с победите си при Петроварадин и Белград надделя на масата. Договорът, подписан с посредничеството на Англия и Холандия, остави Морея на Османската империя, но срещу това заедно с Белград бяха отстъпени на Австрия Северна Сърбия, Банат и Малка Влахия; по думите на TDV „Северна Босна е напълно отстъпена на Австрия“ — крепости като Босанска Дубица и Босански Брод по Сава в атласа от този ден преминават към Австрия (точната граница била прокарана от комисарите една по една, TDV не назовава тези крепости поименно); Венеция запази позициите си по Йонийския бряг като Превеза и Китира. С търговската ahidnâme, подписана същия ден, митото върху австрийските стоки бе намалено от пет на три на сто. Докато скрепяваше отстъплението на Османската държава от Централна Европа, договорът положи основите на двадесет и седемгодишния мир, който отвори пътя на Епохата на лалето (1718-1730): първата османска печатница (1727, İbrahim Müteferrika), преводаческите комисии, наблюденията върху ваксинацията срещу едра шарка и един нов дворцово-културен живот са плод на тези мирни години под управлението на Nevşehirli Damad İbrahim Paşa. Другите селища, сменили ръцете си същия ден в атласа: Крайова (Craiova), Римнику Вълчя (Râmnicu Vâlcea) и Турну Северин (Малка Влахия/Олтения, от Османската империя към Австрия), както и Айя Мавра (Лефкада) (от Османската империя към Венеция; TDV ayamavra: през 1718 с Пожаревацкия договор островът е отстъпен на Венеция). В Малка Влахия освен това Търгу Жиу преминава към Австрия; Воница (Voniçe, TDV pasarofca-antlasmasi) и Китира (Çuha Adası, TDV cuka-adasi: член 3 на Пожаревац) преминават към Венеция.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Източен поход: превземането на Тбилиси и началото на войната с Иран", "78343dc2"], "d": ["След срутването на Сефевидската държава от афганистанското нашествие и слизането на Русия към бреговете на Каспийско море Османската държава изпрати армия на изток, за да не остане празнотата изцяло на руско влияние. С превземането на Тбилиси Грузия бе присъединена към османското управление; след това напредването продължи към Гянджа, Ереван и Нахичеван. Този поход, воден зад мирния облик на Епохата на лалетата, стана началото на дълго източно приключение, което щеше да продължи тринайсет години и да завърши с връщането на всичко спечелено.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Иранският поход от 1723: навлизането в Ширван и Грузия", "c81189fc"], "d": ["Поради срива на държавата на сефевидите вследствие на афганистанското нашествие, с мотива да се възпре слизането на Русия по каспийските брегове, бе предприет поход на изток. Ерзурумската армия влезе през Грузия в Тифлис, а ширванското крило в Шамахи, като си върна земите, загубени преди сто и тридесет години. Този поход остана последното голямо османско настъпление в Кавказ.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Превземането на Керманшах — вратата на Загрос", "ad14799f"], "d": ["Багдадската армия премина през проходите на Загрос и завладя Керманшах, смятан за западната порта на Иран. Градът лежеше на кервано-армейския път от Багдад към Исфахан и превземането му осигуряваше източната сигурност на иракския еялет. Това настъпление започна надпреварата за поделяне на разпадащата се земя на сефевидите между Османската империя и Русия.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Истанбулска мукасеменаме — разделянето на Иран с Русия", "fce8eec2"], "d": ["За да бъде предотвратена срещата на османците и Русия върху срутващата се сефевидска страна, бе подписан договор за разделяне с посредничеството на френския посланик. Западните и южните брегове на Каспийско море бяха оставени на Русия, а Грузия, Ширван, Азербайджан и градовете на Западен Иран — на Османската държава. Това разделяне, което на хартия изглеждаше голяма печалба, скоро щеше да стане фактически невалидно с възхода на Надир шах. Според договора плодородните земи на Ширван, като Шабран и Мюшкюр, бяха оставени от руската страна (Чайджъоглу, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Превземането на Нахичеван", "bdf14d0a"], "d": ["Османските сили, напредващи по Араке, превзеха Нахичеван и Ордубад; Джулфа също бе присъединена към Нахичеванския лива. Градът, като северозападна порта на Иран, бе подчинен на новоучредения еялет Revan. Така османската граница отново достигна най-източната си линия от времето на Законодателя.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Превземането на Хамадан", "e1339a97"], "d": ["Армията, поела на изток от Керманшах, превзе след дълга обсада Хамадан, на западния праг на иранското плато. Градът бе последното голямо спиране по пътя към Исфахан — най-източната точка, до която османските армии бяха стигали от Irakeyn Seferi насам. Подписаната същата година с Русия Истанбулска конвенция положи на хартия поделянето на разпадащия се Иран между Османската империя и Русия.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Повторното превземане на Revan", "88acabef"], "d": ["След деветдесетдневна упорита обсада ключовата крепост на долината на Араке Revan отново премина под османска власт. Крепостта, построена през 1583 и загубена през 1604, бе укрепена този път с по-силен гарнизон. Дължината на обсадата бе показателна, че османската армия вече не напредва лесно. Нахиите Karpi (Üçkilise), Şerür, Makû и Şüregel също бяха присъединени към еялета Revan.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Превземането на Табриз — овладяването на Азербайджан", "e502a4f7"], "d": ["Табриз, обсаден отново след неуспешния опит от предходната година, се предаде на османската армия след тежка битка, водена улица по улица. Merend, Merâga и Sovukbulak (Mahabad), свързани с еялета Табриз, също влязоха под османско управление. През същата година бяха превзети и Lori, Гянджа, Ардебил и Hürremâbâd и районите, паднали се на османците по Истанбулската мукасеменаме, бяха фактически окупирани. Достигнатият на изток обхват бе най-напредналата граница след епохата на договора на Ферхад паша; но удържането му стовари тежко бреме върху армията и хазната.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Превземането на Гянджа — краят на похода в Кавказ", "875bca7a"], "d": ["Гянджа, последната цел на кавказката операция, бе приета с предаване като средище на Карабах между Кура и Араке. С довършването на линията Ширван, Revan, Нахичеван и Гянджа Османската държава достигна в Кавказ ширината си от 1590 Но тази придобивка се оказа краткотрайна: възходът на Надир шах щеше да върне цялата област в рамките на десет години.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Хамаданският договор — присъединяването на Западен Иран към османците", "94a29dc3"], "d": ["С договора, подписан с афганистанския владетел Ашраф шах, четиригодишната война приключи и окупираните от Османската държава земи в Западен Иран бяха юридически признати. В замяна Ашраф шах призна халифството на османския падишах и пое задължението хутбето в Иран да се чете на името на падишаха. Тази дипломатическа победа бе краткотрайна; контраофанзивата, започната от Надир шах през 1730, щеше да заличи придобивките на договора в рамките на няколко години.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Paşa превзе Урмия (Rûmiye)", "eac7f64d"], "d": ["При похода в Иран Hekimoğlu Ali Paşa превзе първо Урмия (Rûmiye), а след това Тебриз, опразнен в полза на Османската империя, на 15 ноември 1731 TDV не дава деня на превземането на Урмия; известно е само годината и че то е предхождало Тебриз.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Договорът на Ахмед паша — връщането на по-голямата част от Западен Иран", "590d839f"], "d": ["След победата на Надир шах при Мелайир и последвалите иранските нападения багдадският управител Ахмед паша подписа мирен текст, без да се допита до центъра. Според договора река Арас бе приета за граница; градовете на Западен Иран като Хамадан, Керманшах, Ардалан, Ардебил и Табриз бяха върнати на Иран, а Гянджа и Тбилиси останаха при османците. Този текст, посрещнат с реакция в Истанбул, бе счетен за недостатъчен и от Надир шах и още преди да изтече 1732 войната пламна отново. Атласът смята, че и Kotur, следващ веригата на Hoy, е преминал на този ден от османците към сефевидите (TDV hoy; специфичен за Kotur ден в източника няма — обявено приблизително).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Повторната загуба на Вахран (Оран) в полза на Испания", "20485027"], "d": ["Големият десантен флот, изпратен от испанския крал Филип V, пристигна пред Вахран под командването на граф Монтемар и, разбивайки силите на Алжирския оджак, си върна града. Пристанището, завладяно двайсет и четири години по-рано, щеше да остане отново шейсет години в ръцете на испански гарнизон. Тази загуба, която показа границите на силата на западните оджаци в Западното Средиземноморие, можа да бъде компенсирана едва през 1792 с окончателното завладяване на Вахран.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Реформата на Хумбараджийския оджак по европейски образец и създаването на Хумбарахане", "d980cf2a"], "d": ["Хумбараджъ Ахмед паша, френски по произход и постъпил на османска служба, с подкрепата на великия везир Хекимоглу Али паша превърна хумбараджийския оджак в платена и организирана по европейски начин част. На триста войници, набрани от Босна, бе давано редовно обучение, основано на смятане и геометрия; бяха изготвени нови наредби за организация, снаряжение и пенсиониране, с модерна техника бяха произведени сто хумбараджийски топа и петдесет хиляди хумбари. Хумбарахането, където се преподаваше геометрия, се смята за първото ядро на модерното военноинженерно образование в Османската държава.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Смъртта на Ахмед III", "455f7fba"], "d": ["Ахмед III, свален от трона през 1730 с бунта на Patrona Halil, прекара последните шест години от живота си в отделението на двореца Топкапъ, предназначено за свалените падишахи, и умря на шестдесет и три години. Бе погребан в Bahçekapı, в тюрбето на баба му Turhan Sultan до Yenicami.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Истанбулски договор — отстъпването на Южен Кавказ на Иран", "8c205aab"], "d": ["Четиригодишната втора иранска война приключи с договора, подписан след разгрома при Арпачай и загубата на Гянджа и Тбилиси. Османската държава се оттегли от всички земи в Южен Кавказ и Западен Иран, които бе завзела от 1723, и границата се върна на линията на Касър-и Ширин от 1639 От тринайсетгодишните източни походи останаха тежко финансово бреме и изпразнена хазна; в замяна на това затварянето на източния фронт бе жизненоважно за новата война, започнала с Русия.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Падането на крепостта Özi (Очаков) в ръцете на руснаците", "f93e61f3"], "d": ["Руската армия под командването на маршал Мюних обсади крепостта Özi в устието на Днепър; със взрива на оръжейния склад защитата се срути и крепостта падна с големи човешки загуби. Загубата на Özi, смятана за ключ на северозападния бряг на Черно море, отвори пътя към Крим за руснаците и предизвика голяма паника в Истанбул. Крепостта щеше да бъде опразнена от руснаците следващата година поради епидемия и затруднения със снабдяването и отново да премине към османците.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Победата при Баня Лука — освобождаването на Босна", "f603865a"], "d": ["Когато австрийските сили навлязоха в Босна и обсадиха Баня Лука, босненският управител Хекимоглу Али паша пристигна на помощ със събрани от местното население сили и нанесе тежко поражение на превъзхождащия по численост враг. Тази победа срути още с първия ход австрийския план за окупация на Босна и северът на еялета бе изцяло възвърнат. Баня Лука стана една от повратните точки, повдигнали морала на османската армия, отстъпваща непрекъснато пред Австрия след 1683", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Победата при Hisarcık (Гроцка) — отварянето на пътя към Белград", "2101cdff"], "d": ["Австрийската армия, напредваща да защити Белград, бе подведена в засада в тесен проход на дунавския бряг и понесе тежки загуби в битка, продължила цял ден. Докато силите на маршал Валис се отдръпваха безредно към Белград, османската армия стигна пред крепостта и започна обсадата. Hisarcık бе най-категоричната полева победа над Австрия след Карловци и пряко осигури възвръщането на Белград.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Нишки договор — мир с Русия, неутрализиране на Азак и спиране на кримските набези", "674f974e"], "d": ["Русия, останала сама след съгласието на Австрия за мир в Белград, бе принудена, с посредничеството на френския посланик Вильньов, да приключи войната. Укрепленията на крепостта Азак бяха разрушени и районът бе обявен за неутрална земя между двете държави; Русия прие условието да не държи военни и търговски кораби в Черно море. Така целта на Русия да излезе на морето бе отложена с още едно поколение, а Османската държава за последен път през XVIII в. стана от масата с печалба.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi се върна от руската окупация: след като крепостта бе разрушена по мира от 1739, бе предадена", "7ecc2bef"], "d": ["Руснаците бяха взели Özi на 11 юли 1737 По силата на мира с Русия през 1739 след разрушаването на укрепленията на крепостта тя бе предадена отново на османците; османците задържаха Özi до 1788, преди Ясийския договор.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Защитата на Мосул — отблъскването на Надир шах", "c03ffbc1"], "d": ["Надир шах, който превзе Киркук и Ербил и стигна пред Мосул, обстрелва града с оръдия четирийсет дни и организира едни след други общи атаки. Защитата, водена от управителя Хюсеин паша ал-Джалили, който въоръжи и градското население, принуди иранската армия да вдигне обсадата с тежки загуби. Устояването на Мосул предотврати загубата на целия Ирак и укрепи за един век влиянието на семейство Джалили в града.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Съюзът от Dir'iye — създаването на първия Саудитски емират в Неджд", "188751bf"], "d": ["Емирът Мухаммед бин Сауд, който взе под закрилата си прогонения от Uyeyne учен Мухаммед бин Абдулвехаб в Dir'iye, сключи с него съюз, поставящ политическата власт в служба на религиозния призив. Това споразумение откри нова история за рода Сауд и обедини разпръснатите оазисни емирства на Неджд около едно движение. Тази сила, която в рамките на половин век щеше да стигне до Кербела, Мека и Медина, щеше да принуди Османската държава да защитава господството си в Хиджаз.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Договорът от Керден — краят на османско-иранските войни", "1d3a919e"], "d": ["С договора, подписан след последната четиригодишна война, границата на Касър-и Ширин от 1639 бе подновена без промяна; никоя от страните не постигна териториално придобивка. Упоритото искане на Надир шах джафаризмът да бъде признат за пети мезхеб остана без отговор; в замяна на това бе решено иранските поклонници да могат свободно да извършват хаджа и да бъде разменяно взаимно посланици. Така османско-иранските войни, продължили над два века, фактически приключиха; тази граница до днес в голяма степен е запазена.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Смъртта на Махмуд I и възцаряването на Осман III", "30203700"], "d": ["Махмуд I, който през двайсет и четиригодишното си управление върна загубените с Белградския договор земи и подкрепи реформата на Хумбараджийския оджак, почина, връщайки се от петъчния селямлък. На негово място се възкачи брат му Осман III, живял до петдесет и осмата си година в кафеса. Започна кратко и тревожно управление; по времето на Осман III, сменил за три години шест велики везири, в държавните работи се наложи изразено застиване.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Смъртта на Осман III и възцаряването на Мустафа III", "3ac10f85"], "d": ["След смъртта на Осман III след тригодишно управление на трона се възкачи Мустафа III, отворен към идеите за реформи и проявяващ близък интерес към държавните работи. Новият падишах, опирайки се на опита на великия везир Коджа Рагъп паша, се опита да оправи финансите и да обнови армията; по това време бяха създадени бързата артилерия на барон дьо Тот. Но руската война, в която бе встъпено през 1768, щеше да засенчи всички придобивки на седемнайсетгодишното управление.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Обявяване на война на Русия — инцидентът при Балта и началото на войната от 1768–1774", "9c6aabe0"], "d": ["След като руски и казашки части, преследващи Барската конфедерация в Полша, нахлуха в градчето Балта на османската граница и го подпалиха, Диванът взе решение за война и руският посланик бе хвърлен в Едикуле. Встъпена във войната без сериозна военна подготовка и обявена шест месеца предварително, тя тръгна зле още от самото начало. Тази борба, която щеше да продължи шест години, с набега при Чешме, разгрома при Картал и окупацията на Крим щеше да се превърне в една от най-тежките серии от поражения в османската история.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Загубата на крепостта Хотин в полза на руснаците", "66d43ea4"], "d": ["Докато двата опита на руската армия под командването на княз Голицин бяха отблъснати, след разгрома на великия везир между Каменец и Хотин армията се оттегли и защитниците опразниха крепостта. Загубата без съпротива на най-силната османска крепост на север от Дунав отвори вратите на Влашко и Молдова за руснаците. Двете княжества бяха окупирани през същата година; Хотин можа да бъде възвърнат едва през 1774 с договора от Кючук-Кайнарджа.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Разгромът в равнината Картал (Кагул)", "6f408eaf"], "d": ["Три седмици след изгарянето на флота при Чешме главната османска армия по Дунав се разпръсна в равнината Картал пред далеч по-малките по численост, но дисциплинирани части на маршал Румянцев. Лагерът, обозът и стотици оръдия попаднаха в ръцете на врага; бягащите части понесоха големи загуби, докато преминаваха Дунав. Унищожаването на флота и на сухопътната армия през същото лято доведе до падането на Кили, Акерман, Измаил и Бендери една след друга и до окупацията на Крим.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Руската окупация на Кримския полуостров", "217837b0"], "d": ["Руските армии, завладели Буджак година по-рано, под командването на княз Долгоруков преминаха Or Kapı и нахлуха в целия Кримски полуостров. Ханът бе свален от трона и на власт бе поставен проруският Сахиб Гирай; така бе направена първата стъпка към откъсването на ханството от османците. Загубата на Крим, три века северен щит на османците, беше началото на процеса, довел до независимост през 1774 и до пряка анексия през 1783", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Смъртта на Мустафа III и възцаряването на Абдюлхамид I", "42cba8e2"], "d": ["На мястото на Мустафа III, починал в най-кризисния момент на руската война, на трона се възкачи на четирийсет и девет години брат му Абдюлхамид I, прекарал четирийсет и три години в кафеса на двореца. Новият падишах, наследил един от най-трудните периоди на държавата, бе принуден да се изправи пред тежките условия на Кючук-Кайнарджийския договор, който щеше да бъде подписан същата година. Петнайсетгодишното му управление щеше да премине със загубата на Крим и нова руска война и да приключи с парализата, получена при четене на вестта за падането на Özi през 1789", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Разгромът при Козлуджа — поражението, водещо към Кючук-Кайнарджа", "8e0542f9"], "d": ["Османските сили, събрани пред Шумен, бяха разбити при Козлуджа от обединените колони на Суворов и Каменски и по-голямата част от армията се разпръсна. С този разгром в Балканите не остана сила за съпротива; руските авангарди обсадиха Шумен и щабът на великия везир се оказа под заплаха. Сядането на масата в Кючук-Кайнарджа и приемането на извънредно тежки условия, преди да мине месец, са пряка последица от това поражение.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Отстъпването на Буковина (Северна Молдова) на Австрия", "190f9caa"], "d": ["Австрия, възползвала се от слабостта, предизвикана от Кючук-Кайнарджа, поиска областта Буковина, осигуряваща връзката между Молдова и Трансилвания, и получи тази земя без да встъпва във война, със заплахи и подкупи. Загубата на тази плодородна и стратегическа област югозападно от Хотин на практика раздели молдовското войводство на две. Това отстъпване, станало без да бъде изстрелян нито един куршум, се смята за един от най-ясните показатели, че Османската държава е загубила възпиращата си сила. С отстъпването на Буковина през 1775 Suçava и Çernovitz преминаха към Австрия (денят е непотвърден).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Иранската окупация на Басра", "0161e709"], "d": ["Садък хан, брат на зендския владетел Керим хан, след едногодишна обсада завзе Басра и Османската държава загуби най-важното си пристанище в Персийския залив. Окупацията нанесе пряк удар върху индийския търговски път, върху доходите от фурми и перли и върху южната защита на Ирак. Градът можа да бъде възвърнат едва през 1779, по време на борбите за трона в Иран след смъртта на Керим хан.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Айналъкавашкият тенкихнаме — временно споразумение за Крим", "9b3b0468"], "d": ["Двете държави, които стигнаха до ръба на война заради това кой ще застане начело на Кримското ханство, с посредничеството на Франция подписаха в двореца Айналъкавак текст с разяснения. Русия се съгласи да изтегли войската си от Крим, а Османската държава — да признае ханството на проруския Шахин Гирай; религиозното право на халифство на падишаха над Крим бе потвърдено. Това крехко равновесие, което щеше да продължи четири години, щеше да се срути напълно през 1783 с пряката анексия на полуострова от Русия.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Строежът на крепостта Анапа — Кавказката отбранителна линия", "be92a80f"], "d": ["След като Крим бе загубен с Кючюк-Кайнарджийския мир, за да се запази османското влияние в Кавказ, започна строежът на нова крепост в устието на река Кубан. Анапа, основана върху останките на една генуезка колония, със своя пазар, бани и повече от двеста и петдесет дюкяна, скоро се превърна в град, осигуряващ връзка с черкезките племена. Крепостта остана четиридесет и осем години най-напредналият османски пост срещу слизането на Русия към Кавказ.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Сваляне и екзекуция на великия везир Halil Hamîd Paşa", "c44001ca"], "d": ["Реформаторът велик везир Halil Hamîd Paşa, от когото Абдюлхамид I многократно бе показвал задоволство, бе внезапно отстранен към сутринта на 31 март 1785 и заточен в Галиполи, а цялото му имущество бе конфискувано. Първо му бяха дадени еялетът Habeş, санджакът Джеда и длъжността шейх на Харема в Мека; докато прекарваше април 1785 в Тенедос в приготовления за път, бе отстранен и от това управителство и с излязлата смъртна заповед бе убит от Karakethüdâzâde Ali, човек на Cezayirli Gazi Hasan Paşa. Отрязаната му глава бе изпратена в Истанбул и изложена в Ortakapı. Според TDV това внезапно падение е тълкувано като обвинение в заговор за сваляне на падишаха от трона и поставяне на негово място на Шехзаде Селим, но истинските причини вероятно са възмущението от мълчанието му по присъединяването на Крим, враждебността на средите, засегнати от реформите му, и противопоставянето на Gazi Hasan Paşa.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Обявяване на война на Русия — започна османско-руската война от 1787–1792", "3bfb870c"], "d": ["След показното пътешествие на Екатерина II в Крим и вземането на Грузия под нейно покровителство Диванът взе решение за война с цел да се отмени анексията и руският посланик бе отново затворен в Едикуле. Но армията не бе готова, хазната бе празна и търсенето на съюзници остана безрезултатно. Войната, която щеше да продължи пет години, щеше да завърши с падането на Özi с кланета, загубата на Измаил и тежките условия на Ясийския договор.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Встъпването на Австрия във войната — борба на два фронта", "ae912290"], "d": ["По силата на тайния съюз от 1781 с Русия австрийският император Йосиф II обяви война на Османската държава и започна действия по посока на Белград и Босна. Османската армия внезапно бе принудена да воюва едновременно на два фронта: срещу Русия на север и срещу Австрия на запад. Въпреки победите над австрийците при Lazarethane, Mehadia и Şebeş западният фронт щеше да се срути със загубата на Белград през 1789", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Османско-пруски съюз", "03b88e51"], "d": ["Селим III, който търсеше съюзници в Европа веднага след възкачването си, подписа съюзен договор с Прусия, предвиждащ взаимна помощ; Прусия се задължи да обяви война на Русия и Австрия, а Османската държава — да не сключва мир, докато Крим не бъде върнат. Това бе първият истински текст за взаимен съюз, подписан в османската история с европейска държава, и показваше изоставянето на класическото разбиране «няма съюз с неверниците». Прусия не встъпи във войната, но принуждавайки Австрия към мир, отвори пътя към Свищовския договор.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Падането на крепостта Измаил и кланетата", "6a296b0c"], "d": ["Крепостта Измаил, смятана за най-силното укрепление в Дунавската делта, бе превзета за един ден с кървава обща атака, организирана от генерал Суворов; гарнизонът и градското население бяха в голяма степен изклани. Това клане, предизвикало широк отзвук в Европа, причини дълбок шок в османското общество и пречупи гръбнака на дунавската отбранителна линия. Крепостта щеше да бъде върната година по-късно с Ясийския договор, но съдбата на войната вече щеше да е решена.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Свищовски договор — затварянето на австрийския фронт", "58741f1d"], "d": ["Благодарение на натиска на Прусия и заетостта на Австрия на запад от Френската революция двете държави стигнаха до мир, като за основа бяха взети границите отпреди войната. Австрия върна всички места, които бе окупирала, включително Белград; Османската държава прие само малки поправки по границата с Хърватия. Затварянето на западния фронт при тези условия даде възможност на Османската държава да съсредоточи цялата си сила срещу Русия и ограничи загубата в Ясийския договор. С тези поправки по хърватската граница Cetin (Cetingrad) и Drežnik Grad преминават от османците към Хабсбургите (TDV zistovi-antlasmasi; Korić 2016, n. 118, 4. член). Orsova (Eski Orsova) е единственото място, което не е върнато (Bánlaky 0019/1796); атласът записва юридическото предаване на този ден (фактическата окупация е на 16 април 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Ясийски договор — окончателната загуба на Крим и границата по Днестър", "a56fd194"], "d": ["С договора, подписан в края на петгодишната война, река Днестър бе приета за граница; левият бряг на реката остана на Русия, а десният — на османците, и Özi с околностите му бе окончателно загубен. Османската държава напълно се отказа от надеждата да си върне Крим и юридически призна анексията от 1783; Влашко и Молдова бяха върнати с двегодишно освобождаване от данък. С приемането на задължение за военно обезщетение от дванайсет милиона гроша северът на Черно море бе трайно отстъпен на Русия. Други места, присъединени на същата дата: Измаил.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Опразването на Оран (Vehrân) от испанците и предаването му на Алжир", "9f95cee6"], "d": ["Когато крепостта и градът бяха до голяма степен разрушени при земетресението от 1790, Испания, която вече не можеше да носи скъпоструващия си гарнизон, поддържан три века, се споразумя с алжирския оджак и предаде Vehrân и Мерс ел-Кебир без война. Така бе ликвидиран и последният европейски пост на северноафриканския бряг. Османски Алжир остана да владее целия бряг в продължение на тридесет и осем години, до френското нашествие.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Фактическото владение на Пазвандоглу Осман във Видин", "0ce70361"], "d": ["Пазвандоглу Осман, въстанал срещу наредбите на Низам-ъ Джедид, накара видинския управител да избяга, превзе града и го укрепи с дълбоки окопи по Дунав. През 1797, на върха на силата си, той събра почти осемдесет хиляди души и взе под контрол Никопол, Свищов, Русе, София и Ниш; представяше се не като бунтовник, а като реформатор. Обсадата на Високата порта през 1798–1799, продължила месеци, остана безрезултатна и той управлява полунезависимо в Северна България до смъртта си през 1807", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Откриването на Мюхендисхане-и Берри-и Хюмаюн", "e9a3a34b"], "d": ["В Хаскьой бе открито сухопътно инженерно училище, за да подготвя артилерийски, фортификационни и картографски офицери за армията на Низам-ъ Джедид; то бе съответствието в сухопътната армия на Морското инженерно училище, основано през 1773 В програмата се преподаваха алгебра, геометрия, механика, фортификация и балистика, от европейските езици бяха преведени книги по математика и артилерия. Смятано за корен на модерното инженерно образование в Турция, това училище се приема за начало на днешния Истанбулски технически университет.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Обявяване на война на Франция и съюз с Русия и Англия", "80e95bd7"], "d": ["След окупацията на Египет от Наполеон Османската държава, нарушавайки двеста и петдесетгодишното си традиционно приятелство с Франция, обяви война на Франция. В същия процес за първи път в историята си тя сключи съюз с Русия и позволи на руския флот да премине през проливите и да излезе в Средиземно море; след това бе подписан съюз и с Англия. Благодарение на тези съюзи Йонийските острови бяха взети от французите, но отварянето на проливите за чужд флот създаде прецедент с тежка цена в бъдеще.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Отнемането на Превеза от французите — битката при Никополис", "d8e5e892"], "d": ["Когато Венецианската република бе унищожена през 1797, Йонийските острови и сухоземните Превеза, Парга и Воница попаднаха в ръцете на Франция. Янинският валия Tepedelenli Ali Paşa, като се възползва от войната, започнала заради френското нашествие в Египет, потегли срещу Превеза и нанесе тежко поражение на френския гарнизон при руините на Никополис извън града. Така това пристанище, оставено на Венеция при Пожаревац, влезе под османска власт осемдесет години по-късно. Бутринт (Butrinto) падна на 25 октомври, когато френският гарнизон взриви укрепленията и се оттегли към Корфу (Curlin, Preveza B, 2010; атласният ден е взет от Превеза) и премина под османска власт.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Защитата на Акра — отблъскването на Наполеон", "56b5c45b"], "d": ["Наполеон, напредвайки от Египет към Сирия, обсади Акра и в продължение на два месеца организира последователни атаки; градът бе защитаван от Джеззар Ахмед паша с подкрепата на английския флот и с изпратените от Истанбул части на Низам-ъ Джедид. Принуден да вдигне обсадата и да се оттегли към Египет, Наполеон погреба мечтата си да стигне до изток пред тези стени. Вестта бе посрещната в Истанбул с голяма радост и бе приета като доказателство, че новосъздадената обучена армия е издържала първия си сериозен изпит.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Нападението на уахабитите над Кербела", "522341ed"], "d": ["Уахабитските сили, тръгнали от Неджд, влязоха в Кербела, разграбиха града, разрушиха гробницата на Хюсеин и убиха над три хиляди души. Кьолеменските управители на Османската държава в Ирак не можаха да предотвратят нападението; събитието предизвика голяма реакция както в Иран, така и в Истанбул. Това нападение бе обявяване на факта, че саудитското движение вече е престанало да бъде оазисен емират и се е превърнало в регионална сила, заплашваща светите градове на османците.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Картли-Кахетия (Източна Грузия) бе присъединена към Русия", "3b650c5e"], "d": ["Царството Картли-Кахетия, което приема руско покровителство през 1783 и бе подложено на разорителния поход на Иран през 1795, бе премахнато; със заповед от 12 септември 1801 бе обявено за губерния на Русия и започна налагането на руската система на управление. От тази дата Грузия загуби независимостта си; в рамките на няколко години под руско владичество минаха и Мегрелия (1803), Имеретия и Гурия (1804) и Русия опря до османската кавказка граница. С това събитие Гори, Душети (Картли) и Телави (Кахетия) преминаха към Русия.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Евакуацията на Египет от французите", "00cfdc8c"], "d": ["В резултат на съвместната операция на османските и английските сили по суша и по море първо Кайро, а след това Александрия бяха приети на предаване и френските сили бяха изпратени с кораби в страната им. С края на тригодишната окупация Египет на хартия се върна към османското управление, но борбата за надмощие между кьолеменските бейове и албанските части вкара страната в хаос. Тази празнота щеше да подготви в рамките на няколко години почвата за възхода на Мехмед Али от Кавала.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Парижки договор — възстановяването на мира с Франция", "1b76991f"], "d": ["С договора, подписан след евакуацията на Египет, състоянието на война между Османската държава и Франция официално приключи и старите капитулации бяха подновени. На френските търговски кораби бе разрешено да влизат в Черно море; в замяна Франция призна териториалната цялост на османците. Установяването на мира даде на външната политика на Селим III, притисната между Русия и Англия, отново свобода за маневриране.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Овладяването на Таиф от уахабитите", "7b791359"], "d": ["Уахабитските сили под командването на Сауд бин Абдулазиз при първия удар към Хиджаз обсадиха и разграбиха Таиф; градът падна като първата врата, водеща към свещените земи. За османския падишах, носещ титлата покровител на Харемейн, това бе удар, пряко разклатил легитимността на султаната. След два месеца и половина същата армия щеше да потегли към Мека.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Първото овладяване на Мека от уахабитите", "21157c05"], "d": ["Два месеца и половина след падането на Таиф уахабитските сили влязоха в Мека, разрушиха гробниците и установиха ред според своето разбиране; шериф Галиб бе принуден да се оттегли в Джеда. Затварянето на хаджийските пътища отекна из целия ислямски свят и принуди Истанбул да поиска военна помощ от египетския управител Мехмед Али. Това първо господство щеше да продължи само три месеца.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Възвръщането на Мека от шериф Галиб", "83d08dff"], "d": ["Оттеглилият се в Джеда шериф Галиб с събраните сили обсади Мека и след двайсет и петдневна обсада върна града от уахабитите; хутбето отново бе четено на османско име. Това второ господство също нямаше да бъде трайно и силите на Сауд щяха да вземат града отново през 1806", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Началото на Първото сръбско въстание", "0f6e8767"], "d": ["След като въстаналите еничарски дахии, завзели управлението в Белград, избиха масово сръбските първенци, под водачеството на Карагеорги започна въоръжена съпротива. Движението, което в началото оставаше вярно на падишаха и бе насочено единствено срещу дахиите, скоро се превърна в национално въстание, искащо автономия и независимост. Сръбските сили завзеха Белград през 1806; това въстание бе първото звено на националните освободителни движения на Балканите.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Окупацията на Медина от уахабитите", "84e310d7"], "d": ["След Мека и Медина попадна в ръцете на уахабитските сили; съкровищницата на Равза-и Мутаххара бе разпиляна и куполните гробници в града бяха разрушени. Така двата свещени града излязоха наведнъж изпод османски контрол и хаджийските керваните от Дамаск и Египет не можаха да тръгнат години наред. Медина можа да бъде възвърната едва седем години по-късно, през 1812, от египетската армия под командването на сина на Мехмед Али паша Тосун паша.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Началото на войната с Русия (Османско-руска война от 1806–1812) и затварянето на проливите", "ea170804"], "d": ["След като Селим III, приближил се към Франция след победата на Наполеон при Аустерлиц, въпреки руския натиск свали влашкия и молдовския войвода, руските армии окупираха двете княжества и войната започна. Османската държава затвори проливите за руския флот; в отговор и Англия застана на страната на Русия и изпрати флот към Истанбул. Тази война, която щеше да продължи шест години, преплетена с Кабакчъйския бунт и свалянето на Селим III, щеше да приключи с загубата на Бесарабия по Букурещкия мир от 1812", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Пристигането на английския флот пред Истанбул (операцията на Дъкуърт)", "195bb58f"], "d": ["Англия, която искаше да принуди Османската държава да скъса връзката си с Франция, прекара флота под командването на адмирал Дъкуърт през Чанаккале и го закотви пред Истанбул. С насочването и на френския посланик Себастиани населението на Истанбул се мобилизира, крайбрежните батареи бяха засилени в рамките на дни и флотът бе принуден да се оттегли, без градът да бъде обстрелян; на връщане той понесе тежки загуби при Чанаккале. Това, че столицата за пръв път е била заплашена толкова отблизо от чужд флот, постави въпроса за проливите в центъра на европейската дипломация.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Удушаването на Мустафа IV", "eeb75c20"], "d": ["След като Alemdar Mustafa Paşa бе нападнат и загина и размирниците поискаха да тръгнат към двореца, сваленият от трона Мустафа IV бе удушен по заповед на брат си Махмуд II. Тялото му бе погребано в Bahçekapı, в тюрбето на баща му Абдюлхамид I; сред размирниците се разпространи слух, че ковчегът е празен.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Договорът от Кале-и Султание — мир с Англия и правилото за проливите", "fe282117"], "d": ["С договора, подписан с Англия след провала на операцията на Дъкуърт, войната между двете държави приключи и старите привилегии на английските търговци бяха върнати. Разпоредбата, съдържаща се в текста и наричана «кадим каиде» (древно правило), записа, че в мирно време никой чужд военен кораб не може да преминава през проливите. Този принцип стана юридическа основа на всички международни уредби, които щяха да оформят режима на проливите през XIX в.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Разгромът при Slobozia — обкръжаването на Дунавската армия", "54b60fd1"], "d": ["По-голямата част от османската армия, преминала Дунав пред Русе, бе притисната при Slobozia с обкръжаващата маневра на Кутузов от отсрещния бряг на реката и оставена да гладува. Хиляди войници бяха принудени да се предадат; силата, с която разполагаше великият везир, на практика се стопи и Високата порта бе принудена след месец да поиска примирие. Това поражение е пряката причина за съгласието за отстъпване на Бесарабия с Букурещкия договор от 1812", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Възвръщането на Белград и потушаването на Първото сръбско въстание", "06f56f52"], "d": ["Сръбските бунтовници, лишени от руска подкрепа с Букурещкия договор, не издържаха пред съвместната операция на силите от Босна и Румелия; Хуршид Ахмед паша влезе в Белград и деветгодишното въстание бе напълно потушено. Карагеорги избяга в Австрия, санджакът Смедерево отново бе подчинен на пряко османско управление. Но приложените строги мерки щяха да предизвикат две години по-късно второ и трайно въстание под водачеството на Милош Обренович.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Второто сръбско въстание и кнежеството на Милош Обренович", "e6e82ad2"], "d": ["Срещу тежките мерки, приложени след потушаването на първото въстание, избухна ново въстание под водачеството на Милош Обренович; този път Високата порта предпочете споразумението пред сила. С постигнатото споразумение Милош бе признат с титлата «главен княз», а правомощията за събиране на данъци и за управление на вътрешните работи бяха оставени на сръбските князе. Това първо ядро на фактическата автономия стана начало на процеса, водещ към фермана от 1830 и към независимостта от 1878", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Въстанието във Влашко — преминаването на Прут от Ипсиланти и въстанието на Владимареску", "67d46a98"], "d": ["Александър Ипсиланти, генерал в руската армия, преминавайки Прут от името на Филики Етерия, се опита да започне общо гръцко въстание във Влашко и Молдова; в същите дни и Тудор Владимареску вдигна местните селяни. Двете движения не можаха да се обединят: на призива на Ипсиланти да се бият заедно срещу турците Владимареску отговори «Аз не съм въстанал срещу турците, а срещу гърците» и скоро бе убит от хората на Ипсиланти. Въстанието бе потушено от османските сили през май, но фенерският войводски ред приключи и пламъкът на въстанието се прехвърли към Морея.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Основаването на Втората саудитска държава в Рияд", "34dad3bd"], "d": ["Шест години след падането на Dir'iye през 1818 и срутването на първата саудитска държава Тюрки бин Абдуллах изгони египетските гарнизони от Неджд и създаде нов саудитски емират със седалище Рияд. Новата структура предпочете да остане в Неджд, избягвайки да стигне до Хиджаз, и се държеше далеч от пряк сблъсък с османско-египетските сили. Тази втора държава щеше да просъществува до края на века и да формира второто звено на веригата, водеща към основаването на днешна Саудитска Арабия. Друго място, загубено на същата дата: Dir'iye (Неджд).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Договорът от Акерман — отстъпки на Сърбия и на княжествата", "c75f15d0"], "d": ["Османската държава, останала без армия веднага след премахването на еничарския оджак, бе принудена да приеме тежък договор пред ултиматума на Русия. Обещаната на Сърбия автономия бе потвърдена, прието бе, че влашките и молдовските войводи не могат да бъдат сваляни без руско одобрение и на руските търговски кораби бе дадена пълна свобода в проливите. Когато две години по-късно Високата порта обяви заради гръцкия въпрос, че не признава договора, Русия щеше да го вземе за повод за война.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Премахването на тимарската система", "84d5d1d6"], "d": ["Година след премахването на еничарския оджак около 5 200 тимарлийски спахии в петдесет и три санджака в Румелия и Анатолия бяха превърнати, заедно с тимарските им доходи, в конница на Асакир-и Мансуре. Така тимарският режим, четиривековният гръбнак на османския поземлен, данъчен и военен ред, фактически приключи. Освободените тимари бяха прехвърлени на хазната и бе отворен пътят към преминаването към централна платена армия и парична данъчна система.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Основаването на Тъбхане-и Амире — началото на модерното медицинско образование", "ac3e57c0"], "d": ["За да подготвя лекари и хирурзи за новосъздадената армия на Асакир-и Мансуре, по предложение на хекимбашъ Мустафа Бехчет ефенди бе открита в Шехзадебашъ Тъбхане-и Амире. Уроците бяха организирани по европейска учебна програма и обучението първоначално се водеше на френски; няколко години по-късно бе основана и Джеррахане-и Амире и двете институции бяха обединени. Това училище, смятано за начало на модерното медицинско обучение в Турция, се приема за корен на днешния Истанбулски медицински факултет.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Началото на османско-руската война от 1828–1829", "9dff4e05"], "d": ["След изгарянето на флота при Наварин и заявлението на Високата порта, че не признава договора от Акерман, Русия обяви война едновременно на два фронта. Тъй като еничарският оджак бе току-що премахнат, а новата армия бе в процес на създаване, османската отбрана бе слаба от самото начало; докато руснаците преминаваха Дунав, на изток те взеха Карс и Ахалцихе. Руската армия, напреднала за една година до Одрин, щеше да наложи тежките условия на Одринския договор от 1829 и независимостта на Гърция.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Първият договор със Съединените американски щати", "d737516f"], "d": ["С договора за търговия и мореплаване, подписан след години контакти, САЩ получиха в османската страна статут на най-облагодетелствана нация и право на търговски проход през проливите. Една отделна тайна клауза предвиждаше османците да поръчват при желание кораби в американските корабостроителници и да купуват готови кораби и дървен материал; Сенатът на САЩ ратифицира договора, но отхвърли тази тайна клауза с 27 гласа срещу 18. Корабният път все пак не се затвори: Хенри Екфорд през 1831 продаде на османците донесения от него кораб, а американските майстори, работещи в Айналъкавак, придобиха на флота нови типове кораби. Този договор стана документ за първите всеобхватни отношения на Османската държава с държава извън Европа.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Прекратяването на управлението на Кьолемен в Багдад", "7e1d38a3"], "d": ["Махмуд II, който водеше политика на централизация, обяви за бунтовник багдадския управител Давуд паша, който не изпращаше исканите пари и бе накарал да бъде убит изпратения от центъра служител. Силите под командването на Али Ръза паша превзеха града след обсада, продължила деветдесет дни, и кьолемените бяха почти изцяло прочистени. Така полунезависимото управление на Кьолемен, продължило от 1704, приключи и Ирак отново бе подчинен директно на центъра.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Основаването на Мекаб-и Харбийе в казармата Maçka", "bf31c7d9"], "d": ["За да осигури на Асакир-и Мансуре-и Мухаммедийе офицери, подготвени по европейски образец, в казармата Maçka бе открито Мекаб-и Фюнун-ъ Харбийе. На учениците се преподаваха математика, картография, фортификация и чужд език; скоро бяха изпратени студенти във Виена и Париж и кадрите бяха засилени. Това училище стана мястото, където се роди традицията на офицери, завършили училище, в османската армия и следователно на новото поколение военни интелектуалци, което щеше да се появи в края на XIX в.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Директното подчиняване на Триполитания на центъра — краят на династията на Караманлиите", "faabcb96"], "d": ["Заради борбите за трона в семейство Караманлъ и нарасналия европейски натиск след окупацията на Алжир от Франция през 1830 Високата порта се намеси директно в Триполитания. Изпратеният от Истанбул флот влезе в града, последният бей Караманлъ бе свален и доведен в Истанбул, а еялетът бе предаден на назначен от центъра управител. С края на 124-годишния династичен период бе укрепено последното парче земя в Северна Африка, управлявано директно от Османската държава.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Премахването на дефтердарството и създаването на Министерство на финансите", "89f8125e"], "d": ["С отмяната на поста дефтердар, начело на класическия османски финансов ред, бе създадено Министерство на финансите (Малие Незарети) като европейско министерство и разпръснатите хазни бяха събрани в едни ръце. През същата година и останалите звена на Високата порта бяха реорганизирани под името незарети и бе преминато към структура на модерен министерски съвет. Тази уредба бе една от най-важните стъпки, подготвили административната основа на Танзиматския ферман, който щеше да бъде обявен година по-късно.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Настаняването на англичаните в Аден", "ddbd556b"], "d": ["Англия, опирайки се на търговското и приятелско споразумение, подписано през 1802 с лахичкия султан Ахмед бин Абдулкерим, стовари войска в пристанището Аден и взе града под контрол. Това пристанище, пазещо входа на Червено море, се превърна във ключова точка на английската имперска стратегия като въглищна база по пътя към Индия. Макар претенцията на Османската държава за Йемен да продължи на хартия, фактическото ѝ господство по южния бряг не се върна повече след тази дата.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Връщане на брега на Тихама: овладяването на Худейда, Зебид и Моха", "353982d2"], "d": ["На йеменския бряг, останал безстопанствен след оттеглянето на египетската армия през 1840, силите под командването на Тевфик паша, под надзора на мекканския шериф, слязоха и присъединиха към османското управление пристанищата Худейда, Зебид и Моха. Макар да бе искано напредване до Сана, поради съпротивата на населението бе върнато към Худейда; така планините останаха при зейдитските имами, а османското господство в продължение на двайсет и три години продължи само в ивицата Тихама. Вътрешен Йемен щеше да бъде възвърнат едва през 1872 с похода на Ахмед Мухтар паша.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Конвенцията от Балта Лиман: общо османско-руско покровителство във Влашко и Молдова", "d3bb22e9"], "d": ["След като революциите от 1848 се прехвърлиха във Влашко и Молдова, османски и руски сили бяха окупирали заедно княжествата. С конвенцията, подписана в Балта Лиман, бе решено войводите да не бъдат избирани, а назначавани от падишаха за седем години и двете държави да установят общ контрол в региона. Споразумението, като запази на хартия османския суверенитет, даде на Русия право на фактическо партньорство и ускори отделянето на дунавските княжества от османците.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Въпросът за унгарските бежанци: убежището на Кошут и приятелите му в Османската империя", "1c7d7ef4"], "d": ["След потушаването на унгарската революция от 1848–1849 с руско-австрийска намеса Лайош Кошут и хиляди унгарски и полски бежанци потърсиха убежище в османските земи. Австрия и Русия поискаха остро връщането на бежанците; Високата порта, с подкрепата на Англия и Франция, отказа връщането и настани групата в Кютахя. Околните на Кошут останаха там около осемнайсет месеца, стотици бежанци приеха исляма и постъпиха на османска служба. Събитието бе прието за една от редките дипломатически победи, издигнали престижа на Танзиматска Османска империя в европейското обществено мнение.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Основаването на Енджумен-и Даниш: първата османска академия в Истанбул", "6fda1365"], "d": ["Създаденият по решение на Меджлис-и Маариф-и Умумийе Енджумен-и Даниш е първата османска научна академия, създадена за подготовка на научни и учебни книги на турски език. Тя бе открита с церемония на 18 юли 1851 в сградата на Дарюлмаариф; сред местните и чуждестранните ѝ членове бе и Ахмед Джевдет паша. Макар и краткотрайна, произведения като Тарих-ът и Каваид-и Османийе на Джевдет паша бяха продукт на тази институция и тя се смята за крайъгълен камък в превръщането на турския в език на науката.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Победата при Олтеница: първият османски успех на Дунавския фронт", "a660ad2f"], "d": ["В началния етап на Кримската война сердар-и екрем Омер Лютфи паша, преминавайки Дунав, отблъсна при Олтеница руските сили с тежки загуби. Победата, спирайки руското напредване още в самото начало на войната, показа на Европа силата, придобита от османската армия с обучение след Танзимата. Този успех подготви психологическата почва, улеснила решението на Англия и Франция да встъпят във войната на страната на османците.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Съюзен договор с Англия и Франция в Истанбул", "04809278"], "d": ["Съюзният договор, подписан в Кримската война срещу Русия между Османската държава и Англия и Франция, определи съвместни действия на трите държави и съюзниците да не сключват отделен мир, преди войната да приключи. Така за първи път в историята си Османската държава встъпи във военен съюз с големите европейски държави като равноправна страна. Този договор образува и юридическата основа на официалното приемане на османците в системата на европейските държави в Париж две години по-късно.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Основаването на Шехремането на Истанбул: първата модерна общинска организация", "be4af27f"], "d": ["Инфраструктурната криза, породена от съюзническите войници, натрупали се в Истанбул по време на Кримската война, и от нарастващото население, разкри недостатъчността на класическото градско управление, центрирано върху кадията. С Шехремането, създадено по европейски образец, чистотата, наркът, контролът на чаршията и строително-устройствените дейности бяха събрани в едни ръце; през следващата година в Бейоглу-Галата бе създадена Шестата община (Алтънджъ Даире-и Беледийе) като пилотен район. Тази стъпка се приема за начало на модерното общинско управление в Османската империя.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Парижки договор: краят на Кримската война и приемането на османците в системата на европейските държави", "4aee0e2a"], "d": ["С Парижкия договор, сложил край на Кримската война, Османската държава бе обявена за равноправен член на европейското международно право и териториалната ѝ цялост бе поставена под общата гаранция на големите държави. Черно море бе неутрализирано, претенцията на Русия за покровителство над православните поданици, която имаше от Кючук-Кайнарджа, бе обявена за невалидна, а южната част на Бесарабия (казите Кили, Кагул, Измаил и Болград) бе дадена на Молдова. Но същият договор, превръщайки Ислахатския ферман в международно задължение, отвори и вратата на намесата във вътрешните работи.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Откриването на двореца Долмабахче: преместването на административния център от Топкапъ", "71ad26d0"], "d": ["Дворецът, поръчан през 1842 от Абдюлмеджид на семейство Балян, бе открит след четиринайсетгодишно строителство и административният център на държавата бе преместен от четиривековния Топкапъ на брега на Босфора. С европейския си стил, кристалното си стълбище и Залата на церемониите дворецът стана каменният израз на претенцията на Танзимата за европеизация. Огромната му цена пък се превърна в една от най-критикуваните пера от годините, когато османските финанси влязоха във въртопа на външното задлъжняване.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Обединението на Влашко и Молдова под управлението на Куза: раждането на Румъния", "baef4da5"], "d": ["На проведените след Парижкия договор избори и двете княжества избраха полковник Александру Йоан Куза за войвода и така осъществиха фактическо обединение. Макар Високата порта и Австрия да се противопоставиха, те бяха принудени да приемат свършения факт, подкрепен от Франция. Този съюз, останал на хартия зависим от османците, щеше да приеме през 1862 името Румъния, а през 1877 да обяви едностранно независимостта си; той е повратна точка в разпадането на османското господство по Дунав.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Събитието Кулели: първият опит за преврат срещу Абдюлмеджид в Истанбул", "e3653b21"], "d": ["Тайно общество от военни и цивилни, недоволно от политиката на Танзимата и от равенството, което Ислахатският ферман даваше на немюсюлманите, бе заловено на събрание в джамията Кълъч Али паша, докато планираше да свали падишаха от трона. Тъй като обвиняемите бяха съдени в казармата Кулели, събитието е известно с това име; смъртните присъди бяха заменени със заточение. Приема се за първия опит за дворцов преврат в османската история, предприет от организация, създадена по идеологически мотиви.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Друзско-маронитската гражданска война в Ливанската планина и събитията в Дамаск", "5595fdd6"], "d": ["Сблъсъците, избухнали през май 1860 с убийството на двама друзи близо до Сайда, се превърнаха в най-кървавата друзско-маронитска гражданска война в планината и през юли се прехвърлиха в Дамаск, завършвайки със смъртта на хиляди християни. След френския десант Високата порта изпрати в региона Фуад паша с извънредни пълномощия; беше проведена строга наказателна акция. Събитията дадоха повод за европейска намеса и бяха пряката причина Ливан да получи специален статут.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Започване на излизането на Терджюман-ъ Ахвал: първият частен турски вестник в Истанбул", "24792957"], "d": ["Терджюман-ъ Ахвал, издаван от Агях ефенди, като Шинаси поеме редакторската работа, е първият турски вестник, излязъл без държавна подкрепа. В уводната статия на първия му брой бе защитено правото на народа да говори за собствените си работи; вестникът, публикувайки в продължения пиесата на Шинаси Шаир Евленмеси, отвори вратата и на модерната турска литература. Раждането на понятието обществено мнение и на опозиционния печат в Османската империя се свързва с тази дата.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Уставът на Ливанската планина: привилегирован статут на мютесарифлък за Ливан", "bf375603"], "d": ["Уставът, изготвен след клането от 1860 под натиска на големите държави, превърна Ливанската планина в привилегирован мютесарифлък, директно подчинен на Високата порта и управляван от административен съвет, формиран според баланса между вероизповеданията. Бе поставено условие мютесарифът да бъде католик християнин, османски поданик, и назначаването му да бъде представяно за одобрение на големите държави; първият мютесариф бе Давуд паша. Този ред щеше да продължи до 1915 и да формира ядрото на модерната ливанска държава.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Смъртта на Абдюлмеджид и възцаряването на султан Абдюлазиз", "27204d7c"], "d": ["След като Абдюлмеджид, подписал по време на двайсет и две годишното си управление Танзиматския и Ислахатския ферман, бе покосен от туберкулоза, на трона се възкачи брат му Абдюлазиз. В първите години новият падишах даваше надежда с мерки за икономии и скромния си начин на живот; той превърна флота в една от малкото сили на света. Но в края на управлението му тежкият външен дълг, банкрутът от 1875 и балканските въстания щяха да се натрупат и да подготвят почвата за свалянето през 1876", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Приемането на името Румъния от обединените княжества", "d960e3fc"], "d": ["Влашко и Молдова, фактически обединени през 1859 с двойното избиране на Куза, през 1862, събирайки парламентите и правителствата си под един покрив в Букурещ, официално приеха името Румъния. Макар Османската държава юридически да запази титлата сюзерен и годишния данък, фактически загуби контрола си над княжеството. Краят на четиривековното османско влияние на север от Дунав се символизира с тази дата.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Присъединяването на Севакин, Масауа и Дахлак към Египет", "a0924860"], "d": ["Масауа, която през 1846 султан Абдюлмеджид бе дал на египетския хедив Мехмед Али паша заедно със Севакин като салияне (отпускане на доход), по времето на хедив Исмаил паша бе включена, заедно с Дахлак и Севакин, в имотите на Египет и организирана със статут на каймакамство. Така тези три пристанища на африканския бряг на Червено море, оставайки юридически османска земя, преминаха административно директно от Високата порта към Кайро — влизайки в същия зависим слой като съседите си Египет и Судан.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Началото на Критското въстание (1866–1869)", "3679b861"], "d": ["Широкомащабното въстание, избухнало на острова с открита подкрепа на Гърция, направи за първи път международен въпрос исканието на критските гърци за енозис (присъединяване към Гърция). Трите години упорита планинска война нанесоха тежки загуби на османската армия и предизвикаха голям отзвук в европейското общество. Въстанието можа да бъде угасено едва през 1868, когато Али паша отиде на острова и въведе устав, даващ широки привилегии.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Изтеглянето на последните османски гарнизони от Белград и сръбските крепости", "b34217db"], "d": ["Под натиска на големите държави и упоритото искане на княз Михаил Високата порта се съгласи да опразни последните военни бази, останали ѝ в Сърбия; на 18 април 1867 османското знаме в Белградската крепост бе свалено и ключовете бяха предадени на княза. Така фактическото османско военно присъствие, продължило от 1521, приключи и последната голяма пречка по пътя на Сърбия към независимост отпадна. Сюзеренитетът на падишаха бе сведен само до въпрос на символично знаме и данък.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Предоставянето на титлата хедив на египетските управители", "09e10c12"], "d": ["В резултат на усилното лобиране на Исмаил паша, от третото поколение на династията на Кавалалъ, и парите, които той изля в Истанбул, на египетския управител бе дадена титлата хедив, подчертаваща превъзходството му над останалите управители. През същите години бе променен и редът на наследяването, така че да преминава от баща на син, и на Египет бяха предоставени правомощия със суверенен характер като външно задлъжняване, даване на медали и държане на консулства. Тези стъпки са първото звено на веригата, ускорила юридическото откъсване на Египет от османците.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Критският устав: широки административни привилегии за острова", "12052262"], "d": ["За да сложи край на тригодишното въстание, великият везир Али паша лично отиде на острова и с издадения с одобрението на падишаха устав на критяните бяха предоставени смесени административни съвети, местни съдилища, използването на гръцки език в официалните актове и данъчни облекчения. Тази уредба задържа османското господство на острова още трийсет години. Но привилегиите, дадени на християнското население, отслабиха положението на мюсюлманските критяни и посяха семената на кризата от 1896–1898", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Откриването на Шура-й Девлет: основаването на Османския държавен съвет", "70b16497"], "d": ["С ирадето от 5 март 1868 Меджлис-и Ахкям-ъ Адлийе бе разделен на две: административно-законодателните работи бяха оставени на Шура-й Девлет, а съдебните — на Диван-ъ Ахкям-ъ Адлийе; институцията бе открита с церемония във Високата порта и за първи председател бе назначен Мидхат паша. Тя бе натоварена да изготвя законопроекти, да решава административни спорове и да води процесите срещу чиновници. Със смесената си структура от мюсюлмански и немюсюлмански членове тя се смята за първото институционално приложение на идеята за разделение на властите в Османската империя.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Откриването на Суецкия канал: скъсяване на пътя към Индия през Египет", "377ccd04"], "d": ["Строителството, започнало през 1859, продължи десет години и каналът, свързващ Средиземно с Червено море, с дължина 163 километра, бе пуснат в експлоатация с грандиозна церемония. Когато пътят, свързващ Европа с Индия, се скъси с хиляди мили, Египет изведнъж стана ключова точка на световната търговия. Тази геостратегическа стойност щеше да бъде главната причина за окупацията на Египет от Англия тринайсет години след откриването на канала, а дългът, който каналът стовари на Египет, щеше да доведе хедивството до банкрут.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Основаването на Българската екзархия: отделянето на българската църква от Фенер", "33a8272c"], "d": ["С падишахски ферман бе създадена самостоятелна българска църква (екзархия), отделна от Гръцката патриаршия, и бе оставено на народно допитване кои каази ще бъдат подчинени на екзархията. Макар Високата порта да направи тази стъпка, за да пречупи гръцкото влияние, резултатът се оказа обратен: църквата се превърна в организиран център на българската национална идентичност и на българската претенция към Македония. Така бе положена институционалната основа на българо-гръцко-сръбското съперничество на Балканите и на въстанията от 1876", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Поставянето на Асир под пряко управление", "4559e099"], "d": ["Когато стратегическото значение на Червено море нарасна с отварянето на Суецкия канал, стана ясно, че планините Асир, разположени насред сухопътния път към Йемен, не могат да бъдат оставени без контрол. Силите на Redif Paşa, потеглил в йеменския поход, навлязоха в Абха и свързаха областта пряко с османската власт; бе учреден санджакът Асир. Поради планинската география и влиянието на Идриси това господство никога не се утвърди изцяло.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Походът на Мидхат паша в Неджд: възстановяване на османското господство в Лахса", "7db51461"], "d": ["Багдадският управител Мидхат паша, възползвайки се от борбата за трона в рода Сауд, изпрати войска към западния бряг на Персийския залив и присъедини областта Лахса към вилаета Басра под името санджак Неджд. Абдуллах бин Фейсал бе назначен за мютесариф и османското господство бе установено на хартия. Походът имаше за цел да спре разпространяването на английското влияние в Залива и още същата година доведе до това и Катар да премине под османски контрол.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Смъртта на великия везир Али паша: краят на танзиматските кадри", "1cf0141c"], "d": ["Със смъртта на Али паша, който след смъртта на Фуад паша през 1869 носеше сам политиката на Танзимата, поколението на майсторите дипломати, ръководили през трийсет години външната политика на държавата, се изчерпа. Проруското и своеволно управление на заелия мястото му Махмуд Недим паша затвърди личното управление на Абдюлазиз. В рамките на петте години след смъртта на Али паша финансите банкрутираха, Балканите се вдигнаха и промяната на султаната стана неизбежна.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Установяването на османски контрол в Катар", "3b453165"], "d": ["По покана на шейх Касим бин Сани, намиращ се под английски натиск, османските сили слязоха на полуостров Катар и през есента на 1871 в региона бе установен османски контрол. Катар бе организиран като каза към санджака Неджд и шейхът бе назначен за каймакам. Този ход стана най-конкретното придобивка на напредналата политика на Мидхат паша срещу Англия в Залива; османското знаме се вееше на полуострова до 1913", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Ферман за наследяването на Тунис — бейството на семейството на Mehmed Sâdık Paşa", "1509ebb0"], "d": ["С фермана, издаден по инициатива на Hayreddin Paşa, изпратен в Истанбул от тунизийския бей Mehmed Sâdık Paşa, който се възползва от поражението на Франция срещу Прусия, Тунис бе даден на Mehmed Sâdık Paşa и неговото потомство по реда на наследяването, като остава пряко подчинен на Истанбул. Без разрешението на падишаха нямаше да се водят преговори за война и мир, нито щеше да се отстъпва земя от страната на когото и да било, а исканията на Османската империя за войници щяха да бъдат изпълнявани. Франция не призна фермана; десет години по-късно окупира Тунис.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Превземането на Сана: възстановяване на османския авторитет в Йемен", "978e20a0"], "d": ["Когато със Суецкия канал стратегическата стойност на Червено море нарасна, Високата порта изпрати в Йемен армията фирка-и ихтиятийе под командването на Ахмед Мухтар паша. С превземането на Сана държавният авторитет бе възстановен във вътрешен Йемен, фактически загубен от два века, и регионът бе превърнат във вилает. Но борбата със зейдитските имами не приключи никога; въстанията от 1891, 1898 и 1904 образуваха най-скъпия и най-продължителен вътрешен фронт на османците. Други места, присъединени на същата дата: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Началото на Херцеговинското въстание: ново разпалване на Източния въпрос", "571b18ec"], "d": ["Въстанието на християнските селяни около Невесине заради тежките данъци и натиска на аяните скоро се разпростря върху цяла Херцеговина и бе подхранено от доброволци от Сърбия и Черна гора. Въстанието, което доведе до реформаторски натиск от Австрия и Русия, предизвика през следващата година българските въстания и обявяването на война от Сърбия и Черна гора. Така бе счупено първото звено на голямата верига, водеща към войната от 93 и към загубата на Балканите с Берлинския договор.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Банкрутът на османските финанси: намаляване наполовина на плащанията по външния дълг", "2cac2fa5"], "d": ["Последователните заеми от 1854, разходите на Кримската война, дворцовите строежи и анатолийският глад от 1873–74 превърнаха бюджетния дефицит в пропаст, надхвърляща пет милиона лири. Правителството на Махмуд Недим паша, обявявайки, че плащанията на лихви и главница по дълга ще бъдат намалени наполовина за пет години, фактически обяви мораториум. Това решение, предизвикало голяма реакция на европейските борси, започна процеса, който шест години по-късно щеше да завърши с Мухарремския декрет и създаването на Дюйун-и Умумийе.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Свалянето на Мурад V и възцаряването на Абдюлхамид II", "cffb2271"], "d": ["Мурад V, възкачил се на трона след свалянето на Абдюлазиз, поради смъртта на чичо му и душевното му здраве, разклатено от събитието Черкес Хасан, стана неспособен да изпълнява длъжността си; от деветдесет и трите дни на управлението му само в седем разсъждението му е било в ред. С фетва на шейхюлисляма той бе свален и на негово място бе поставен брат му Абдюлхамид II. Новият падишах се възкачи на трона, обещавайки на Мидхат паша, че ще обяви конституция; започваше епоха, която щеше да продължи тридесет и три години.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Цариградската конференция (Tersane Konferansı): натискът на големите държави за реформи на Балканите", "b5006a2c"], "d": ["Конференцията, събрана от големите държави в Истанбул за разрешаване на балканската криза, поиска България да бъде разделена на два автономни вилаета и в Босна и Херцеговина да бъдат приложени реформи под международен контрол. Високата порта, обявявайки с оръдейни салюти в деня на откриването на конференцията провъзгласяването на Канун-и Есаси, се опита да посрещне натиска с конституционна реформа. Делегатите сметнаха това за протакане и се разпръснаха на 20 януари 1877; четири месеца по-късно Русия обяви война.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Откриването на първия Меджлис-и Мебусан в Долмабахче", "429bb279"], "d": ["Избраните съгласно Канун-и Есаси 115 депутати за пръв път се събраха на 19 март 1877 на церемония в Залата на церемониите на двореца Долмабахче; така в османската история започна периодът на представителния парламент. Мюсюлманските и немюсюлманските депутати разпитваха остро правителството, обсъждаха ръководенето на войната и отговорността на назирите. Тази смела опозиция щеше да бъде главната причина за съкращаването на живота на парламента.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Началото на защитата на Плевен: съпротивата на Гази Осман паша", "0e04a878"], "d": ["Осман паша, който от Видин тръгна към Плевен, за да прекъсне пътя към Истанбул на руската армия, преминала Дунав във войната от 93, укрепи градчето с табии и окопи и започна петмесечна легендарна защита. Три последователни големи руско-румънски атаки бяха отблъснати с тежки загуби и армията, водена лично от цар Александър II, бе принудена да премине към обсада. Плевен влезе в историята като най-блестящия успех в защитата на османската армия през XIX в.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Падането на Плевен: срутването на Дунавския фронт", "185e7602"], "d": ["Осман паша, на когото в петмесечната обсада се изчерпаха припасите, предприе излаз по река Вит; когато бе ранен и пленен, градът се предаде. Руските командири поздравиха пленения паша, като му върнаха сабята, и на Осман паша бе дадена титлата «Гази». С падането на Плевен пред руската армия пътят се отвори; в рамките на два месеца паднаха София, Пловдив и Одрин и руските авангарди стигнаха до Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Окупацията на София от руските сили", "ef369d22"], "d": ["Руската армия, преминала Балкана след падането на Плевен, влезе в останалата беззащитна София. Градът нямаше да се върне повече под османско управление и щеше да стане в края на 1878 столица на автономното Княжество България, а през 1879 и фактическа такава. На картата София излиза от пряко османско управление от тази дата и преминава към временна руска окупация, а след това към автономно българско управление.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Одринското примирие: замлъкване на оръжията във войната от 93", "1f899180"], "d": ["След последователното падане на София, Пловдив и Одрин и достигането на руската армия до бреговете на Мраморно море Високата порта бе принудена да поиска примирие. Примирието, подписано в Одрин, наложи на османците предварителните условия на мира като автономия за България, независимост на Черна гора, Сърбия и Румъния и тежко военно обезщетение. Тези условия щяха да се превърнат месец по-късно в текст на договор в Сан Стефано.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Безсрочното закриване на Меджлис-и Мебусан от Абдюлхамид II", "e770b540"], "d": ["След острите критики на депутатите, които държаха правителството и двореца отговорни за катастрофалния край на войната, Абдюлхамид II, опирайки се на правомощието, което Канун-и Есаси му даваше, закри парламента безсрочно. Така първият османски парламент, проработил около единайсет месеца, се затвори и започна епохата на истибдада, която щеше да продължи тридесет години. Парламентът щеше да се събере отново едва след революцията от 1908", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Санстефанският мирен договор: проектът за Велика България", "2c7cc611"], "d": ["Санстефанският мирен договор, сложил край на войната от 93, създаваше огромна автономна България, простираща се до Егейско море и включваща Македония; признаваше независимостта на Сърбия, Черна гора и Румъния; отстъпваше на Русия Карс, Ардахан, Батум и Doğubayazıt и налагаше освен това невъзможно за изплащане военно обезщетение. Този текст, сваляйки Русия към Средиземно море, предизвика острата реакция на Англия и Австрия. Той бе преустроен в рамките на четири месеца, без да бъде приложен, с Берлинския конгрес; въпреки това остана като документът, обявил края на Османска Румелия.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Карс, Ардахан и Батуми бяха отстъпени на Русия — elviye-i selâse", "99bdfad2"], "d": ["С Берлинския договор Османската държава отстъпи на Русия Карс, Ардахан и Батуми срещу част от военното обезщетение; Догубаязит и долината на Eleşkirt, дадени на Русия в Санстефанския договор, останаха при Османската империя. Макар Батуми да бе даден като свободно пристанище, този му статут можа да се запази само до 1886 Руснаците направиха Карс вилает, подчинен на Закавказкото генерал-губернаторство със средище Тифлис; население, достигащо 100 000 души, от elviye-i selâse бе принудено да се пресели към страната на Ерзурум. С този договор Южна Бесарабия (Килия, Кагул, Болград) бе върната от Румъния на Русия.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Окупацията на Босна и Херцеговина и Yenipazar от Австро-Унгария", "e5f901df"], "d": ["Опирайки се на правомощието, дадено от Берлинския договор, австро-унгарските армии навлязоха в Босна; макар османското правителство да се бе съгласило да не оказва съпротива, местното мюсюлманско-православно население в Сараево и Мостар грабна оръжието и оказа тримесечна упорита съпротива. Окупацията можа да бъде завършена едва на 20 октомври 1878 Юридическият суверенитет на падишаха продължи на хартия до 1908, но четиривековна османска Босна бе фактически загубена и започна голяма вълна на мюсюлмански изселнически поток. Други места, загубени на същата дата: Banaluka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Мухарремският декрет и създаването на Управлението Дюйун-и Умумийе", "02b7cc03"], "d": ["Преговорите, водени след банкрута от 1875 с представители на държавите кредитори, завършиха с декрета от 28 мухарем 1299 (20 декември 1881): главницата на дълга бе намалена с повече от половината, а в замяна най-доходоносните приходни пера като солта, тютюна, коприната, гербовия налог и риболовните такси бяха предадени на Управлението Дюйун-и Умумийе, управлявано директно от кредиторите. Тази администрация, в която работеха хиляди чиновници, се превърна в отделна финансова организация в рамките на държавата. Приема се за датата, на която османската финансова независимост фактически приключи.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Севакин — единственото пристанище, което не падна в ръцете на Махди", "5a37b198"], "d": ["Докато от февруари 1884 всички области на Източен Судан освен Севакин преминаваха под господството на Мухаммед Ахмед ал-Махди, пристанището устоя с военната защита на трибатальонна английска сила под командването на генерал Греъм. Това бе началото на период, в който фактическото и юридическото положение се разделиха: макар крайбрежието да бе фактически под английски военен контрол, административната му връзка щеше да бъде през 1885 взета от Египет и свързана директно с вилаета Йемен, тоест с Високата порта — този ред продължи, докато приключи през 1888 с окупацията на Зейла от Франция.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Убийството на Мидхат паша в затвора на Таиф", "f4562261"], "d": ["Мидхат паша, архитектът на Канун-и Есаси и символично име на Първата конституция, бе обявен за виновен на Съда на Йълдъз във връзка със смъртта на Абдюлазиз и бе изпратен в Таиф, като смъртната му присъда бе заменена със заточение. Според записа на TDV в нощта на 7–8 май 1884 той бе удушен в килията си, като официалната причина бе обявена болестта «ширпенче». Смъртта му се превърна в символ на прочистването на конституционната опозиция по времето на Абдюлхамид II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Предоставянето на германците на концесията за железницата Хайдарпаша–Анкара", "5705b163"], "d": ["С падишахски указ (ирадето) концесията за строеж и експлоатация на линията Хайдарпаша–Анкара бе дадена на банкера Алфред фон Каула, представляващ Deutsche Bank, и бе създадена Анадолската железопътна компания. Тази концесия стана повратна точка, пречупила английско-френския монопол в османския транспорт и външна политика и утвърдила германското влияние. Заедно с концесията за Багдадската линия, която щеше да бъде дадена на същата компания единайсет години по-късно, щеше да се роди мечтата «Берлин–Багдад», превърнала се в една от главните оси на съперничеството на големите сили преди Първата световна война.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Основаването на Дружество «Иттихад-и Османи» в Истанбул", "b7187939"], "d": ["Четирима ученици на Военномедицинското училище основаха като тайна организация срещу истибдадското управление Дружество «Иттихад-и Османи»; тази структура скоро се превърна в Дружество «Иттихад ве Теракки», което щеше да събере под покрива си всички опозиционни елементи на младотурското движение. Организацията, основана на принципа на клетките, се слея с изгнаниците в Европа и офицерите в Солун. Кадрите, които през 1908 щяха да накарат да бъде обявена Втората конституция и след 1913 да управляват сами държавата, излязоха от тази малка ученическа клетка.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Нападението над Османската банка: акцията на дашнаците в Галата", "08b3095f"], "d": ["Въоръжена група на арменската организация Дашнакцутюн, с цел да привлече вниманието на Европа към арменския въпрос, превзе и взе за заложници седалището на Османската банка в Галата и заплаши да взриви сградата. Кризата приключи с намесата на посланиците, срещу извеждането на действащите лица от страната с кораб. Кървавите събития в Истанбул през дните след нападението бяха определящи за превръщането на арменския въпрос в лост за международна намеса.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Началото на османско-гръцката война от 1897: тесалийският фронт", "33e490ab"], "d": ["След стоварването на гръцки флот и войска в Крит и нападенията на чети по румелийската граница Османската държава обяви война. Османската армия, обучена от германската реформаторска мисия, напредна бързо в Тесалия и за един месец взе Yenişehir, Чаталджа и Dömeke; гръцката армия се разпадна. С намесата на големите държави спечелените земи бяха върнати, но войната остана като единствената категорична военна победа на епохата на Абдюлхамид II и не можа да предотврати фактическата загуба на Крит.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Предоставянето на германците на концесията за линията Кония–Багдад", "fd8b6cbd"], "d": ["След посещението на кайзер Вилхелм II в Истанбул и Дамаск през 1898 на Анадолската железопътна компания бе дадена предварителна концесия за линията, която щеше да се простира от Кония до Багдад и Басра. Проектът за Багдадската железница означаваше за османците засилване на централния контрол над арабските вилаети, а за Германия — достигане до Персийския залив. Този проект, на който Англия и Русия остро се противопоставиха, стана едно от най-спорните досиета на имперското съперничество, водещо към Първата световна война.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Началото на строежа на Хиджазката железница в Дамаск", "62f58f68"], "d": ["Линията, наредена с ирадето на Абдюлхамид II от 2 май 1900, бе започната на 1 септември 1900 с официална церемония в Дамаск. Проектът, изграден изцяло с дарения, събрани от ислямския свят, и с труда на османски инженери и войници, скъси пътуването на поклонниците Дамаск–Медина от четирийсет дни на пет. Той бе както престижно дело, укрепващо духовния авторитет на халифата, така и стратегическа инвестиция, засилваща военния контрол над Хиджаз.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Мюрцщегската програма: международен реформен контрол в Македония", "4c7464da"], "d": ["След Илинденското въстание руският и австрийският император се срещнаха в Мюрцщег и подготвиха нов пакет реформи за Македония. Програмата предвиждаше до османския главен инспектор да бъдат поставени двама чуждестранни цивилни агенти, жандармерията да бъде реорганизирана от европейски офицери и административните граници да бъдат променени по национален признак. Макар Високата порта да се съпротивлява с довода, че суверенните ѝ права се накърняват, пред общия натиск тя бе принудена да приеме; програмата стана един от основните фактори, ускорили организирането на младотурците сред младите офицери.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Смъртта на Мурад V", "396659a7"], "d": ["Мурад V, който през 1876 остана на трона около три месеца и бе детрониран, след опитите да бъде върнат на трона живя двадесет и осем години като затворник под строга охрана и умря от диабет. Бе погребан до майка си в Cedîd Havâtîn Türbesi в Yenicami. Остана в историята като падишахът, който е стоял най-кратко на трона.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Загубата на Сана в полза на имам Яхя", "e7f876cb"], "d": ["Въстанието, започнато през 1904 от зейдитския имам Яхя Хамидуддин, завърши през април 1905 с падането на Сана в края на обсадата; градът излезе от османско управление и по време на обсадата се появиха глад и епидемия. Планинската география на Йемен, дължината на линиите за снабдяване и местната легитимност на зейдитския имамат правеха османското господство тук крехко от самото му основаване. Градът щеше да бъде възвърнат пет месеца по-късно с цената на тежки загуби, но йеменският проблем нямаше да се затвори до 1918", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Атентатът при Йълдъз: бомбено нападение срещу Абдюлхамид II", "1ee2e1a6"], "d": ["Организацията Дашнакцутюн организира атентат, взривявайки ландо с часовников механизъм с бомба в каретата на падишаха, излизащ от петъчния селямлък; закъснението на Абдюлхамид с няколко минути, докато разговаряше с шейхюлисляма, му спаси живота. При взрива загинаха двайсет и шест души и над петдесет бяха ранени. Събитието втвърди още повече манията за сигурност на падишаха и истибдадското му управление, основано на шпионската организация; то стана и тема на стихотворението на Тевфик Фикрет «Бир Лахза-и Тааххур».", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Възвръщането на Сана: потушаването на въстанието на имам Яхя", "dec3b8f9"], "d": ["Въстанието, започнало през 1904 под водачеството на зейдитския имам Яхя, завърши през април 1905 с падането на Сана и в града се появиха глад и епидемия. Подкрепителните армии под командването на Али Ръза паша и Ахмед Фейзи паша с кампанията си между 15 юли и 1 септември 1905, подкрепена и от силите в Таиз, върнаха града с цената на тежки загуби и въстанието бе потушено. Кампанията в Йемен донесе на османската армия десетки хиляди загуби и огромно финансово бреме; сред офицерите в Румелия страхът от «заточение в Йемен» бе сред основните оплаквания, подхранващи организирането на младотурците.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Свикването на първия Меджлис-и Мебусан на Втората конституция", "e7fd2716"], "d": ["Парламентът, образуван с двустепенни избори, проведени след прекъсване от тридесет години, бе открит на 17 декември 1908 с речта на падишаха и за негов председател бе избран лидерът на младотурското движение Ахмед Ръза бей. Съставен от турски, арабски, албански, гръцки, арменски и еврейски депутати, парламентът бе последният голям опит на идеала на османизма. Но независимостта на България, анексията на Босна и обявеното от Крит присъединяване към Гърция бяха засенчили този оптимизъм още преди парламентът да бъде открит.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Хареке Ордусу и свалянето на Абдюлхамид II: възцаряването на Мехмед V Решад", "6a65a704"], "d": ["Хареке Ордусу, тръгнала от Солун след Събитието от 31 март, влезе в Истанбул в нощта на 22–23 април от четири посоки и на 24 април дворецът Йълдъз се предаде. Меджлис-и Умуми-и Милли на 27 април реши свалянето на Абдюлхамид II; падишахът бе изпратен в Солун и на негово място на трона бе поставен брат му Мехмед V Решад. Така тридесет и трите години лично управление приключиха, но мястото им бе заето от нов период, при който падишахът се символизираше и Иттихад ве Теракки управляваше с подкрепата на армията.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Албанското въстание: въоръжена съпротива в Косово и Шкодра", "93ed30c6"], "d": ["Централистичната данъчна политика на иттихадисткото правителство, кампанията по събиране на оръжие и спорът за латинската азбука вдигнаха албанските племена, смятани дотогава за едни от най-верните на държавата елементи. Макар армията под командването на Махмуд Шевкет паша да потуши въстанието строго, безпокойствата пламнаха отново през 1911 и 1912 Тези въстания изтощиха османската армия в навечерието на Балканската война и ускориха раждането на албанското национално движение.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Договорът от Уши: отстъпването на Триполитания и Бенгази на Италия", "4ffa1fd2"], "d": ["Високата порта, която не можеше да поеме риска от двуфронтов конфликт пред военната подготовка на балканските държави, подписа тайен мир с Италия в швейцарското градче Уши и отстъпи Триполитания и Бенгази. Османската държава така загуби последната си земя в Африка; в замяна бе обещано връщане на Родос и Додеканезите, окупирани от Италия, но това обещание никога не бе изпълнено. Когато договорът бе подписан, Балканската война бе вече започнала. С това събитие Murzuk (Fizan), Gât, Sebha, Ubârî, Tırgan (Traghan), Zevîle (Zawila) и el-Katrûn (Fizan (санджак на вилаета Триполитания)) преминаха към италианско управление.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Гръцка окупация на Лемнос", "9555af1d"], "d": ["В Първата балканска война гръцкият флот окупира Лемнос; пристанището Мудрос на острова стана база за блокадата на Дарданелите. Островът бе оставен на Гърция в Лозана (24 юли 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Гръцка окупация на Тасос", "6c03c7f0"], "d": ["В Първата балканска война Гърция окупира Тасос и Самотраки.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Гръцка окупация на Самотраки", "911e82a3"], "d": ["В Първата балканска война Гърция окупира Самотраки.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Гръцка окупация на Митилини", "6b2b07ba"], "d": ["Гръцкият флот слезе на сушата в Митилини; островът бе завладян от гръцката армия и флот в края на Първата балканска война. Лондонската конференция (май 1913) потвърди положението.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Гръцки десант на Хиос", "901c6539"], "d": ["Хиос, бомбардиран на 7 април 1912 в Първата балканска война, бе подложен на гръцки десант; османският гарнизон се предаде на 3 януари 1913 Островът бе оставен на Гърция с Лозанския договор (24 юли 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Убийството на великия везир Махмуд Шевкет паша в Истанбул", "68e60e63"], "d": ["Махмуд Шевкет паша, назначен за велик везир след нападението над Високата порта (Баб-ъ Али), бе убит с огън, открит по каретата му близо до Çarşıkapı, докато отиваше в Министерството на войната. Иттихад ве Теракки, стоварвайки убийството върху опозицията, започна голяма вълна от арести и екзекуции и Партията на свободата и съгласието (Хюрриет ве Итилаф) бе фактически прочистена. С това събитие диктатурата на еднопартийната система на иттихадистите, основана на тройката Енвер–Талат–Джемал, бе окончателно установена.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Началото на Втората балканска война: борбата за разпределение между съюзниците", "48d088a2"], "d": ["Балканските съюзници, които не можаха да разделят земите, взети от османците с Лондонския договор, се нахвърлиха един върху друг; с нападението на България срещу сръбските и гръцките позиции започна втората война. Когато Румъния и Черна гора също встъпиха във фронта срещу България, българската армия се срути. Османската държава, възползвайки се от тази възможност, премина линията Мидия–Енез, очертана от Лондонския договор, и върна Източна Тракия заедно с Одрин.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Истанбулски договор: мир с България и узаконяване на Одрин", "c8c18b2d"], "d": ["Договорът, подписан след Втората балканска война между Османската държава и България, като прие река Марица за граница, юридически узакони оставането на Одрин, Къркларели, Димотика и Източна Тракия на османците. Дедеагач бе оставен на България (Кавала пък бе преминала към Гърция през юли 1913 след българската окупация от есента на 1912 и бе узаконена за Гърция с Букурещкия договор от 10 август 1913); бяха уредени взаимната размяна на население между двете страни и правата на мюсюлманите в България. Гаранцията на единственото парче земя, което можа да бъде върнато от балканската катастрофа, е този текст. Други места, присъединени на същата дата: Гюмюрджина.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Връщането на Тенедос и Имброс — Атинският договор", "ec084d09"], "d": ["От Северноегейските острови, окупирани от Гърция във Балканската война, Тенедос и Имброс, които държат входа на Проливите, при преговорите за Атинския договор бяха сметнати за незаменими за отбраната на Чанаккале и бяха върнати на Османската империя. Останалите острови останаха в Гърция. Тези два острова останаха последните земи, които империята държеше в Егея, и бяха оставени на Турция и в Лозана.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Атинският договор: мир с Гърция и предаването на Солун и Янина", "8e94def7"], "d": ["Договорът, подписан между Османската държава и Гърция, официално призна преминаването на Солун, Янина и Южна Македония, загубени в Балканската война, към Гърция и бе направен отказ от османските права върху Крит. Бяха уредени подробно религиозните и имуществените права на мюсюлманите, оставащи в Гърция, статутът на вакъфите и назначаването на муфтиите. Статутът на Егейските острови остана неразрешен и остана като източник на постоянно напрежение между двете държави.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Подписването на османско-германския таен съюзен договор в Истанбул", "0472efb3"], "d": ["Веднага след избухването на войната в Европа в конака на великия везир Саид Халим паша бе подписан таен съюзен договор между Османската държава и Германия; текстът предвиждаше османците също да застанат на страната на Германия в случай, че Русия встъпи във война срещу Германия. Договорът бе скрит дори от кабинета и бе известен само на четирима души. Три месеца по-късно с нападението в Черно море Османската държава щеше да бъде фактически повлечена във войната и съдбата на империята щеше да бъде вързана с този документ.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Едностранната отмяна на капитулациите", "ec773d18"], "d": ["Османското правителство, в момент, когато Европа бе заета с войната, обяви, че от 1 октомври 1914 едностранно отменя капитулациите, даващи на чужденците съдебни, финансови и митнически привилегии. Приключването на този четиривековен ред на привилегиите бе посрещнато в страната с голям възторг на независимост и в Истанбул бяха направени празненства. Всички държави, включително съюзна Германия, протестираха срещу решението; капитулациите щяха да станат окончателно история едва през 1923 в Лозана.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Нападението в Черно море: бомбардирането на руски пристанища от османския флот", "8ad4ef61"], "d": ["Goeben и Breslau (Явуз и Мидилли), избягали от Германия и присъединили се към османския флот като «закупени», излязоха в Черно море под командването на адмирал Сушон, обстреляха руски пристанища и потопиха кораби. Тази заповед, дадена тайно от кабинета от Енвер паша, фактически сложи край на неутралитета. В рамките на седмица Русия, Англия и Франция обявиха война и Османската държава встъпи безвъзвратно в Първата световна война.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Овладяването на Фао от английско-индийските сили — откриването на Иракския фронт", "08663813"], "d": ["На сутринта след деня, в който държавите на Антантата обявиха война на Османската държава, английско-индийска бригада, чакаща в Бахрейн, слезе във Фао в устието на Шат ал-Араб. Малката османска част в разрушената крепост Фао се оттегли под огъня на бойните кораби и станцията на индийската телеграфна линия попадна в ръцете на англичаните. Така Иракският фронт бе открит.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Обявяването на Джихад-и Екбер: четене на фетвата за джихад в джамията Фатих", "2a6174e8"], "d": ["Петте фетви, дадени от шейхюлисляма Юргюплю Хайри ефенди, бяха прочетени от името на халиф-падишаха в джамията Фатих и всички мюсюлмани бяха призовани на джихад срещу държавите на Антантата. Този ход, към който Германия имаше големи надежди, целеше да вдигне мюсюлманите в английските и френските колонии. Очакваното общо въстание не се състоя; напротив, въстанието на мекканския емир шериф Хюсеин две години по-късно, с английска подкрепа, показа горчиво границите на политическото влияние на халифата.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Предаването на Kürne на англичаните", "621d36b0"], "d": ["Силите на басренския управител Субхи бей, оттеглили се след падането на Басра в Kürne, където се срещат Тигър и Ефрат, се предадоха сутринта на 9 декември 1914 след сблъсъците на 4–8 декември.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Операцията Саръкамъш: катастрофа на Кавказкия фронт", "5cbde7f0"], "d": ["Енвер паша, за да върне Карс–Ардахан–Батум, загубени през 1878, и да вдигне турците в Кавказ, насочи през зимата Трета армия в маневра за обкръжаване на руските сили през планините Аллахуекбер. Поради недостатъчното зимно снаряжение, изчерпващото се снабдяване и виелиците, достигащи до минус тридесет градуса, армията се стопи още преди да влезе в битка; десетки хиляди войници загинаха от замръзване. Операцията стана една от най-тежките катастрофи на османците във войната и остави източния фронт беззащитен за две години.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Първата операция за канала: атака срещу Суец през пустинята Синай", "02dd72f5"], "d": ["Командирът на Четвърта армия Джемал паша организира атака през пустинята Синай с цел да освободи Египет от английската окупация и да затвори Суецкия канал за корабоплаване. Макар османските части да стигнаха източния бряг на канала и част от тях да успее да премине на отсрещния, те се оттеглиха заради английското превъзходство и неосъществилото се очаквано въстание на египетското население. Операцията не достигна целта си, но предизвика косвен стратегически ефект, принуждавайки Англия да държи в Египет голяма сила.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Приемането на Закона за преселване и настаняване (Техджир)", "2f2bc22c"], "d": ["След въстанието във Ван и руското напредване правителството прие временния закон, позволяващ на командирите на армиите да прехвърлят в други райони населението, за което се смяташе, че нарушава сигурността зад фронта, и падишахът го утвърди на 27 май 1915 В резултат на прилагането му по-голямата част от арменското население в източните и южните вилаети на Анатолия бе изпратена към Сирия и Мосул; по време на преселването имаше много голяма загуба на живот поради болести, глад и нападения. Решението остана най-тежкият и днес също най-спорният въпрос на последните години на османците.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Османски части си върнаха Муш от руската окупация", "fb1be113"], "d": ["Шест месеца след първата руска окупация на Муш османският 16-и корпус влезе в градчето при контранастъплението Битлис-Муш.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Муш отново премина в руски ръце", "43ad8a03"], "d": ["При руското контранастъпление османският отряд опразни Муш; градчето отново попадна под руска окупация между 22 и 25 август 1916 и остана в нейни ръце до пролетта на 1917", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Муш бе окончателно освободен от руската окупация", "f0e89703"], "d": ["Муш, попаднал под руска окупация през Първата световна война, бе окончателно върнат от османските сили на 1 май 1917", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Смъртта на Абдюлхамид II в двореца Бейлербейи", "c9662582"], "d": ["Абдюлхамид II, който бе свален от трона през 1909, доведен първо в Солун и след загубата на града в Балканската война в Истанбул и държан под домашен арест в двореца Бейлербейи, почина. През тридесет и трите години на управлението си той се бе опитвал да печели време, държейки държавата далеч от войни, но бе помнен и с истибдадското си управление. Погребан бе с голямо множество в гробницата на Махмуд I на Диванйолу; смъртта му съвпадна с военна година, в която създаденият от него ред бе отдавна прочистен.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Договорът от Брест-Литовск: възвръщането на Карс, Ардахан и Батум", "da82636f"], "d": ["Договорът, подписан между Русия, която след болшевишката революция излезе от войната, и Централните сили, затвори Източния фронт и върна на Османската държава Карс, Ардахан и Батум (Елвийе-и Селясе), загубени с Берлинския договор от 1878 Това бе единственото териториално придобивка, постигнато в османската история след четирийсет години. Но след Мудросското примирие районът щеше да бъде отново загубен, а окончателното решение щеше да дойде с Карския договор от 1921", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Османски части влязоха в Артвин", "ca7d1778"], "d": ["Османските части, преминали на 25 март границата от 1914, потеглиха към Elviye-i Selâse, чиято граница отпреди 1878 Брест-Литовск бе върнал, и влязоха в Артвин на 28 март 1918 Артвин бе оставен на Русия през 1878 като част от Батумския санджак; в статията на TDV за Артвин връщането е записано само като „Март 1918“, а деня дава Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ардахан премина в ръцете на турската армия", "7fd9e3db"], "d": ["При операцията за Elviye-i Selâse османската армия след Артвин превзе Ардахан на 3 април 1918; Ардахан бе паднал през 1877 в Doksanüç Harbi и бе оставен на Русия през 1878 Карс щеше да бъде превзет един месец по-късно, на 25 април.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Връщането на Батуми", "d37a1a0d"], "d": ["Османската армия, напреднала на изток след оттеглянето на Русия от войната с Брест-Литовския договор, си върна след четиридесет години загубеното през 1878 пристанище Батуми. Това пристанище в източния край на Черно море бе морският изход на бакинския петрол. Придобивката продължи само седем месеца; след Мудроското примирие областта щеше да бъде опразнена.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Карс влезе под османска власт", "02cbf0b3"], "d": ["В Брест-Литовск бе решено връщането на трите санджака — Карс, Ардахан и Батуми, — загубени с Берлинския договор от 1878; османската армия влезе в Ардахан на 3 април, в Батуми на 14 април и в Карс на 25 април 1918 и управлението бе фактически установено. Тези земи, наричани „Elviye-i Selâse“, бяха смятани за възмездие за загубата, продължаваща от Doksanüç Harbi. След примирието те щяха да бъдат загубени отново и окончателно щяха да бъдат присъединени към Турция едва с Карския договор от 1921", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Iğdır бе завзет — напредване в долината на Араке", "87ebf4d3"], "d": ["В рамките на настъплението, започнало през февруари 1918, турските части разбиха арменските части при Serderabad, северно от Араке, и завзеха Iğdır на 20 май 1918 Iğdır не влизаше в Elviye-i Selâse, а бе уезд Sürmeli на Ереванската губерния; около 180 години по-късно в областта бе установена първата османска власт.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Смъртта на Мехмед V Решад и възцаряването на Мехмед VI Вахдеддин", "d302ba07"], "d": ["Мехмед V Решад, деветгодишното управление на когото премина с Триполитанската, Балканските и Световната война, почина в най-критичния период на войната и на негово място брат му Вахдеддин се възкачи на трона под името Мехмед VI. Новият падишах се опита да се освободи от попечителството на иттихадисткия кадър; когато четири месеца по-късно бе подписано примирие, щеше да бъде принуден да ръководи ликвидацията на империята. Той бе тридесет и шестият и последен падишах на османската династия.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Пристигането на флота на Антантата пред Истанбул и фактическата окупация на града", "d10cb14d"], "d": ["След Мудросското примирие съюзническият флот от над шейсет единици, състоящ се от английски, френски, италиански и гръцки кораби, хвърли котва пред Долмабахче и Истанбул попадна фактически под окупация. След четиристотин шейсет и пет години столицата за първи път премина под контрола на чужди войници. Думите «Както дойдоха, така ще си отидат», които според преданието Мустафа Кемал паша казал в същия ден, слизайки в Хайдарпаша и виждайки картината, щяха да станат едно от символните изречения на Националната борба.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Оттегляне в областта на Араке: Iğdır бе опразнен", "57572ab4"], "d": ["По силата на клаузата на Мудроското примирие за оттегляне зад границата от 1914 Yakup Şevki Paşa със заповед от 21 ноември нареди частите извън границата на Брест-Литовск да бъдат изтеглени до 4 декември; Iğdır и околностите му бяха напълно опразнени на тази дата. След това Aras-Türk Hükûmeti бе разрушено от арменците в края на декември 1918", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Британците се настаниха в Артвин", "e2cb3153"], "d": ["Тъй като Мудроското примирие от 30 октомври 1918 поставяше условие османската армия да се оттегли зад границата от 1914, Артвин бе опразнен и на 17 декември 1918 бе окупиран от британците. Според статията на TDV за Артвин британската окупация продължи до април 1920", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Британско управление в Батуми след Мудрос", "9dd768fc"], "d": ["По силата на Мудроското примирие от 30 октомври 1918 Османската държава бе принудена да се оттегли от Батуми; на 24 декември 1918 градът бе зает от британски части. Батуми, превърнат през април 1918 в средище на самостоятелен санджак, остана под британски контрол от тази дата до юли 1920", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ардахан премина под грузинска власт", "97cf47f6"], "d": ["Опразнения след Мудрос Ардахан бе окупиран от грузински сили на 20 април 1919, в дните, когато Cenûb-ı Garbî Kafkas Hükûmeti бе разпуснато от британците. Грузинската власт щеше да продължи до 23 февруари 1921", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston предаде управлението на Карс на арменския управител", "efa81cb0"], "d": ["Британският командир Preston, който на 12-13 април 1919 разпусна Cenûb-ı Garbî Kafkas Hükûmeti, на 30 април 1919 премахна временното правителство на шурата и предаде управлението на града на арменеца Karganof, назначен за управител на Карс; в Карс започна периодът на арменско управление, който продължи до победата на Kâzım Karabekir на 30 октомври 1920", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Ерзурумският конгрес: решението на източните вилаети за национална съпротива", "41ef0457"], "d": ["Конгресът, свикан от Дружеството за защита на правата на Източна Анатолия, след като бе отложен поради английски натиск, бе открит с петдесет и шест делегати и за негов председател бе избран подалият оставка от армията Мустафа Кемал паша. Конгресът обяви, че в рамките на националните граници родината е едно цяло, че мандатът и покровителството не могат да бъдат приети и че в случай на разпадане на правителството народът ще вземе съдбата си в собствените си ръце. Тези решения щяха да образуват ядрото на текста на Мисак-ъ Миллий шест месеца по-късно.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Сивашкият конгрес: обединяването на националната съпротива под един покрив", "0e9ad36b"], "d": ["Конгресът, започнал работа на 4 септември 1919 в Сивашката султания, обедини дружествата за защита на правата от всички краища на страната под името Дружество за защита на правата на Анадола и Румелия и избра Представителен комитет (Хейет-и Темсилийе). Предложението за американски мандат бе отхвърлено след дълги дебати. С декларацията, публикувана на 11 септември, Националната борба се превърна в легитимно политическо движение с един център и започна открита борба за власт с Истанбулското правителство.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Амасийският протокол: преговорите на Истанбулското правителство с Представителния комитет", "40e6a6ab"], "d": ["След падането на Дамат Ферид и образуването на правителството на Али Ръза паша министърът на флота Салих паша бе изпратен в Амасия, за да преговаря с Представителния комитет. С постигнатите протоколи Истанбулското правителство фактически призна съществуването на анадолското движение; бе прието свикването на Меджлис-и Мебусан, свободното провеждане на изборите и опазването на националните граници. Това е първото официално политическо придобивка на Националната борба спрямо Истанбул.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Приемането на Мисак-ъ Миллий в последния османски парламент", "6322865e"], "d": ["Текстът на Ахд-и Миллий, подписан от 121 депутати в последния османски Меджлис-и Мебусан, поставяше като условие неделимата цялост на земите, останали в рамките на линията от Мудрос и обитавани от мюсюлманско-турско мнозинство, допитване до народа в арабските вилаети и Западна Тракия, отмяната на капитулациите и пълна политическа и финансова независимост. Текстът бе приет единодушно на 17 февруари 1920 и обявен пред света. Тази декларация бе както политическата програма на Националната борба, така и картата на границите, които щяха да бъдат защитавани в Лозана; тя стана пряката причина за официалната окупация на Истанбул от държавите на Антантата на 16 март.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["При изтеглянето на британците Артвин остана в Грузия", "6d086b06"], "d": ["Според статията на TDV за Артвин британската окупация продължи до април 1920; при изтеглянето си британците оставиха града на Грузия. Артвин остана в ръцете на Грузия до ултиматума на TBMM от 23 февруари 1921", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Батуми бе предаден на грузинска администрация", "6523d095"], "d": ["Официалното предаване на Батуми от британците на грузинците се състоя на 7 юли 1920 (статията на TDV за Батуми дава само „юли 1920“). Правителството в Анкара на 25 юли протестира срещу предаването като „окупация“.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Договорът от Гюмрю: първият международен договор на правителството на ВНСТ", "9232c690"], "d": ["След като Източният фронт под командването на Кязъм Карабекир върна Саръкамъш и Карс, Армения поиска мир и с договора, подписан в Гюмрю, призна, че не признава Севър и се отказва от териториалните си претенции на изток. Този първи договор, подписан от Анкарското правителство, стана първият международен документ, фактически отхвърлил Севър, и отвори пътя на правното признаване към ВНСТ. Така източната граница бе осигурена и стана възможно силите да бъдат пренасочени към Западния фронт.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Първата битка при Иньоню: първата победа на редовната армия", "4add3719"], "d": ["Новосъздадената редовна армия спря при позициите на Иньоню гръцките сили, напредващи от посока Бурса, и ги принуди да се оттеглят. Макар този успех да бе ограничен в военно отношение, политическите му последици бяха много големи: Анкарското правителство бе поканено на Лондонската конференция, пътят към Московския договор със Съветска Русия бе отворен и бе приет Законът за основните устройства (Тешкилат-ъ Есасийе). Доверието на вътрешното обществено мнение в редовната армия също се затвърди с тази победа.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Втората битка при Иньоню: второто пречупване на гръцката атака", "a974521c"], "d": ["Гръцката армия, която не получи резултат от Лондонската конференция, премина в нова атака от посока Бурса и Ушак, но отново бе спряна по хребетите на Иньоню и бе принудена да се оттегли. Телеграмата на Мустафа Кемал паша до Исмет паша «Вие там победихте не само врага, но и лошата съдба на нацията» бе написана след тази победа. Битката издигна международния престиж на Националната борба и ускори процеса на оттегляне на Италия от Анадола.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Анкарското споразумение: мир с Франция и затваряне на южния фронт", "35fc32db"], "d": ["След победата при Сакаря със споразумението, подписано с Франция в Анкара, войната на южния фронт приключи; френските сили опразниха Чукурова и Югоизтока, включително Адана, Антеп, Мараш и Урфа, и се оттеглиха към сирийската граница. Така една от държавите на Антантата фактически призна Анкарското правителство и в Севърския фронт се появи първата пукнатина. Оръжията, поети от опразнените райони, и освободените части изиграха ключова роля в подготовката на Голямата атака.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Мудания примирие: предаването без война на Истанбул и проливите", "ac0d9baf"], "d": ["След Голямата атака, когато турската армия се изправи пред английските сили при Чанаккале и Измит, конференцията, свикана в Мудания, завърши с примирие след единайсетдневни тежки пазарлъци. Бе прието Източна Тракия да бъде опразнена от Гърция в рамките на петнайсет дни до Марица и предадена на турско управление, а Истанбул и проливите да бъдат предадени с мирен договор. Така въоръжената фаза на Националната борба приключи с дипломатическа победа, спечелена, без да бъде изстрелян нито един куршум, и вратата на Лозана се отвори.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Напускането на Истанбул от Мехмед VI Вахдеддин и избирането на Абдюлмеджид ефенди за халиф", "8ab0e847"], "d": ["Последният падишах Мехмед VI Вахдеддин, чието положение стана спорно след отмяната на султаната, напусна Истанбул в петък сутринта на 17 ноември 1922 с английския бронепалубен кораб Malaya и отиде в Малта. ВНСТ два дни по-късно, на 19 ноември, избра Абдюлмеджид ефенди за халиф без политическа власт. Така шестстотин двайсет и трите години династично управление на османците фактически приключиха; халифатът щеше да продължи още петнайсет месеца символично. Преминал в Малта и след това в Италия, Вахдеддин се настани във Вила Нобел в Сан Ремо; след молбите му да бъде приет в мюсюлманска страна, които не дадоха резултат, той умря там на 16 май 1926, повтаряйки, че никога не се е отказвал от правата си на султанат и халифат.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Смъртта на последния падишах Мехмед VI Vahdeddin в Сан Ремо", "7149ed0e"], "d": ["Последният османски падишах Mehmed Vahdeddin, настанил се в италианския град Сан Ремо след напускането на Истанбул, умря на 16 май 1926, без да научи, че се е събрал халифският конгрес (13 май 1926), в който бе заявено, че никога не се е отказвал от правата си на султанат и халифат. Бе в тежко финансово затруднение; дължеше 60 000 лири на търговците от Сан Ремо; чули за смъртта му, кредиторите наложиха запор върху вещите на дома му.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Превземането на областта на Болу от Konuralp — Mudurnu, Konurapa и Bolu", "e245cd27"], "d": ["Konuralp, един от военачалниците на Орхан Гази, се насочи към планинската област източно от Сакария и присъедини областта на Mudurnu, Konurapa и Bolu към османската власт; градчето на равнината Дюздже бе наречено на негово име. Точната дата на завоеванието не е известна; разказът се основава на предание на Âşıkpaşazâde. Областта бе по онова време гранична зона, сменяща ръцете си между Candaroğulları и Византия; завоеванието за пръв път приближи Османската империя до западния бряг на Черно море. След битката при Анкара областта щеше отново да премине към Candaroğulları, но по времето на Завоевателя щеше да бъде окончателно върната.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Превземането на византийските градчета южно от Мраморно море — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["След като Никея и Измит бяха превзети, градчетата, останали във византийски ръце на запад от Бурсанската равнина, влязоха едно по едно под османска власт. Gölyazı около езерото Улуабат, Kirmasti по поречието на Сусурлук и Mihaliç завършиха коридора, свързващ южния бряг на Мраморно море със земите на Karesi. Тези градчета се предадоха дълго време без обсада, чрез прекъсване на околностите им; византийското присъствие в областта така бе притиснато към Гемлишкия залив.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Gördüs (Коринт) премина към Морейското деспотство", "392495eb"], "d": ["Коринт, който от 1358 бе тимар на флорентинския род Acciajuoli, подчинен на Ахейското княжество, премина през 1395 в ръцете на византийския морейски деспот Теодор. След това градът остана под управлението на деспотството до османското завоевание.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Присъединяването на Hacıemîroğulları Beyliği — Ordu и Ünye", "c064f07f"], "d": ["Туркменското бейство, основано от Bayram Bey около Ordu и разширено от сина му Hacı Emîr през 1350-те години, бе малка, но стратегическа крайбрежна държава със средище в днешния Eskipazar: единствената независима област между Самсун и Трабзон. Emîr Süleyman бе заявил през 1398 покорство при похода на Баязид Светкавицата в Canik и след битката при Анкара бейството отново бе станало свободно. При Мурад II, през същите години с ликвидирането на Tâceddinoğulları, земите на бейството бяха свързани пряко с османската власт и черноморският бряг от Самсун до Giresun се обедини в една ръка.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Превземането на Gördüs (Коринт)", "87a2bc59"], "d": ["При похода на Завоевателя в Морея крепостта Акрокоринт бе обсаждана три месеца и накрая бе приета с мирно предаване. Коринтският провлак, смятан за вратата на Морея, така премина към Османската империя.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Присъединяването на Черна гора към османската власт — Цетине", "7fdb7cc8"], "d": ["Когато династията Черноевичи, управляваща Зета, се отказа от властта си през 1496, планинската област Черна гора, която бе задният двор на Шкодра, бе поставена пряко под османска власт и бе организирана първо като отделен санджак, а след това като част от Шкодренския санджак. Манастирът Цетине бе оставен на мястото си като религиозно средище на областта. Поради суровостта на географията управлението тук никога не действаше толкова строго, колкото в равнините; двеста години по-късно управлението на владиките, произлязло от същия манастир, щеше да бъде зародишът на фактическата независимост.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Приемането на османската власт от крепостта Bayezid при Irakeyn Seferi", "f29e2e17"], "d": ["Когато великият везир İbrahim Paşa дойде при Irakeyn Seferi в околностите на Бингьол, заедно с много кюрдски племена в областта крепостите Ван, Toprakkale, Avnik и Bayezid се съгласиха да влязат под османска власт. Bayezid се бе присъединила към Османската империя през 1514 при похода на Селим Грозния, но когато армията се върна, сефевидите бяха си върнали областта.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Повторното преминаване на Тебриз към сефевидите — връщането от Irakeyn", "80b8b761"], "d": ["При Irakeyn Seferi армията влезе в Тебриз, но тъй като истинската цел бе Багдад, в града не бе оставен постоянен гарнизон. Когато армията, прекарала зимата в Багдад, се връщаше на запад, шах Тахмасп отново навлезе в опразнения Азербайджан и си върна Тебриз. Това бе повтарящият се модел на османско-сефевидските войни: Тебриз бе превземан пет пъти и и в петте не можа да бъде задържан; градът щеше да получи дълготраен османски гарнизон едва през 1585", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Падането на Ван и Ерджиш в ръцете на Тахмасп (османското положение приключи през 1534-35)", "cb93d561"], "d": ["В областта, предала Ван на османска власт през 1534, Ulama Paşa устоя във Ванската крепост на сефевидската обсада; крепостта премина в ръцете на сефевидите, а сефевидските сили, обсаждащи Ерджиш, се бяха оттеглили с османска помощ. Когато Законодателят стигна Ахлат (23 септември 1535), Ван вече бе в ръцете на Тахмасп. Ван остана сефевидски до 1548", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Преминаването на санджака Bayezid под сефевидска власт (Ван и Ерджиш вече бяха сефевидски през 1535)", "806a2cf1"], "d": ["Санджакът Bayezid, разположен насред османско-сефевидската граница, отново премина в ръцете на Иран (Kaya 2017 го споменава „заедно с Ван и Ерджиш“; но според Karataş 2025 и TDV Ван и Ерджиш се бяха върнали към сефевидите на 22 септември 1535 — виж предходната записка); при тази смяна на ръцете някои места на санджака бяха разрушени. Санджакът многократно сменяше ръцете си между двете държави до последната четвърт на XVI в.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Повторното преминаване на санджака Bayezid към Османската империя по време на Nahcıvan Seferi", "cf0171fa"], "d": ["По време на третия ирански (Nahcıvan) поход на Законодателя санджакът Bayezid отново бе поставен под османска власт. При похода от 1554 Bayazıt стана важна база за армията; санджакът окончателно влезе под османски суверенитет през 1578", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Загубата на Revan от шах Абас", "34413cf2"], "d": ["Когато източният фронт остана беззащитен през годините, в които бунтовете на джелалиите блокираха Анадола, шах Абас, който бе преустроил армията си по европейски образец, премина в настъпление. Крепостта Revan, построена през 1583 от Ferhad Paşa, се предаде след седеммесечна обсада. Първото звено на кавказката линия, придобита с Договора на Ferhad Paşa, се бе откъснало и в следващите три години целият Южен Кавказ щеше да бъде загубен.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Загубата на Тифлис и Гянджа", "3fb51753"], "d": ["След падането на Revan сефевидската армия напредна по долината на Кура; средището на Карабах Гянджа и столицата на Грузия Тифлис бяха загубени една след друга. Османската държава по същото време водеше тринадесетгодишната дълга война на австрийския фронт и се бореше с джелалиите в Анадола; нямаше сили за изпращане на изток. Така широкият ред на кавказките еялети, установен с Договора на Ferhad Paşa от 1590, фактически приключи.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Загубата на Ширван — Шамахи, Баку и Дербент", "81beab11"], "d": ["Ширванският еялет по каспийския бряг, придобит с походите на Özdemiroğlu Osman Paşa от 1578-1585, бе осигурил на османските финанси значителни доходи като основен източник на копринената търговия. Походът на шах Абас на север ликвидира този еялет, като превзе последователно Шамахи, Баку и Дербент. Загубата не бе само на земя: пътят на иранската коприна, която се вливаше през Османската империя в Европа, също излезе от контрол и сефевидската държава започна да търгува с коприната през Индийския океан.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Загубата на Таиз", "65f20d53"], "d": ["Османците през 1038 (1629) г. напуснаха и Таиз заедно с властта над Йемен, оставена на управлението на Kāsımî в Сана — първата голяма стъпка в процеса, в който зейдитските имами си върнаха вътрешния Йемен.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Загубата на Йемен — властта на имамите Kāsımî", "49e83e3c"], "d": ["Йемен бе османски еялет от 1538; но съпротивата на зейдитските имами никога не секна. Въстанието, започнато от имам Kāsım, се разпростря върху цялата страна по времето на сина му el-Müeyyed Muhammed и османските гарнизони бяха обсаждани един след друг. Докато Мурад IV бе насочил вниманието си към Багдад и Revan, не можаха да бъдат изпратени подкрепления; Таиз бе загубен през 1629, а Моха бе опразнена в последната фаза на същия срив на 22 октомври 1635 През 1635 последните части в Сана и Забид също напуснаха Йемен. Така източният бряг на Червено море остана двеста тридесет и седем години извън империята и можа да бъде върнат едва през 1872 Лахидж (ел-Хавта), според TDV İslâm Ansiklopedisi, бе в ръцете на османците до 1635; от тази дата нататък зейдитските имами бяха влиятелни.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Опразването на Моха", "c6b3061a"], "d": ["Mustafa Bey опразни Моха с останалите сили и оръжия на 10 Джумадилевел 1045 (22 октомври 1635); след това Hasan b. Kāsım, синът на имам Kāsım, назначи свои хора в Забид и Моха и установи контрол на Kāsımî и в крайбрежието Tihâme.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Загубата на Лахса в полза на емирството на Benî Hâlid", "a9b6131a"], "d": ["Лахса бе еялет, учреден през 1550, за да се затвори западният бряг на Персийския залив за Португалия; но бе много далеч от Истанбул, в края на един-единствен пустинен път. В годините, когато обсадата на Крит изчерпваше ресурсите, племето Benî Hâlid в областта под водачеството на Berrâk b. Gureyr изведе османския гарнизон и основа свое емирство. Западният бряг на Залива остана в племенни емирства сто и петдесет години; през 1795 щеше да премине към саудитите, а през 1871 отново към Османската империя.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Загубата на Превеза и Воница в полза на Венеция — отварянето на епирския бряг", "1201204c"], "d": ["Венеция, присъединила се към Свещената лига, преди да започне похода в Морея, взе двете крепости, които държат входа на Амбракийския залив: Превеза и Воница на отсрещния бряг. Същото лято падна и Айя Мавра (Лефкада). Тези три пункта осигуриха безопасното навлизане на флотата от Йонийско море във вътрешността на Гърция и станаха база на операцията в Морея, която щеше да започне на следващата година. Превеза и Воница бяха оставени на Венеция и при Пожаревац; към османска власт щяха да се върнат едва през 1798", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Загубата на Солнок — разпадането на линията на Тиса", "51c2c8ef"], "d": ["След падането на Нове Замки през август Хабсбургската армия се насочи на юг и превзе Солнок, мостовото предмостие над река Тиса. Градът бе единственият безопасен проход между Буда и Трансилвания; загубата му означаваше откъсването на османските крепости в източната половина на Унгария една от друга. Решаващо за обсадата на Буда на следващата година бе прекъсването на пътя за снабдяване.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Загубата на Модон в полза на Венеция", "114c9cc0"], "d": ["Модон в югозападния край на полуостров Морея бе пристанището, което Венеция бе загубила три века по-рано и наричаше „едно от двете очи на държавата“. Крепостта, обсадена след падането на Корон, бе превзета, като бе бомбардирана едновременно от суша и от море. Походът на Морозини в Морея така завладя целия западен бряг на полуострова и пътят към вътрешността бе отворен.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Загубата на Печ", "99d54cf4"], "d": ["След падането на Буда през септември Хабсбургските сили слязоха на юг на запад от Дунав и превзеха Печ, османски от времето на Законодателя. Градът, известен с джамията на Gazi Kâsım Paşa, бе един от най-развитите санджакски центрове на Будинския еялет. Загубата му означаваше отварянето на пътя към Мохачката равнина; на следващата година второто поражение при Мохач щеше да се случи именно тук.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Загубата на Сегедин", "9fbee1b2"], "d": ["Сегедин, при сливането на реките Тиса и Муреш, бе южната порта на Унгарската равнина и държеше пътя към Темешварския еялет. След падането на Буда и Печ същата есен обсадената крепост скоро се предаде. Загубата на трите крепости в рамките на един сезон бе знак, че установеното от 1541 османско административно устройство в Унгария започва да се срутва. Атласът смята, че същия ден от Османската империя към хабсбургската страна е преминал и Зента по Тиса (специфичният за Зента ден на предаване в източника не бе прочетен, денят е взет от Сегедин; TDV zenta: от октомври 1686 започнаха сражения между Османската империя и съюзниците, водени от Хабсбургите — beyanlı yaklaşıklık).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Загубата на Патра — северната порта на Морея", "b9cff63c"], "d": ["Патра, при входа на Коринтския залив, бе пристанището, което контролираше прехода между Морея и Румелия. След като венецианската армия превзе града, крепостите от двете страни на залива също паднаха една след друга и полуостровът бе напълно изолиран от сушата. В края на тази операция цяла Морея премина към Венеция; областта щеше да се управлява до 1715 под името „Regno di Morea“.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Оставянето на Gördüs (Коринт) на Венеция", "9a25b6b9"], "d": ["След падането на Патра Коринт бе оставен мирно на венецианците и мюсюлманското население напусна града. През август 1687 армията на Морозини се събираше в Коринт за похода към Атина.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Загубата на Егър", "983391aa"], "d": ["Егър бе превзет през 1596 при похода, в който лично участва Мехмед III, и бе станал средище на еялет със собствено име. Тази последна голяма османска крепост в Северна Унгария, след второто поражение при Мохач, устоя една година напълно обсадена и се предаде поради глад. С нейната загуба северното крило на Османската държава в Унгария бе напълно ликвидирано.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Загубата на İstolni Belgrad — коронационният град на унгарските крале", "c6147255"], "d": ["Градът, в който унгарските крале се короноваха и бяха погребвани в продължение на векове, бе превзет през 1543 от Законодателя и бе станал един от най-важните санджакски центрове на Будинския еялет. Около две години след падането на Буда крепостта, напълно откъсната от околностите си, се предаде. С тази загуба османското присъствие на запад от Дунав бе притиснато към околностите на Срем и Осиек.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Загубата на Сигетвар", "834910a7"], "d": ["Сигетвар бе крепостта, в която султан Сюлейман Законодателят умря през 1566 по време на обсадата при тринадесетия и последен си поход; затова имаше символично място в османската памет. След сто двадесет и три години, след като всички околни крепости паднаха, се предаде и крепостта, защитена от блата. Тюрбето, в което са погребани вътрешностите на Законодателя, и градчето около него бяха разрушени, след като преминаха под хабсбургско управление. Другото селище, преминало същия ден в атласа от Османската империя към Хабсбургите: Барч — следва abi-merkez веригата на Сигетвар (Bánlaky 0017/1449; beyanlı yaklaşıklık).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Загубата на Варад", "6cce360d"], "d": ["Варад бе ключовата крепост, отваряща към Трансилвания, превзета през 1660 от Köprülü Mehmed Paşa и превърната в средище на еялет със собствено име. Крепостта, останала напълно сама след поражението при Сланкамен, се предаде от глад след близо двегодишна блокада. С нейната загуба османското влияние над Трансилвания фактически приключи и хабсбургското господство се установи на изток от Тиса.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Загубата на Yanova — затварянето на пътя към Трансилвания", "4b5e30d8"], "d": ["Yanova бе крепост, превзета през 1658, която държеше връзката между Варад и Тимишоара. След падането на Варад, щом околностите ѝ бяха прекъснати, и тя бе загубена. Така Темешварският еялет бе напълно изолиран от север и до Карловци продължи да съществува като единствената унгарска земя, останала в османски ръце.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Установяването на управлението на владиките в Черна гора — фактическото откъсване на Цетине", "a924b778"], "d": ["В годините, когато Войната на Свещената лига отслаби османския контрол на Балканите, митрополията начело на манастира Цетине се превърна в длъжност, предавана от баща на син в рода Петрович, и областта придоби фактически отделно управление. Благодарение на недостъпността на планините това владичество продължи две столетия в положение нито напълно независимо, нито напълно подчинено; правно независимостта му щеше да бъде призната едва с Берлинския договор от 1878", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Връщането на Gördüs (Коринт)", "26f53e3a"], "d": ["Първото голямо спиране на похода на Damad Ali Paşa в Морея бе Коринт; османците си върнаха града от венецианците през юни 1715 и оттук напредваха към останалата част на полуострова.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Настъплението на Надир: загубата на Тебриз, Нахичеван, Хамадан, Керманшах, Merâga и Kasr-ı Şîrîn", "d95efd59"], "d": ["Градовете на Западен Иран, взети между 1723 и 1727 в резултат на срива на държавата на сефевидите, бяха един по един загубени при настъплението на Надир хан, завзел фактическата власт в Иран. В Азербайджан в ръцете на Надир попаднаха и Ардабил и Halhal. Загубата на Хамадан, Керманшах и Kasr-ı Şîrîn намери тежък отзвук в Истанбул; това, че армията не потегли на поход и чака в Üsküdar, и опитът загубата да бъде прикрита, станаха една от непосредствените причини за бунта на Patrona Halil, избухнал шест седмици по-късно. Атласът смята, че и Kotur, следващ веригата на Хой, е преминал в този ден от Османската империя към сефевидите (Uluerler 2015, Turkish Studies 10/5, s. 6; специфичен за Kotur ден в източника няма — beyanlı yaklaşıklık).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Разгромът при Baghavard (Arpaçay) — загубата на Кавказ в полза на Надир хан", "4262f54c"], "d": ["Кавказките еялети, придобити през 1723-1725 в резултат на срива на държавата на сефевидите, можаха да бъдат задържани десет години. Надир хан, завзел фактическата власт в Иран, нанесе тежко поражение на османската армия при Baghavard, близо до Revan; сердарът Abdullah Köprülü Paşa загина на бойното поле. След разгрома Revan, Тифлис, Гянджа и Ширван бяха опразнени в рамките на месеци. Източната граница се върна на линията Kasr-ı Şîrîn от 1639, която щеше да бъде потвърдена през 1746", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Загубата на Бендери в полза на руснаците", "0daca453"], "d": ["След разгрома при Кагул османската армия се бе оттеглила на юг от Дунав и крепостите между Молдова и Очаков бяха останали сами. Бендери, който държеше прохода на Днестър, бе взет с щурм след двумесечна обсада; градът бе опожарен и ограбен. Загубата на крепостта откъсна средното звено на отбранителната линия на Северното Черноморие, след което паднаха и Аккерман и Килия. При Кючюк-Кайнарджа Бендери щеше да бъде върнат, но щеше да бъде загубен отново през 1806", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Влизането на емирството на Sabah в Кувейт под османско покровителство", "3584dba0"], "d": ["Според статията на TDV за Кувейт пристанището е основано в началото на XVIII в. от племето Utûb, дошло от Неджд, а родът Sabah бе поел управлението към края на века. В същите години, когато Лахса премина в ръцете на саудитите, емирството, което пред вахабитския натиск нямаше друг избор освен да се опре на Басра, влезе под османско покровителство. Връзката щеше да бъде оформена през 1871 с устройството на Басра на Midhat Paşa и Кувейт щеше да се смята за една от трите каази на Басренския санджак; по-късните териториални претенции на Ирак също се основават на този запис.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Загубата на Мека в полза на вахабитите", "2da23acd"], "d": ["Движението на вахабитите, възникнало в Неджд, се насочи към Хиджаз по времето на Suûd b. Abdülazîz; след Таиф и Медина и Мека бе приета за втори път — емирът на Мека шериф Gālib предаде града на вахабитите при условие, че остане емир. Тюрбетата бяха разрушени и пътят на хаджийските кервани от Дамаск и Кайро бе прекъснат; и surre, изпращана всяка година от падишаха в Харамейн, бе прекъсната в тези години — единственото изключение от тази непрекъсната до 1915 помощ е периодът на вахабитско господство. Тъй като титлата покровител на Харамейн бе една от основните опори на легитимността на падишаха, тази загуба бе тежък политически удар отвъд загубата на земя; връщането ѝ щеше да отнеме седем години и да стане възможно с армията на Kavalalı Mehmed Ali Paşa.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Краят на Дубровнишката република — френската окупация", "f8e27bf1"], "d": ["Французите, установили се по далматинския бряг с договора от Кампоформио (1797), завзеха Дубровник на 27 май 1806 и сложиха край на малката търговска република. Така приключи тристагодишният подчинен статут на Дубровник, който от 1458 плащаше данък на Османската империя и запазваше автономията и търговските си привилегии; градът и островът Млет (Mljet) на републиката преминават на картата пряко под френска власт.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Загубата на Сухуми в полза на руснаците — отварянето на източния черноморски бряг", "adc96bd4"], "d": ["В османско-руската война от 1806-1812 руският флот се насочи към източния черноморски бряг и превзе Сухум-Кале, на който се опираше османското господство в Абхазия. Крепостта бе средище на връзката с кавказките племена и на крайбрежната търговия. С нейната загуба Русия за пръв път се установи трайно по източния бряг на Черно море; османското влияние в Кавказ бе притиснато към околностите на Анапа и Поти.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Оставянето на Парга под османска власт", "66e0cc5d"], "d": ["Парга бе във венециански ръце от 1401 и никога не бе влизала под османска власт; след унищожаването на Венеция премина последователно към Франция и Англия. Статията на TDV за Tepedelenli Ali Paşa резюмира положението така: градът се предаде на англичаните и бе оставен под управлението на Ali Paşa едва през 1819 Предаването завърши с преселването на по-голямата част от населението към Йонийските острови. Така и последният от тройката Превеза-Парга-Воница, оставена на Венеция при Пожаревац, бе присъединен към империята; Парга щеше да остане османска деветдесет и четири години.", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["Преминаването на Аргос в ръцете на гръцките въстаници", "be66a696"], "d": ["През първите месеци на въстанието в Морея Аргос и околностите му излязоха от османска власт и преминаха в ръцете на гръцките въстаници; градът щеше да бъде сцена на османска контраоперация през май 1821", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["Ahmed Kihaya превзе Аргос, градът бе ограбен и опожарен", "d6d3ac7b"], "d": ["Силите на Ahmed Kihaya разбиха гърците в Аргос, ограбиха и опожариха града; градът за кратко се върна под османски контрол.", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["Ahmed Kihaya се обедини в Аргос с мюсюлманите от Триполица и потегли към Триполица", "9d679fd5"], "d": ["Ahmed Kihaya се обедини в Аргос с мюсюлманите от Триполица и потегли към Триполица; Аргос отново премина под контрола на гръцките въстаници.", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Преминаването на Gördüs (Коринт) в ръцете на гръцките въстаници", "892dcdc6"], "d": ["По време на гръцката война за независимост Акрокоринт премина в ръцете на въстаниците и комендантът на крепостта Kâmil Bey бе взет в плен.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["Dramalı Mahmud Paşa установи щаба си в Аргос", "c79abbfb"], "d": ["Армията на Dramalı Mahmud Paşa навлезе в равнината на Аргос и пашата установи щаба си в градчето Аргос; градът отново премина под османски контрол.", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["Dramalı Mahmud Paşa започна да се оттегля от Аргос", "5e5afb74"], "d": ["Dramalı Mahmud Paşa, принуден да се оттегли, преди да са изминали две седмици от окупацията на Аргос, започна да насочва първата дивизия на армията си към Коринт; Аргос отново премина в ръцете на гръцките въстаници.", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Загубата на Нафплио (Nauplion) в полза на въстаниците", "1a67fa50"], "d": ["Нафплио, пристанището с най-силните укрепления в Морея, се предаде от глад след блокада, продължила повече от година. Крепостта бе от началото на въстанието последната голяма опора на османския контрол в полуострова; със загубата ѝ цяла Морея премина в ръцете на въстаниците. Градът скоро щеше да стане първата столица на новата гръцка държава.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["Преминаването на Лепанто под гръцка власт", "c9d19d4b"], "d": ["Лепанто на северния бряг на Коринтския залив, който остана в османски ръце до гръцкото въстание, бе загубен през април 1829 и премина под гръцка власт; името на градчето бе променено на античното Навпактос. Мюсюлманското и еврейското население на града напълно изчезна и той се превърна в малко градче.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Френската окупация на Алжир — краят на тристагодишния оджак", "0be8f568"], "d": ["Под предлог за случая с ветрилото, произтекъл от спор за дълг, Франция държа алжирския бряг три години под блокада, след което стовари войници в Сиди Ферух. В края на операцията, продължила три седмици, Hüseyin Dayı се предаде и османският Алжирски оджак, продължавал от 1516, приключи. Окупацията не остана ограничена до столицата; Тлемсен, Шершел и Медеа във вътрешността също бяха загубени същото лято. Преминаването на целия бряг под френски контрол щеше да отнеме още двадесет и четири години.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Предаването на Eğriboz на Гърция — заедно с острова (Каристос, Орей)", "7b524aa4"], "d": ["Eğriboz, който бе сцена на ожесточени сражения по време на гръцката война за независимост, но остана в османски ръце, бе предаден на гърците през 1831, след като мирният договор влезе в сила. Мюсюлманското население на града, важна военноморска база от 1470, продаде цялото си имущество на много ниски цени и се пресели масово в османските земи; градът дълго време остана празен и германският пътешественик Фалмерайер през 1842 го определи като град-призрак.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Френската окупация на Оран (Vehrân)", "a8415d66"], "d": ["Vehrân, предаден от Испания без война през 1792, бе най-голямото пристанище в западната част на Алжир. Шест месеца след падането на столицата френски части влязоха в града. Започналата оттук западна операция скоро щеше да срещне петнадесетгодишната съпротива на Emîr Abdülkādir.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Окупацията на Анаба (Bône)", "21f37fb1"], "d": ["Анаба, пристанището на Източен Алжир близо до тунизийската граница, бе взето от френските сили и превърнато в база за похода срещу Константина. Градът бе същевременно най-близкото африканско пристанище срещу остров Сардиния.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Предаването на Атина на новата гръцка държава (денят, в който баварските части приеха Акропола)", "deee4d37"], "d": ["Атина, османска от 1456, бе сменяла ръцете си няколко пъти по време на гръцката война за независимост; гарнизонът на Акропола бе преминал през 1827 отново под османски контрол. Тъй като остана на север от границата, прокарана с Лондонския протокол, градът бе предаден на новото кралство и гарнизонът опразни Акропола. Денят в атласа е денят, в който баварските части приеха Акропола; действителното излизане на османския гарнизон се случи няколко дни по-късно (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, гл. 13; Finlay, Journals and Letters, т. I, с. 67). На следващата година Атина бе обявена за столица на Гърция на мястото на Нафплио.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Окупацията на Беджая (Bougie)", "a8927e00"], "d": ["Пристанището Беджая, където Кабилските планини се отварят към морето, бе последното независимо звено от крайбрежната линия между Алжир и Анаба. Бе взето с подкрепата на морската артилерия; но планинската вътрешност зад него нямаше да влезе под френски контрол още тридесет години. Тези окупации по брега представляват годишното топене на османски Алжир на картата.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Окупацията на Сетиф", "2073731a"], "d": ["След падането на Константина преди година френските сили излязоха на платото и, като превзеха стария римски град Сетиф, установиха там постоянен гарнизон. Сетиф бе мястото, където се пресичаха керванните пътища между брега и Сахара; окупацията му показа, че Франция вече започва да контролира не само пристанищата, но и вътрешната търговска мрежа.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Окупацията на Бискра — загубата на портата на Сахара", "d895cad0"], "d": ["Бискра бе вратата, отваряща се към Сахара в южното подножие на Атласките планини, и средище на палмовите оазиси. С превземането ѝ в годините, когато съпротивата на Emîr Abdülkādir започна да се пречупва, френският контрол за пръв път достигна северния бряг на пустинята. Оттук нататък щеше да има пустинна операция, напредваща от оазис на оазис.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Окупацията на Тугурт — загубата на целия Алжир", "33c056e2"], "d": ["С превземането на оазисния град Тугурт в северната част на Сахара окупацията, започнала през 1830, бе завършена в северната половина на днешен Алжир. Османската държава в тези години се биеше в Кримската война на една страна с Франция; макар никога да не се бе отказвала официално от правните си претенции върху Алжир, фактически не можа да направи нито една стъпка. Единствената останала земя в Северна Африка бе Триполитания.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Падането на Ubeyyid — преминаването на Кордофан в ръцете на силите на махди", "58299f62"], "d": ["Движението, започнато от Мухаммед Ахмед, провъзгласил се за махди, бързо се разпространи срещу египетското управление в Судан. Ubeyyid, средището на Кордофан, падна след четиримесечна обсада и стана столица на въстанието; хазната и оръжейните складове в града позволиха на движението да се превърне в армия. Судан правно все още бе земя на египетското хедивство, подчинено на Османската империя, затова загубата на картата отпада от тялото на империята.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Падането на Хартум — загубата на целия Судан", "d4b98464"], "d": ["След десетмесечна обсада силите на махди навлязоха в Хартум, при сливането на Синия и Белия Нил; управителят на града Гордън бе убит, а изпратената за помощ британска колона закъсня с два дни. От тази дата целият Судан, включително Сенар, Донгола и Кордофан, остана четиринадесет години под управлението на държавата на махди. Областта щеше да премине в британско-египетско съвместно управление едва през 1899, с напълно прекъсната османска връзка.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Италианската окупация на Масауа — загубата на западния бряг на Червено море", "c333b95b"], "d": ["Пристанището Масауа, средище на еялета Habeş, бе окупирано от Италия, възползвала се от размириците, с които бунтът на махди обхвана Судан; това формира ядрото на италианска Еритрея. Sevâkin на север и архипелагът Дахлак в открито море също бяха загубени в същия процес. Така османското господство по западния бряг на Червено море, продължавало от времето на султан Селим Грозния, приключи и морето вече бе чужда вода и от двете си страни.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Италианската окупация на Родос", "e08662c5"], "d": ["Италия, която искаше да принуди Османската държава да седне на масата в Триполитанската война, пренесе войната в Средиземноморието и стовари войници на Родос. Островът бе превзет в рамките на няколко дни. Родос, който Законодателят бе взел през 1522 след дълга обсада и който бе държан триста и деветдесет години, така престана да бъде най-голямата островна база на империята в Източното Средиземноморие; макар в Договора от Уши да се смяташе за временна окупация, той не можа да бъде върнат повече.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Италианската окупация на Додеканезите", "200aacf2"], "d": ["В седмицата след превземането на Родос италианският флот окупира и околните острови; на този архипелаг по-късно щеше да бъде дадено името „Додеканезите“. Повечето острови бяха на няколко мили от анадолския бряг и контролираха югоизточния проход на Егея. Окупацията в Договора от Уши се смяташе за временна срещу отстъпването на Триполитания, но Италия никога не опразни островите; през 1947 те щяха да бъдат предадени на Гърция.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Окупацията на Кос", "ab246c62"], "d": ["Кос, последното звено на операцията в Додеканезите, бе плодородният и гъсто населен остров точно срещу полуостров Бодрум. С окупацията всички острови в югоизточния ъгъл на Егея влязоха под италиански контрол и югозападният бряг на Анадола бе обграден по цялата си дължина от чужда верига от острови.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Обявяването на независимостта на Икария", "c4452033"], "d": ["На малкия остров Икария между Самос и Хиос населението, в обстановката на неяснота, създадена от италианските окупации, се вдигна на въстание, изведе османската жандармерия от острова и обяви петмесечна „свободна държава“ със собствено знаме, пощенска марка и събрание. През ноември 1912 островът бе присъединен към Гърция. Въпреки малкия си размер това събитие е ясен показател за това как се разпадаше централното управление в Егея.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Излизането на Самос от османска власт", "3a862f2b"], "d": ["Самос бе автономно емирство, плащащо данък на Османската империя от 1832 и управлявано от бей, назначаван от Истанбул. В празнотата, създадена от Триполитанската война, движението в полза на обединението на острова пое управлението и автономният ред на емирството фактически приключи; същата година островът обяви присъединяването си към Гърция. Този остров, на два километра от анадолския бряг, остана една от първите земи, загубени в Егея.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Падането на Янина — загубата на Епир и Парга", "d42fce18"], "d": ["Янина, обсаждана пет месеца в Балканската война, се предаде след падането на позициите при Бизани; заедно с града целият Епир премина към Гърция. Парга, подчинена на Янинския санджак, също бе загубена на тази дата и деветдесет и четири годишното османско управление приключи. Загубата на Янина означаваше затварянето на последния прозорец на империята към Адриатическо море.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Падането на Одрин в ръцете на българите", "459d2e56"], "d": ["След петмесечна и половина обсада Одрин, чиито боеприпаси и провизии бяха изчерпани, се предаде; Şükrü Paşa бе взет в плен. Падането на града, османски от 1361 и столица в продължение на деветдесет и две години, бе сметнато за най-тежкия удар на Балканската война. Одрин щеше да бъде върнат четири месеца по-късно във Втората балканска война, като се възползваха от срива на България по другите фронтове.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Загубата на Янбу в полза на силите на шериф Хюсеин", "e291c816"], "d": ["Въстанието, започнато през юни от шериф Хюсеин, се разпростря към брега на Червено море; Янбу, пристанището на Медина, с подкрепата на британския флот попадна в ръцете на въстаниците. Пристанището стана главна порта на потока от оръжие и пари, идващ отвън към въстанието. Така връзката със морето на силите на Fahreddin Paşa в Медина бе прекъсната и градът остана сам в края на Хиджазката железница.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Третата битка за Газа — загубата на Газа и Хан Юнис", "c142a069"], "d": ["След два неуспешни опита Алънби при третото си настъпление пробива фронта, като заобиколи Беершева, и линията на Газа, държана шест месеца, рухна. Газа и Хан Юнис на юг от нея бяха опразнени в същия ден. Този пробив бе началото на разпадането на палестинския фронт; Йерусалим щеше да падне пет седмици по-късно.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Окупацията на Гюмюрджина — загубата на Западна Тракия", "904d813c"], "d": ["Западна Тракия, която след Мудрос първо влезе под контрола на силите на Антантата, бе оставена на Гърция с решение на конференцията в Сан Ремо и гръцката армия влезе в Гюмюрджина. Областта, върната през 1913 от България, остана последната земя, загубена от империята в Румелия. Статутът на турското население в областта щеше да бъде уреден три години по-късно в Лозана с режим за малцинствата. С тази окупация казите Гюмюрджина, Ксанти, Дедеагач и Sofulu на Западна Тракия преминаха към Гърция.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Разпадането на държавата на Илханидите: смъртта на Ebû Said Bahadır Han", "0f187469"], "d": ["Според статията İlhanlılar в TDV İslâm Ansiklopedisi смъртта на Ebû Said без наследник води до разпадане на държавата на Илханидите, която столетие е господствала в Иран; емирите, възползвайки се от борбата за трона, основават местни династии като Джалаиридите, Кара-койунлу, Музафаридите, Serbedârîler от Хорасан и Eretnaoğulları. Това разпадане разделя региона на мозайка от бейства, която ще продължи столетие; в края на краищата той отново ще бъде обединен с походите на Тимур.", "ebf54b53"]},
"OLAYLAR_EK7:1387-01-01:0":{"b": ["Тимур поставя по-голямата част от Иран под своя власт", "1cee2b82"], "d": ["Според статията Timur в TDV İslâm Ansiklopedisi Тимур, който от началото на 1380-те ликвидира една по една следилханидските местни династии като Serbedârîler, Kertler и Музафаридите, по време на «тригодишния поход» от 1386-1388 фактически поставя под властта си по-голямата част от Иран; окончателният край на династията на Музафаридите ще му бъде сложен едва през 1393. Така след столетие на разпокъсаност регионът отново е подчинен на един-единствен централен орган.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Победата при Аракс: Kara Yûsuf побеждава тимуридския Ebû Bekir Mirza", "4b61a75a"], "d": ["След смъртта на Тимур през 1405 владетелят на Кара-койунлу Kara Yûsuf, върнал се от заточение, превзема Avnik и си възвръща земите в Източна Анатолия, след което тръгва срещу внука на Тимур Ebû Bekir Mirza, смятан за господар на Азербайджан и двата Ирака, и го побеждава на брега на Аракс. Тази победа не дава Табриз на Кара-койунлу: TDV `tebriz` пише, че през 1408 градът е в ръцете на Ebû Bekir Mirza; битката, спечелила Азербайджан, е Serdrûd на 13 април 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Победата при Serdrûd: Табриз и Азербайджан преминават към Кара-койунлу", "1f0a429d"], "d": ["Kara Yûsuf побеждава тимуридския Ebû Bekir Mirza за втори път след Аракс, при Serdrûd близо до Табриз; тази победа дава Азербайджан на Кара-койунлу. След това Kara Yûsuf възлага на Bistam Bey завладяването на Irâk-ı Acem;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Чумна епидемия в Истанбул и преместването на двореца в Одрин", "70c7a163"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Истанбул бързото и гъсто заселване на града е подготвило почвата за разпространение на епидемични болести от време на време; по време на чумната епидемия през 1466 дворът и държавните сановници временно се оттеглиха в Одрин. Населението на града понасяше сериозни загуби при подобни епидемии.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Uzun Hasan слага край на държавата на Кара-койунлу", "ef68399e"], "d": ["Според статията Uzun Hasan в TDV İslâm Ansiklopedisi владетелят на Ак-койунлу Uzun Hasan побеждава и убива владетеля на Кара-койунлу Cihan Şah в района Bingöl-Sancak на 12 Рабиулахир 872 / 10 ноември 1467; синът на Cihan Şah Hasan Ali е победен при Merend през септември 1468 и е убит пред Хамадан през април-май 1469, като така държавата на Кара-койунлу е окончателно унищожена. Земите преминават под властта на Ак-койунлу; през следващото десетилетие държавата щяла да се разшири до вътрешността на Иран.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Откриването на медресетата Sahn-ı Semân за обучение", "021f2a83"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Sahn-ı Semân тези осем медресета, учредени в рамките на комплекса на Завоевателя, бяха замислени като най-високото учебно заведение на времето и образуваха върха на османската илмийска йерархия. Мюдерисството и завършването тук през следващите векове се смяташе за най-престижното стъпало в кариерата на кадия и мюдерис.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Завършването на двореца Топкапъ (Saray-ı Cedîd)", "d2db6323"], "d": ["Според статията на TDV İslâm Ansiklopedisi за двореца Топкапъ източниците на епохата се разминават по началната и крайната дата на строежа; според датата 883 (1478) върху надписа на Bâb-ı Hümâyun строежът, започнат по заповед на Завоевателя вероятно през 1465, бе до тази година в голяма степен завършен и дворецът замени държавното средище в стария дворец. Така падишахът се премести в новото си жилище, което щеше да бъде три века административното и церемониално сърце на държавата.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Възкачването на Баязид II в Истанбул", "9b686d04"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Баязид II шехзаде Баязид, санджакбей на Амасия, при вестта за смъртта на баща си бързо дойде в Истанбул и се възкачи на трона; с подкрепата на еничарите изпревари тръгването на брат си Джем от Кония. При възкачването на трона на еничарите бе раздаден обичайният cülûs bahşişi. Тази смяна на трона запали и фитила на борбата между двамата братя.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Султан Джем се провъзгласи за султан в Бурса", "b355168a"], "d": ["Според статията на TDV İslâm Ansiklopedisi за султан Джем Джем, стигнал през Караман до Бурса, завзе града, провъзгласи се за султан и накара да се чете хутбе. Това краткотрайно султанство приключи, когато силите, изпратени от по-големия му брат Баязид II, победиха Джем при Енишехир. След поражението Джем бе принуден да избяга към Египет.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Екзекуцията на Gedik Ahmed Paşa", "6d75a58c"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Gedik Ahmed Paşa пашата, известен с похода при Отранто и с великото везирство си, бе екзекутиран в Одрин по заповед на Баязид II поради позицията си по въпроса за султан Джем и опасенията от влиянието му. Смъртта на един от най-опитните военачалници от времето на Завоевателя намери широк отзвук в двореца.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Основаването на първата печатница в Истанбул", "04475930"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Matbaa братята David и Samuel ibn Nahmias, еврейски преселници от Испания, основаха в Истанбул първата печатница, която печата с еврейски букви. Това бе записано като първият опит за печатница, действал в османските земи; печатането с турско-арабски букви щеше да стане възможно много по-късно, през XVIII в.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Превземането на Табриз от Шах Исмаил: основаването на държавата на Сефевидите", "014d81e6"], "d": ["Според статиите Safevîler и Akkoyunlular в TDV İslâm Ansiklopedisi младият шейх на текето в Ардебил Исмаил, с армия, сформирана от неговите кизилбаши мюриди в Анатолия, нанася тежко поражение на султана на Ак-койунлу Elvend в района на Нахичеван; Elvend бяга в Диарбекир, Исмаил влиза в Табриз, възцарява се и обявява дванадесетимамското шиитство за официален мазхаб. Така приключват както властта на Ак-койунлу, така и периодът на бейства след Илханидите в региона; създадена е държавата на Сефевидите, която ще просъществува три века.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Земетресението „Малкият Страшен съд“ в Истанбул", "53e3b1d6"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Истанбул по времето на силното земетресение, което връхлетя града, сред народа бе наричано „Малкият Страшен съд“; бяха нанесени тежки щети на стените, джамиите и много сгради, имаше много жертви. По заповед на Баязид II в града бе започната широкомащабна мобилизация за поправки и възстановяване.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Започването на бунта на Şahkulu", "3d9a4a90"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Şahkulu Baba Tekeli Şahkulu, подхранван от сефевидската пропаганда, събра около себе си широка туркменска маса в областта Teke и започна голям бунт с религиозно-обществен характер. Бунтът, като една от най-сериозните кризи на вътрешната сигурност на епохата, дълбоко разтърси централната власт на държавата.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Смъртта на Баязид II по пътя към Димотика", "c46e98c9"], "d": ["Бившият падишах, напуснал Истанбул след абдикацията си, за да отиде в Димотика, града на раждането си, докато напредваше в своята tahtırevan, която можеше да изминава само 5-6 км на ден, се разболя в село Abalar близо до Чорлу и умря на 25 Рабиулевел 918 (10 юни 1512). TDV İslâm Ansiklopedisi намира причината за смъртта за много съмнителна; според някои местни и чужди източници се спира на възможността да е бил отровен. След тридесет и една годишно царуване осмият падишах от рода на Осман Гази така загуби живота си.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Екзекуцията на Шехзаде Ахмед по заповед на Селим Грозния", "65abb2f2"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Селим I Шехзаде Ахмед, любимецът на баща му Баязид II и главен съперник за трона, бе разбит на равнината Енишехир в борбата, която започна след възкачването на брат му Селим, и бе заловен и убит, докато бягаше от бойното поле. С това събитие Селим до голяма степен приключи съперничеството за трона между братята и племенниците си.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["İbrahim Paşa бе назначен за велик везир", "9c94c1e3"], "d": ["Според статията на TDV İslâm Ansiklopedisi за İbrâhîm Paşa, Makbul İbrahim Paşa, издигнат от has odabaşılık до румелийски бейлербей и същия ден до велик везир, стана велик везир на 13 Şâban 929 (27 юни 1523). Това бе назначение без прецедент — от дворцова служба направо до великото везирство — и показваше изключителната близост на İbrahim Paşa до Законодателя.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbaros Hayreddin Paşa бе назначен за капудан паша", "a0ff6bab"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Barbaros Hayreddin Paşa Hayreddin Paşa, известен с успехите си в Алжир, бе повикан в Истанбул на 6 април 1534 и назначен за капудан паша и бейлербей на Cezâyir-i Bahr-i Sefîd. Това назначение се смята за началото на преустройството на османския флот и институционализирането на морската мощ в Средиземноморието.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Paşa стана велик везир за първи път", "ddfcc014"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Rüstem Paşa, след отстраняването на Hadım Süleyman Paşa във връзка със спор с един везир, Rüstem Paşa бе назначен за велик везир на 17 Рамазан 951 (2 декември 1544). Близостта му до двореца бе нараснала благодарение на брака му с Mihrimah Sultan и с тази длъжност Rüstem Paşa стана един от най-влиятелните държавници от времето на Законодателя.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi стана шейхюлислям", "11ed04f8"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Ebüssuûd Efendi, Ebüssuûd Efendi, бил осем години румелийски казаскер, бе назначен за шейхюлислям през Şâban 952 (октомври 1545) и остана на тази длъжност двадесет и осем години и единадесет месеца. Ebüssuûd Efendi, известен с фетвите си, които привеждаха канунаме на Законодателя в съгласие с шериатското право, изигра решаваща роля в оформянето на правните и образователните институции на епохата си.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Barbaros Hayreddin Paşa умря", "3378a0bf"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Barbaros Hayreddin Paşa след кратка болест той умря в Истанбул на 6 Джумадилевел 953 (5 юли 1546). Смъртта на Barbaros, погребан в тюрбето до медресето, построено от него в Бешикташ, бе възприета като закриване на една епоха в средиземноморското надмощие, установено от османския флот.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Започна строежът на джамията и комплекса Сюлеймание", "101ec36f"], "d": ["Според статията на TDV İslâm Ansiklopedisi за джамията и комплекса Сюлеймание комплексът, чийто основен камък бе положен през 1550 под ръководството на главния архитект Мимар Синан, бе замислен като голям социален комплекс, състоящ се освен от джамията и от медресета, darüşşifa, imaret и библиотека. Строежът бе една от най-големите строителни програми, символизиращи мощта на царуването на Законодателя и благоустройството на Истанбул.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Започна нова чумна вълна в Истанбул и околностите му", "547d6bf6"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Tâun една от епидемиите на XVI в., засегнали ислямския свят, се прояви между 1552 и 1566 и бе особено силна в Истанбул, Анадола, Румелия, Египет и Северна Африка. Разширяващите се търговски пътища и нарасналата подвижност на населението се смятат за фактори, улеснили разпространението на епидемиите през най-силния период на империята.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Paşa бе назначен за велик везир", "a7d7748e"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Kara Ahmed Paşa, Kara Ahmed Paşa, служещ като втори везир, бе издигнат до велик везир на 27 Шевал 960 (5 октомври 1553) след внезапното отстраняване на тогавашния велик везир. Тази промяна сочи към период, съвпадащ с екзекуцията на Шехзаде Мустафа, в който силовите равновесия вътре в двореца бързо смениха ръцете си.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Капудан пашата Пири Рейс бе екзекутиран", "3b2ad7a0"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Pîrî Reis, когато в Египет стигнаха обвиненията, че при вдигането на обсадата на Ормуз е ограбил имуществото на мюсюлманите срещу подкуп и е изоставил армията си на бойното поле, прочутият мореплавател и картограф бе екзекутиран в Кайро в края на 960 (края на 1553). Смъртта на Pîrî Reis, чието имущество бе конфискувано, се оценява като последица от съперничеството между пашите в морската политика на Басра и Индийския океан по онова време.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Paşa бе екзекутиран, Rüstem Paşa отново стана велик везир", "9a85076a"], "d": ["Според статиите на TDV İslâm Ansiklopedisi за Rüstem Paşa и Kara Ahmed Paşa на мястото на Kara Ahmed Paşa, внезапно екзекутиран по време на заседание на дивана на 13 Зилкаде 962 (29 септември 1555), Rüstem Paşa бе назначен същия ден за втори път за велик везир с подкрепата на султанките Хюрем и Mihrimah. Задкулисната страна на събитието е оставена неясна в източниците и е оценена като последица от дворцови интриги.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Хюрем Султан умря", "1ae998b5"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Hürrem Sultan Хюрем Султан, която като хасеки султан на Законодателя години наред имаше голямо влияние в двореца, умря в Истанбул на 26 Джумадилахир 965 (15 април 1558) и бе погребана в тюрбето си в комплекса на джамията Сюлеймание. След смъртта на Vâlide Sultan Hafsa през 1534 смъртта на Хюрем Султан, укрепила авторитета си над харема, премахна и уравновесяващото влияние пред съперничеството за трона между синовете ѝ Баязид и Селим.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokullu Mehmed Paşa се издигна до велик везир", "896391a2"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Sokullu Mehmed Paşa, Sokullu Mehmed Paşa, който се издигна до велик везир със смъртта на Semiz Ali Paşa на 30 Зилкаде 972 (29 юни 1565), стана последният велик везир на Законодателя и, като продължи на тази длъжност и при Селим II и Мурад III, стана един от най-дълго служилите велики везири в османската история.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Селим II стигна Истанбул и се възкачи на трона", "0289ef97"], "d": ["След смъртта на султан Сюлейман Законодателя при Сигетвар вестта бе държана седмици наред в тайна от Sokullu Mehmed Paşa, за да не се наруши редът. Според TDV İslâm Ansiklopedisi Selânikî дава датата на пристигането на Селим в Истанбул като 15 Рабиулевел 974 (30 септември 1566), докато повечето съвременни историци смятат за вярна 9 Рабиулевел (24 септември). Смъртта на Законодателя бе официално обявена в Белград едва на 24-25 октомври 1566", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Флотът, възстановен от Kılıç Ali Paşa, бе спуснат във водата", "d0fc9f48"], "d": ["След тежкото поражение при Лепанто (7 октомври 1571) през цялата зима се строяха кораби в корабостроителниците. Според TDV İslâm Ansiklopedisi на 1 Сафер 980 (13 юни 1572) новият флот, състоящ се от 250 галери и около 300 доброволни реиси, бе спуснат във водата с демонстрация на сила.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokullu Mehmed Paşa бе убит при покушение", "6ffa8dec"], "d": ["Sokullu Mehmed Paşa, който бе велик везир четиринадесет години през царуването на трима падишаха, бе убит с кама на 20 Şâban 987 (12 октомври 1579) от един дервиш, който се приближи към следобедния диван в конака му, сякаш за да подаде молба. Според TDV İslâm Ansiklopedisi се обсъжда дали покушението е свързано с отмъщението за екзекутирания шейх на Hamzaviyye Hamza Bâlî.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Първата търговска ahidnâme с Англия — на англичаните бяха дадени капитулации", "59c8e3ee"], "d": ["Английският представител William Harborne, изпратен в Истанбул през октомври 1578, получи от Мурад III ahidnâme от 1580 с подкрепата на Sokullu Mehmed Paşa и Hoca Sâdeddin Efendi. С тази ahidnâme английските търговци придобиха право да се ползват в същата степен от търговските привилегии (капитулации), давани преди това на французите и венецианците. Между кралица Елизабет I и Мурад III бяха разменени писма и бе установена и официална връзка между двете държави. Непосредствено след тези привилегии през 1581 в Лондон бе основана Levant Company; англичаните водеха търговията си в областта чрез тази компания до 1825", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Истанбулската обсерватория бе разрушена с hatt-ı hümâyun", "3bc0c78c"], "d": ["Под влияние на фетвата, че обсерваториите носят нещастие на страните, и на опозицията в двореца с hatt-ı hümâyun от 4 Зилхидже 987 (22 януари 1580) Истанбулската обсерватория бе разрушена заедно с всички инструменти в нея. Според TDV İslâm Ansiklopedisi това бе краткотрайният край на институцията, основана от Takıyyüddin er-Râsıd.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Започна сватбата по случай обрязването на Шехзаде Мехмед на Atmeydanı", "c2926d5d"], "d": ["Синът на Мурад III Шехзаде Мехмед бе обрязан с великолепни церемонии, започнали на 6 Джумадилевел 990 (29 май 1582) и продължили петдесет и шест-петдесет и седем дни. Според TDV İslâm Ansiklopedisi тържествата, устроени на Atmeydanı, бяха едни от най-великолепните дворцови празненства на епохата.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Nurbânû Vâlide Sultan умря", "77d0a577"], "d": ["Майката на Мурад III Nurbânû Sultan умря на 22 Зилкаде 991 (7 декември 1583). Според TDV İslâm Ansiklopedisi като валиде султан тя бе водила кореспонденция с дворовете на Венеция и Франция и венецианският сенат същата година бе приел да ѝ изпрати в знак на признателност за услугите ѝ подарък на стойност 2000 венециански златни.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Избухна Beylerbeyi Vak'ası заради обезценения акче", "db2f2e61"], "d": ["Когато държавата плащаше, като намалява дела на среброто в акчето, спахиите и еничарите обкръжиха двореца и вдигнаха кървав бунт, останал в историята под името Beylerbeyi Vak'ası. Според статията на TDV İslâm Ansiklopedisi за Abdülkadir Şeyhî Efendi шейхюлисламът бе отстранен вследствие на това събитие.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Мехмед III се възкачи на трона, деветнадесет шехзаде бяха удушени", "2cd9a8c5"], "d": ["Мехмед III, при смъртта на баща си Мурад III, стигна Истанбул и се възкачи на трона в петък на 16 Джумадилевел 1003 (27 януари 1595). Според TDV İslâm Ansiklopedisi същата нощ деветнадесет шехзаде, четирима от които възрастни (Mustafa, Bayezid, Osman и Abdullah), бяха удушени; това бе най-многобройното братоубийство в османската история.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan спечели влияние като валиде султан", "000bec21"], "d": ["Съпругата на Мурад III и майка на Мехмед III Safiye Sultan с възкачването на сина си се издигна до решаващо положение в дворцовата политика като валиде султан. Според TDV İslâm Ansiklopedisi в този период влиянието, произтичащо от харема, достигна измерението на пряка намеса в държавните работи.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Мехмед III потегли лично на поход под натиска на еничарите", "d3c50656"], "d": ["Въпреки противопоставянето на великия везир Damad İbrahim Paşa, под натиска на еничарите Мехмед III потегли от Истанбул на поход на 20 юни 1596 като първия падишах след Сюлейман Законодателя, застанал лично начело на армията. Според TDV İslâm Ansiklopedisi това означаваше съживяване на старата традиция на gazâ.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Чумната епидемия, започнала през 1570-те години, продължаваше да засяга Истанбул", "eb4ca37a"], "d": ["Според статията на TDV İslâm Ansiklopedisi за tâun епидемията, започнала през 1570-те години, продължи да оказва влияние до началото на XVII в. и порази преди всичко Истанбул, но също Анадола, Балканите, Египет и Северна Африка. Периодите на епидемия представляваха хронична заплаха, често прекъсваща дворцовия и градския живот.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Karayazıcı Abdülhalim умря, бунтовното движение отслабна", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, който се оттегли ранен след тежкото поражение при Sepetli близо до Elbistan на 12 август 1601, умря през 1010 (1602). Според TDV İslâm Ansiklopedisi вестта за смъртта стигна Истанбул през рамазана на 1010 (февруари-март 1602); източниците посочват, че е спорно дали смъртта му е последица от раната, или е настъпила от собствените му хора.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Фактическият край на традицията на братоубийството", "9046c607"], "d": ["При възкачването си Ахмед I, за разлика от предишните падишаси, не уби брат си Шехзаде Мустафа и му пощади живота; това решение се смята за началото на фактическото възприемане на реда ekber-erşed в османската система на наследяване. Статията на TDV İslâm Ansiklopedisi „Mustafa I“ съобщава, че Мустафа след тази дата води живот в дворцовия mahfil. Практиката сложи фактически край на убийствата при възкачване, продължаващи векове.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Положен бе основният камък на джамията Султанахмед", "1683262f"], "d": ["По заповед на Ахмед I основният камък на джамията, която щеше да построи архитектът Sedefkâr Mehmed Ağa, бе положен тържествено на Atmeydanı. Според статията на TDV İslâm Ansiklopedisi „Sultan Ahmed Camii ve Külliyesi“ сградата бе обект и на критики на епохата с това, че бе първата голяма selâtin camii, построена пряко от хазната без победа в завоевание. Комплексът бе замислен така, че освен джамията да включва медресе, imaret и тюрбе.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Убийството на Млади Осман от еничарите (Hâile-i Osmâniye)", "324f6582"], "d": ["Въстаналите еничари и спахии, поради слуховете, че под предлог за хадж излиза извън Истанбул и планира да разпусне еничарския оджак, свалиха Осман II от трона и го удушиха в занданите на Йедикуле. Според статията на TDV İslâm Ansiklopedisi „Osman II“ това събитие е първият случай в османската история, в който падишах е убит открито с военен бунт, и създаде дълбок пречупващ момент в отношенията между династията и войската. Последните му часове минаха така: след като опитът да се скрие в конака на еничарския ага Ali Ağa не даде резултат, падишахът бе качен, по израза на TDV, „по ужасен начин, с открита глава, в разпуснато състояние“ на кон и под тежки обиди отведен първо в Orta Cami, където се намираше Мустафа I, а следобед на същия ден в Йедикуле; според някои историци, за да се докаже смъртта му, ушите и носът му били отрязани и показани на майката на Мустафа I. След събитието Мустафа I бе възкачен на трона за втори път. Събитието, наричано „Hâile-i Osmâniye“ (бедствието на Осман), трайно наруши равновесието дворец-оджак и започна споровете за легитимност, продължили цял век.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Възкачването на Мустафа I на трона за втори път", "34a0b29a"], "d": ["След убийството на Млади Осман от еничарите, тъй като в династията нямаше друг възрастен мъж, Мустафа I бе възкачен на трона за втори път. Според статията на TDV İslâm Ansiklopedisi „Mustafa I“ и това второ султанство, също както първото, мина, без да може фактически да управлява държавните работи, и управлението на държавата остана в ръцете на везирите и валиде султан. Този период, продължил четиринадесет месеца, приключи през 1623 с възкачването на Мурад IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Пожарът в Cibali", "3e42fb08"], "d": ["Пожарът, избухнал в Cibali и бързо разпространил се под влияние на вятъра, превърна в пепел голяма част от Истанбул; според статията на TDV İslâm Ansiklopedisi „İstanbul“ източниците на епохата съобщават, че са изгорели хиляди домове. Свързването на пожара с дървената жилищна тъкан и тютюнопушенето стана пряк мотив за строгата забрана на тютюна и кафенетата, която Мурад IV щеше да обяви малко по-късно. Бедствието бе само един от повтарящите се големи пожари в Истанбул на епохата.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Забраната на тютюна и кафенетата от Мурад IV", "5dd71297"], "d": ["След пожара в Cibali, от съображения за пожарна безопасност и обществен ред, Мурад IV забрани тютюнопушенето и кафенетата; на нарушителите на забраната бяха налагани тежки наказания, включително смъртно наказание. Според статията на TDV İslâm Ansiklopedisi „Murad IV“ падишахът провеждаше толкова строга политика на вътрешна дисциплина, че лично обикаляше улиците на града, преоблечен, за да следи за забраната. Тези строги мерки се оценяват като част от усилията на Мурад IV да установи отново централния авторитет.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Чумна епидемия в Истанбул", "f33f58c5"], "d": ["През времето на Мурад IV Истанбул бе разтърсен от тежка чумна епидемия, засегнала значителна част от населението; градската търговия и ежедневният живот бяха нарушени с месеци. Статията на TDV İslâm Ansiklopedisi „İstanbul“ отбелязва, че повтарящите се епидемии през XVII в. сериозно са повлияли на демографското равновесие на града. По време на епидемията дворът и елитът са се преместили за известно време в градини и павилиони извън града.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Полетът с криле на Hezarfen Ahmed Çelebi (предание)", "df474c04"], "d": ["Според преданието, предадено от Евлия Челеби, Hezarfen Ahmed Çelebi успял с направени от него криле да се хвърли от Галатската кула и да се рее чак до Üsküdar; макар историческата му достоверност да е спорна, станал символ на техническото въображение. Падишахът, който в началото възнаградил Hezarfen, по-късно, поради отзвука, който събитието предизвикало, го заточил в Алжир.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Спечелването на влияние в двореца от Cinci Hoca Hüseyin Efendi", "41d21572"], "d": ["Знахарят Hüseyin Efendi, повикан в двореца, за да лекува душевните страдания на падишаха İbrahim, скоро спечели доверието на падишаха и се издигна до анадолски казаскер. Според статията на TDV İslâm Ansiklopedisi „Hüseyin Efendi, Cinci Hoca“ той използва това влияние за трупане на богатство и за намеса в политическите събития на епохата. След смъртта на İbrahim бе отстранен от всичките си длъжности и екзекутиран през 1648", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Екзекуцията на Kemankeş Mustafa Paşa", "0ecc8030"], "d": ["Kemankeş Mustafa Paşa, велик везир от времето на Мурад IV, който със своите финансови реформи донесе на хазната значителен излишък, бе екзекутиран чрез удушаване, след като дворцовите му съперници повлияха на İbrahim и бе обвинен, че е вдигнал еничарски бунт. Според статията на TDV İslâm Ansiklopedisi „Kemankeş Mustafa Paşa“ екзекуцията му се състоя на 21 Зилкаде 1053 / 31 януари 1644: Kemankeş Kara Mustafa Paşa бе удушен от палача Kara Ali на Hocapaşa Çarşısı и погребан в собственото си тюрбе в Çarşıkapı. Смъртта му се споменава като поразителен пример за нестабилността на великото везирство на епохата и сложи край на краткия период на строги реформи.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Решението на дивана за похода срещу Крит и потеглянето на флота", "9076827e"], "d": ["В Divan-ı Hümayun бе решено да се предприеме голям поход срещу принадлежащия на Венеция остров Крит и османският флот под командването на капудан паша потегли от Истанбул към Крит. Според статията на TDV İslâm Ansiklopedisi „Girit“ това решение образува политическото начало на един продължителен период на обсада и война, който щеше да трае около двадесет и пет години. Започването на похода бе предизвикало широки обсъждания сред държавниците като най-голямото външнополитическо начинание на времето на İbrahim.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Възкачването на Мехмед IV на седемгодишна възраст", "a197a3bc"], "d": ["Веднага след свалянето на İbrahim синът му Мехмед, едва седемгодишен, бе възкачен на трона и стана падишах с титлата Мехмед IV. Според статията на TDV İslâm Ansiklopedisi „Mehmed IV“ толкова младото възкачване изостри борбата за влияние вътре в двореца между баба му Kösem Sultan и майка му Turhan Sultan. Тази борба за власт щеше да завърши през 1651 с убийството на Kösem Sultan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Реформата на Tarhuncu Ahmed Paşa за балансиран бюджет", "376fc7f2"], "d": ["Великият везир Tarhuncu Ahmed Paşa, за да преодолее финансовата криза, причинена от дългите военни години, приложи строга програма за икономии, включваща и дворцовите разходи, и изготви първия известен в османската история балансиран бюджет (tarhuncu lâyihası). Според статията на TDV İslâm Ansiklopedisi „Tarhuncu Ahmed Paşa“ тази реформа донесе на хазната значителен излишък, но създаде широко недоволство в дворцовите среди и висшата бюрокрация. Това недоволство щеше да завърши година по-късно с неговата екзекуция.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Çınar Vak'ası (Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Çınar Vak'ası еничари и спахии, върнали се без заплащане от похода на Крит, се вдигнаха на бунт в Истанбул и поискаха екзекутирането на държавници, които обвиняваха в корупция. Предложението на великия везир Zurnazen Mustafa Paşa за конфискация и заточение не бе прието; първо трима чиновници, а след това около тридесет държавници бяха екзекутирани и труповете им бяха обесени по чинарите на площад Султанахмед. Затова събитието бе наречено Çınar Vak'ası.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Назначаването на Köprülü Mehmed Paşa за велик везир при условия", "3a6b7f8f"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Köprülü Mehmed Paşa, Köprülü Mehmed Paşa, наближаващ осемдесетте, прие печата едва след като накара Vâlide Turhan Sultan и Мехмед IV да приемат тежките условия, които им представи — да не се намесват в назначенията му и да не вярват на казаното против него. На 26 Зилкаде 1066 пое длъжността на мястото на Boynueğri Mehmed Paşa и пристъпи към строго възстановяване на държавната дисциплина.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Потушаването на движението на Kadızâdeliler от Köprülü Mehmed Paşa", "5ec3ce84"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Kadızâdeliler Köprülü Mehmed Paşa веднага след като пое длъжността се зае с религиозния конфликт между обкръжението на Kadızâde Mehmed Efendi и последователите на тарикатите. След консултация с улемите, макар да бе издал смъртна заповед за водачите на движението Üstüvânî Mehmed Efendi, Türk Ahmed и Divâne Mustafa, това наказание бе заменено със заточение и тримата бяха изпратени в Кипър; така втората фаза на движението приключи.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Голям пожар в Истанбул: изгарянето на Ağakapısı", "b9253b66"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Ağakapısı при големия пожар, избухнал през юли 1660 по времето на Мехмед IV, Ağakapısı, официалният щаб на еничарския ага, изгоря напълно и след това бе построен отново. Този пожар бе един от големите градски пожари, поразявали многократно Истанбул на епохата.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Назначаването на Köprülüzâde Fâzıl Ahmed Paşa за велик везир", "c1999b5c"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Köprülüzâde Fâzıl Ahmed Paşa със смъртта на баща му Köprülü Mehmed Paşa бе назначен за велик везир на 8 Рабиулевел 1072 (1 ноември 1661). За разлика от баща си, известен като кротък, набожен и покровител на учени и творци, Fâzıl Ahmed Paşa през великото си везирство, продължило повече от петнадесет години, основа библиотеки и благотворителни институции в Истанбул и в завладените земи.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Назначаването на Vânî Mehmed Efendi за проповедник в Yeni Cami и за наставник на падишаха", "7ea6aaae"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Mehmed Efendi, Vânî Vânî Mehmed Efendi, повикан в Истанбул със станането на Köprülüzâde Fâzıl Ahmed Paşa велик везир и представен на Мехмед IV, скоро спечели близкия интерес на падишаха. През 1665 бе назначен за проповедник в Yeni Cami и за наставник на падишаха и стана един от най-влиятелните духовници на двореца.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Назначаването на Merzifonlu Kara Mustafa Paşa за велик везир", "3d1e836c"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Merzifonlu Kara Mustafa Paşa със смъртта на Fâzıl Ahmed Paşa бе назначен за велик везир на 28 Şâban 1087 (5 ноември 1676). Като зет и възпитаник на рода Köprülü и с дълъг опит в държавното управление, Merzifonlu стана един от най-силните и влиятелни велики везири на Мехмед IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Смъртта на Vânî Mehmed Efendi в изгнание", "cda714aa"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Mehmed Efendi, Vânî Vânî Mehmed Efendi, смятан за един от главните, които накараха падишаха да приеме похода срещу Виена, след като походът завърши с разгром бе опозорен под натиска на общественото мнение и заточен в градчето Kestel край Бурса. Там умря на 14 Зилкаде 1096 (12 октомври 1685) и бе погребан във входа на построената от него джамия.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Назначаването на Köprülüzâde Fâzıl Mustafa Paşa за велик везир и финансовите му реформи", "b048570e"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Köprülüzâde Fâzıl Mustafa Paşa Fâzıl Mustafa Paşa, назначен за велик везир на 11 Мухарем 1101 (25 октомври 1689), преустрои реда на събиране на джизя според шериатските основи, води борба с инфлацията на mangır и укрепи хазната, като пренасочи ресурси от дворцовите институции. Освен това подсили провинциалното управление с надеждни служители и създаде местни съвети, подобни на централния диван.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Влизането в сила на системата malikâne", "316b8426"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Mâlikâne през последната четвърт на XVII в. нарастването на военните разходи и намаляването на приходите вследствие на загубите на земи вкараха хазната в тежка финансова криза. В системата malikâne, влязла в сила през 1106 (1695) г., на мултезимите бе дадено доживотно право на постоянен данък и вместо краткосрочната експлоатация бе въведен стимул за опазване на производството.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Възкачването на Мустафа II", "b53656c7"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Mustafa II Мустафа II, възкачил се на трона на тридесет и една години, обяви султанството си, без да чака одобрението на великия везир и шейхюлислям; церемонията по препасването на меча се състоя няколко дни по-късно в Eski Cami. Падишахът, възкачил се в период, когато след разгрома при Виена продължаваха войните на много фронтове, остана последният османски султан, потеглил лично на поход.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Назначаването на Feyzullah Efendi за шейхюлислям за втори път", "1cf14cff"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Feyzullah Efendi, Seyyid след възкачването на Мустафа II Feyzullah Efendi бе назначен за втори път за шейхюлислям на 11 Шевал 1106 (25 май 1695). Влиянието му над падишаха нарастваше постепенно през този период на длъжността, продължил повече от осем години.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Назначаването на синовете на Feyzullah Efendi на високи длъжности и натрупването на реакция", "a6398280"], "d": ["Според статията на TDV İslâm Ansiklopedisi за Feyzullah Efendi, Seyyid шейхюлисламът получи от Мустафа II безпрецедентен ферман, че синът му Fethullah Efendi ще стане шейхюлислям след него, и настани роднините си на висши длъжности в млада възраст. Тези практики създадоха широко недоволство сред илмийския клас, войската и жителите на Истанбул; съчетани със слуховете, че столицата ще бъде преместена в Одрин, те подготвиха почвата за Одринските събития от 1703 (Edirne Vak'ası).", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Започването на Одринските събития (Edirne Vak'ası)", "5a106458"], "d": ["Според статията на TDV „Edirne Vak'ası“ движението, започнало с бунта на войници, неполучили заплатите си, скоро прерасна в широк бунт с участието на еничари, медресе-студенти, занаятчии и население. Главната цел на бунта бе шейхюлисляма Feyzullah Efendi, обвиняван в прекомерна намеса в държавните дела. Тълпа от около 60 000 души тръгна от Истанбул към Одрин.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Великото везирство на Nevşehirli Damad İbrahim Paşa", "8d627a6f"], "d": ["Според статията на TDV „Damad İbrâhim Paşa, Nevşehirli“, по време на продължаващите мирни преговори с Австрия той бе назначен на 8 Джумадилахир 1130 (9 май 1718) на длъжността велик везир и веднага след назначаването се насочи към преговорите, които щяха да сложат край на войната; два месеца по-късно бе подписан Пожаревацкият мир (21 юли 1718). По думите на TDV „искаше да се занимава със социални и финансови въпроси, жадуваше за мирен период, който да накара да бъдат забравени войните, години наред завършвали с поражение“. С реформи във финансите намали заплатите на войниците и създаде значителен излишък в държавната хазна. Великото му везирство, което щеше да продължи дванадесет години, образува политическата рамка на епохата, носеща името му (Епохата на лалето).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Основаването на Tulumbacı Ocağı", "f58b0d97"], "d": ["Според статията на TDV „Tulumbacı“, след успеха, който Gerçek Dâvud, върнал се от похода в Морея през 1715, показа с tulumba при пожарите в Истанбул, великият везир Nevşehirli Damad İbrahim Paşa го натовари да създаде официален пожарникарски оджак. Оджакът, основан в Acemi Oğlanları Kışlası с шест офицери и петдесет нефери, достигна 150 души през 1724 и 461 през 1755 Dâvud остана начело на оджака до смъртта си през 1733", "3b860f0f"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Строежът на Sâdâbâd Kasrı", "aec9c65e"], "d": ["Според статията на TDV „Sâdâbâd“ по бреговете на дерето Kağıthane бе построен голям комплекс за забавления и разходки, състоящ се от дворец, вдъхновен от френската дворцова архитектура, канал, чешми и павилиони. Sâdâbâd, станал най-предпочитаното място за забавления на епохата, бе увековечен в стиховете на поета Nedîm. Комплексът бе до голяма степен разрушен по време на бунта на Patrona Halil през 1730", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Руските сили превземат Дербент: Каспийският поход на Петър I", "c2b269f9"], "d": ["Докато държавата на Сефевидите е въвлечена във вътрешни размирици от афганистанското нашествие, руският цар Петър I предприема поход, за да завземе иранските земи по Каспийското крайбрежие; крайбрежният град Дербент се предава на руските сили без значителна съпротива. Според статията Derbend в TDV İslâm Ansiklopedisi тази окупация е началото на временно руско господство, което ще продължи тринайсет години; Османската държава също се възползва от същите размирици и се насочва към западната част на Кавказ. Армията е стигнала от Астрахан по море до залива Agrahan, а оттам по суша покрай брега през Tarku; шамхалът на Tarku приема Петър като гост и преминава под руско подчинение.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Премахването на шамхалството Tarku: пряко руско управление", "b0f029c6"], "d": ["Шамхалът на Tarku Adil-Girey, който през 1722 приема Петър като гост и преминава под руско подчинение, се вдига на бунт през 1725; Yeropkin разрушава Tarku през есента на 1725, шамхалът е арестуван и заточен в средата на май 1726 и шамхалството е премахнато. Tarku и околностите му остават под пряко руско управление до Гянджинския договор от 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Разрешението на İbrahim Müteferrika за основаване на печатница", "0659dd0a"], "d": ["Според статията на TDV „İbrâhim Müteferrika“ с фермана на Ахмед III и фетвата на шейхюлислям Yenişehirli Abdullah Efendi бе разрешено основаването на първата турска печатница. Печатницата започна да действа в квартал Yavuzselim в Истанбул. Müteferrika до смъртта си през 1747 отпечата седемнадесет произведения в двадесет и три тома.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Завършването на първата печатна книга Vankulu Lügati", "684700e8"], "d": ["Според статията на TDV „İbrâhim Müteferrika“ турският превод на Sıhâhu'l-Cevherî (Vankulu Lügati), първото произведение на печатницата, бе завършен в началото на 1729 Това бе първата книга, отпечатана с арабски букви в османските земи, и се смята за началото на историята на турското печатарство.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Екзекуцията на Nevşehirli Damad İbrahim Paşa", "50c64341"], "d": ["Според статията на TDV „Damad İbrâhim Paşa, Nevşehirli“ тялото на великия везир, убит в двореца по време на бунта на Patrona Halil, бе влачено по улиците на Истанбул и оставено близо до Чешмата на Ахмед III на площад Султанахмед. Дванадесетгодишното му велико везирство и Епохата на лалето така приключиха по кървав начин.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Абдикацията на Ахмед III, възкачването на Махмуд I", "a43f5d40"], "d": ["Според статията на TDV „Mahmud I“, пред натиска на бунтовниците Ахмед III, като си осигури гаранции за себе си и децата си, абдикира и лично възкачи на трона племенника си Шехзаде Махмуд. Махмуд I, седнал на трона със съвета на чичо си „вземи държавните работи в ръцете си, не се доверявай на никого“, като първо дело се зае да пречупи влиянието на бунтовническата групировка, която го бе възкачила.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Преустройството на артилерийския оджак от Humbaracı Ahmed Paşa", "ea3a7c64"], "d": ["Според статията на TDV „Humbaracı“ офицерът от френски произход Ahmed Paşa, преминал в исляма, по време на великия везир Hekimoğlu Ali Paşa се зае с преустройството по европейски образец на организацията на humbaracı със заплати. Създаде нова структура от 601 души, пряко подчинена на великия везир, от които 300 с заплата и 301 с timar. С технологията на епохата накара да бъдат произведени 100 хаубици и 50 000 гюлета.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Основаването на Hendesehâne (първият образец на инженерно училище)", "a77ed1f3"], "d": ["Според статията на TDV „Mahmud I“ Humbaracı Ahmed Paşa основа в Üsküdar Hendesehâne, наричана още Humbarahâne, и даде военно обучение, основано на математика и геометрия, на ученици, избрани сред дворцовите служители и bostancı. Тази институция се смята за първия образец на инженерните училища, които щяха да се развият в следващия период.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Гянджинският договор: връщането на Дербент и Баку на Иран", "ff19d531"], "d": ["Русия, която търси съюз с Иран срещу османската заплаха, с Гянджинския договор връща градовете по Каспийското крайбрежие, държани от нея от тринайсет години, на Иран под командването на Надир хан (още не приел титлата шах). Според статията Derbend в TDV İslâm Ansiklopedisi това изтегляне е резултат от нежеланието на Русия да воюва на юг едновременно на два фронта (срещу Османската държава и Иран) и затвърждава военния авторитет на Надир, който проправя пътя към възкачването му на трона след няколко години. Tarki (Tarku) под руско управление също се връща на иранска страна с това изтегляне (на картата се използва денят на Гянджа). Salyan и Şâbüran под руско управление също се връщат на иранска страна с това изтегляне (специфичен за селищата ден в източника няма, на картата се използва денят на Гянджа — декларирано приблизително).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Възкачването на Надир шах на трона в степта Мугань: фактическият край на династията на Сефевидите", "4f640979"], "d": ["Според статията Nadir Şah в TDV İslâm Ansiklopedisi курилтаят от около двайсет хиляди души, събран в степта Мугань, настоятелно поискал той да застане начело на Иран; Надир приема предложението при условие да се откажат от крайното шиитско учение, станало причина за войните между Сефевидите и османците, и да се възприеме умереният джафаритски мазхаб, и на 24 Шевал 1148 (8 март 1736) се възкачва на трона с титлата Надир шах. Това означава фактическия край на двувековната династия на Сефевидите и основаването на династията на Афшарите.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Започването на чумната епидемия в Истанбул", "9fa82b56"], "d": ["Според статията на TDV „Tâun“ чумната епидемия, действала в ислямската география между 1739 и 1743, порази през този период и Истанбул. Статията отбелязва, че епидемиите през XVIII в. са протичали сравнително по-леко от предишните векове. Сред периодите на епидемии се броят и 1713, 1719, 1728-1729 и 1759-1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Пожарът Hocapaşa", "321c7d0d"], "d": ["Според статията на TDV „Fatma Sultan Camii“ пожарът Hocapaşa, избухнал през нощта, опустоши Bâbıâli и околностите му; предполага се, че и джамията Fatma Sultan в района е пострадала от този пожар. Това бедствие, един от големите пожари, поразявали Истанбул по времето на Осман III, причини тежки разрушения в търговския и административния център на града.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Великото везирство на Koca Ragıp Mehmed Paşa", "a1846910"], "d": ["Ragıp Paşa, известен като поет и дипломат, бе назначен от Осман III на длъжността велик везир (след смъртта на Осман III през октомври 1757 продължи на длъжност и получи нов печат от Мустафа III). Докато продължаваха Седемгодишните войни, той следваше балансирана външна политика, която държеше Османската държава извън конфликтите в Европа. През великото си везирство, което щеше да продължи шест години, отдели значение и на културни дейности като основаването на библиотека.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Смъртта на Ragıp Paşa", "6bc19323"], "d": ["Ragıp Paşa умря след шестгодишното си велико везирство. Със смъртта му приключи най-дълготрайното и балансирано велико везирство от времето на Мустафа III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Голямото Истанбулско земетресение и разрушаването на джамията на Завоевателя", "2475b4dc"], "d": ["Според статията на TDV „Fâtih Camii ve Külliyesi“ при голямото земетресение от 1766 главният купол на джамията рухна напълно, стените бяха повредени до степен, в която не можеха да бъдат поправени. По заповед на Мустафа III възстановяването, започнало през 1767 под ръководството на архитектите Sarım İbrahim Efendi и İzzet Mehmed Bey, бе завършено през 1771 с нов проект, различен от стария план.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Краткотрайен опит за артилерийско училище под ръководството на барон de Tott", "4192260c"], "d": ["Според статията на TDV „Mühendishâne-i Bahrî-i Hümâyun“ неуспехите в османско-руската война от 1768 показаха нуждата от техническо военно обучение; краткотрайното артилерийско училище, открито с приноса на френския офицер Baron de Tott, започна да действа през октомври 1772, но остана безрезултатно. Този опит се смята за предшественик на Mühendishâne-i Bahrî-i Hümâyun, която щеше да бъде основана през 1775", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Селим III се възкачи на трона", "00d046d9"], "d": ["След смъртта на Абдюлхамид I племенникът му Селим III се възкачи на трона. Според статията на TDV İslâm Ansiklopedisi за Selim III новият падишах, който от времето си като шехзаде се интересуваше от преустройството на европейските армии, скоро след възкачването си започна да подготвя програма за коренно обновление. Тази програма в рамките на няколко години щеше да бъде наречена Nizâm-ı Cedîd.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Започна подготовката на реформаторската програма Nizâm-ı Cedîd", "eff78a68"], "d": ["Селим III нареди да бъде подготвена обширна програма за обновление в съответствие с проекти (lâyiha), поискани от държавните сановници и чуждестранни специалисти. Според статията на TDV İslâm Ansiklopedisi за Nizâm-ı Cedîd тази програма не се ограничи само със създаването на нова армия; тя прерасна в широко реформаторско движение, обхващащо финансите, провинциалното управление и дипломацията. През следващите петнадесет години програмата щеше да намери както поддръжници, така и противници.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Бяха основани постоянни посолства в европейските столици", "2e9dc8a1"], "d": ["Селим III за пръв път в историята на Османската държава изпрати постоянни посланици, които да служат непрекъснато в големите европейски центрове. Според статията на TDV İslâm Ansiklopedisi за Elçi тази стъпка придаде на османската дипломация, водена дотогава само с временни и еднократни мисии, трайна организация. Основната задача на новите посолства бе да съобщават редовно на Истанбул за политическите и военните събития в Европа.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Бе основана хазната İrad-ı Cedîd", "ae5c8ce2"], "d": ["За покриване на разходите на армията Nizâm-ı Cedîd и на реформаторската програма бе основана отделна хазна. Според статията на TDV İslâm Ansiklopedisi за Esham сред приходите на новата хазна бяха пряката експлоатация на някои mukataa от държавата и поставянето на продажбите на esham под контрол. Тази уредба бе опит да се създаде нов източник извън традиционната финансова система.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Започна бунтът на Kabakçı Mustafa", "b98eee17"], "d": ["Натрупаното недоволство срещу Nizâm-ı Cedîd избухна с бунта на войниците yamak под водачеството на Kabakçı Mustafa. Според статията на TDV İslâm Ansiklopedisi за Kabakçı İsyanı бунтовниците скоро завзеха контрола в Истанбул и поискаха главите на държавниците, поддръжници на Nizâm-ı Cedîd. Бунтът в рамките на няколко дни завърши със свалянето на Селим III от трона.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Селим III бе свален от трона", "ff2c30ec"], "d": ["Под натиска на бунта на Kabakçı Mustafa Селим III бе свален от трона с фетва, получена от шейхюлисляма. Според статията на TDV İslâm Ansiklopedisi за Selim III това решение бе моментът, в който осемнадесетгодишният период на реформи фактически приключи; и армията Nizâm-ı Cedîd бе разпусната скоро след това. Селим започна да бъде държан под стража в двореца Топкапъ.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Мустафа IV се възкачи на трона", "8f1ac86c"], "d": ["Веднага след свалянето на Селим III от трона племенникът му Мустафа IV бе провъзгласен за падишах. Според статията на TDV İslâm Ansiklopedisi за Mustafa IV новият падишах започна царуването си под влиянието на противниците на Nizâm-ı Cedîd, подкрепили бунта. Този кратък период бе етап на нестабилност, в който централният авторитет значително отслабна.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Paşa влезе в Истанбул с армията си", "0cad3dea"], "d": ["Русчукският аян Alemdar Mustafa Paşa дойде с армията си пред Истанбул, за да възкачи Селим III отново на трона. Според статията на TDV İslâm Ansiklopedisi за Alemdar Mustafa Paşa влизането му в града бе посрещнато лично от Мустафа IV; но в рамките на няколко дни силовото равновесие в двореца щеше да се промени напълно. Това влизане започна веригата от събития, завършила както със смъртта на Селим, така и с ново възкачване.", "c042d316"]}
});
